INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Rt', 3, 'pt', '[{"numero": 1, "texto": "E disse-lhe sua sogra Noemi: Filha minha, não tenho de buscar descanso a ti, para que fiques bem?"}, {"numero": 2, "texto": "Não é Boaz nosso parente, com cujas moças tu tens estado? Eis que ele aventa esta noite a os grãos de cevada."}, {"numero": 3, "texto": "Tu te lavarás, pois, e te ungirás, e vestindo-te tuas vestes, passarás à eira; mas não te darás a conhecer ao homem até que ele tenha acabado de comer e de beber."}, {"numero": 4, "texto": "E quando ele se deitar, repara tu o lugar de onde ele se deitará, e irás, e descobrirás os pés, e te deitarás ali; e ele te dirá o que tenhas de fazer."}, {"numero": 5, "texto": "E lhe respondeu: Farei tudo o que tu me mandares."}, {"numero": 6, "texto": "Desceu, pois à eira, e fez tudo o que sua sogra lhe havia mandado."}, {"numero": 7, "texto": "E quando Boaz havia comido e bebido, e seu coração esteve contente, retirou-se para dormir a um lado do amontoado. Então ela veio caladamente, e revelou os pés, e deitou-se."}, {"numero": 8, "texto": "E aconteceu, que à meia noite se estremeceu aquele homem, e apalpou: e eis que, a mulher que estava deitada a seus pés."}, {"numero": 9, "texto": "Então ele disse: Quem és? E ela respondeu: Eu sou Rute tua serva: estende a borda de tua capa sobre tua serva, porquanto és parente próximo."}, {"numero": 10, "texto": "E ele disse: Bendita sejas tu do SENHOR, filha minha; que fizeste melhor tua última bondade que a primeira, não indo atrás dos rapazes, sejam pobres ou ricos."}, {"numero": 11, "texto": "Agora, pois, não temas, filha minha: eu farei contigo o que tu disseres, pois que toda a porta de meu povo sabe que és mulher virtuosa."}, {"numero": 12, "texto": "E agora, ainda que seja certo que eu sou parente próximo, contudo isso há parente mais próximo que eu."}, {"numero": 13, "texto": "Repousa esta noite, e quando for de dia, se ele te redimir, bem, redima-te; mas se ele não te quiser redimir, eu te redimirei, vive o SENHOR. Descansa, pois, até a manhã."}, {"numero": 14, "texto": "E depois que repousou a seus pés até a manhã, levantou-se, antes que ninguém pudesse conhecer a outro. E ele disse: Não se saiba que tenha vindo mulher à eira."}, {"numero": 15, "texto": "Depois lhe disse: Aproxima o lenço que trazes sobre ti, e segura-o. E enquanto ela o segurava, ele mediu seis medidas de cevada, e as pôs às costas: e veio ela à cidade."}, {"numero": 16, "texto": "Assim que veio à sua sogra, esta lhe disse: Que houve, minha filha? E ela lhe declarou ela tudo o que com aquele homem lhe havia acontecido."}, {"numero": 17, "texto": "E disse: Estas seis medidas de cevada me deu, dizendo-me: Porque não vás vazia à tua sogra."}, {"numero": 18, "texto": "Então Noemi disse: Repousa, filha minha, até que saibas como a coisa se sucede; porque aquele homem não parará até que hoje conclua o negócio."}]'::jsonb, 'Almeida Livre'),
  ('Rt', 3, 'en', '[{"numero": 1, "texto": "Then Naomi her mother in law said unto her, My daughter, shall I not seek rest for thee, that it may be well with thee?"}, {"numero": 2, "texto": "And now is not Boaz of our kindred, with whose maidens thou wast? Behold, he winnoweth barley to night in the threshingfloor."}, {"numero": 3, "texto": "Wash thyself therefore, and anoint thee, and put thy raiment upon thee, and get thee down to the floor: but make not thyself known unto the man, until he shall have done eating and drinking."}, {"numero": 4, "texto": "And it shall be, when he lieth down, that thou shalt mark the place where he shall lie, and thou shalt go in, and uncover his feet, and lay thee down; and he will tell thee what thou shalt do."}, {"numero": 5, "texto": "And she said unto her, All that thou sayest unto me I will do."}, {"numero": 6, "texto": "And she went down unto the floor, and did according to all that her mother in law bade her."}, {"numero": 7, "texto": "And when Boaz had eaten and drunk, and his heart was merry, he went to lie down at the end of the heap of corn: and she came softly, and uncovered his feet, and laid her down."}, {"numero": 8, "texto": "And it came to pass at midnight, that the man was afraid, and turned himself: and, behold, a woman lay at his feet."}, {"numero": 9, "texto": "And he said, Who art thou? And she answered, I am Ruth thine handmaid: spread therefore thy skirt over thine handmaid; for thou art a near kinsman."}, {"numero": 10, "texto": "And he said, Blessed be thou of the Lord, my daughter: for thou hast shewed more kindness in the latter end than at the beginning, inasmuch as thou followedst not young men, whether poor or rich."}, {"numero": 11, "texto": "And now, my daughter, fear not; I will do to thee all that thou requirest: for all the city of my people doth know that thou art a virtuous woman."}, {"numero": 12, "texto": "And now it is true that I am thy near kinsman: howbeit there is a kinsman nearer than I."}, {"numero": 13, "texto": "Tarry this night, and it shall be in the morning, that if he will perform unto thee the part of a kinsman, well; let him do the kinsman''s part: but if he will not do the part of a kinsman to thee, then will I do the part of a kinsman to thee, as the Lord liveth: lie down until the morning."}, {"numero": 14, "texto": "And she lay at his feet until the morning: and she rose up before one could know another. And he said, Let it not be known that a woman came into the floor."}, {"numero": 15, "texto": "Also he said, Bring the vail that thou hast upon thee, and hold it. And when she held it, he measured six measures of barley, and laid it on her: and she went into the city."}, {"numero": 16, "texto": "And when she came to her mother in law, she said, Who art thou, my daughter? And she told her all that the man had done to her."}, {"numero": 17, "texto": "And she said, These six measures of barley gave he me; for he said to me, Go not empty unto thy mother in law."}, {"numero": 18, "texto": "Then said she, Sit still, my daughter, until thou know how the matter will fall: for the man will not be in rest, until he have finished the thing this day."}]'::jsonb, 'King James Version'),
  ('Rt', 3, 'fr', '[{"numero": 1, "texto": "Naomi, sa belle-mère, lui dit: Ma fille, je voudrais assurer ton repos, afin que tu fusses heureuse."}, {"numero": 2, "texto": "Et maintenant Boaz, avec les servantes duquel tu as été, n''''est-il pas notre parent? Voici, il doit vanner cette nuit les orges qui sont dans l''''aire."}, {"numero": 3, "texto": "Lave-toi et oins-toi, puis remets tes habits, et descends à l''''aire. Tu ne te feras pas connaître à lui, jusqu''''à ce qu''''il ait achevé de manger et de boire."}, {"numero": 4, "texto": "Et quand il ira se coucher, observe le lieu où il se couche. Ensuite va, découvre ses pieds, et couche-toi. Il te dira lui-même ce que tu as à faire."}, {"numero": 5, "texto": "Elle lui répondit: Je ferai tout ce que tu as dit."}, {"numero": 6, "texto": "Elle descendit à l''''aire, et fit tout ce qu''''avait ordonné sa belle-mère."}, {"numero": 7, "texto": "Boaz mangea et but, et son coeur était joyeux. Il alla se coucher à l''''extrémité d''''un tas de gerbes. Ruth vint alors tout doucement, découvrit ses pieds, et se coucha."}, {"numero": 8, "texto": "Au milieu de la nuit, cet homme eut une frayeur; il se pencha, et voici, une femme était couchée à ses pieds."}, {"numero": 9, "texto": "Il dit: Qui es-tu? Elle répondit: Je suis Ruth, ta servante; étends ton aile sur ta servante, car tu as droit de rachat."}, {"numero": 10, "texto": "Et il dit: Sois bénie de l''''Eternel, ma fille! Ce dernier trait témoigne encore plus en ta faveur que le premier, car tu n''''as pas recherché des jeunes gens, pauvres ou riches."}, {"numero": 11, "texto": "Maintenant, ma fille, ne crains point; je ferai pour toi tout ce que tu diras; car toute la porte de mon peuple sait que tu es une femme vertueuse."}, {"numero": 12, "texto": "Il est bien vrai que j''''ai droit de rachat, mais il en existe un autre plus proche que moi."}, {"numero": 13, "texto": "Passe ici la nuit. Et demain, s''''il veut user envers toi du droit de rachat, à la bonne heure, qu''''il le fasse; mais s''''il ne lui plaît pas d''''en user envers toi, j''''en userai, moi, l''''Eternel est vivant! Reste couchée jusqu''''au matin."}, {"numero": 14, "texto": "Elle resta couchée à ses pieds jusqu''''au matin, et elle se leva avant qu''''on pût se reconnaître l''''un l''''autre. Boaz dit: Qu''''on ne sache pas qu''''une femme est entrée dans l''''aire."}, {"numero": 15, "texto": "Et il ajouta: Donne le manteau qui est sur toi, et tiens-le. Elle le tint, et il mesura six mesures d''''orge, qu''''il chargea sur elle. Puis il rentra dans la ville."}, {"numero": 16, "texto": "Ruth revint auprès de sa belle-mère, et Naomi dit: Est-ce toi, ma fille? Ruth lui raconta tout ce que cet homme avait fait pour elle."}, {"numero": 17, "texto": "Elle dit: Il m''''a donné ces six mesures d''''orge, en disant: Tu ne retourneras pas à vide vers ta belle-mère."}, {"numero": 18, "texto": "Et Naomi dit: Sois tranquille, ma fille, jusqu''''à ce que tu saches comment finira la chose, car cet homme ne se donnera point de repos qu''''il n''''ait terminé cette affaire aujourd''''hui."}]'::jsonb, 'Louis Segond 1910'),
  ('Rt', 3, 'es', '[{"numero": 1, "texto": "Y DÍJOLE su suegra Noemi: Hija mía, ¿no te tengo de buscar descanso, que te sea bueno?"}, {"numero": 2, "texto": "¿No es Booz nuestro pariente, con cuyas mozas tú has estado? He aquí que él avienta esta noche la parva de las cebadas."}, {"numero": 3, "texto": "Te lavarás pues, y te ungirás, y vistiéndote tus vestidos, pasarás á la era; mas no te darás á conocer al varón hasta que él haya acabado de comer y de beber."}, {"numero": 4, "texto": "Y cuando él se acostare, repara tú el lugar donde él se acostará, é irás, y descubrirás los pies, y te acostarás allí; y él te dirá lo que hayas de hacer."}, {"numero": 5, "texto": "Y le respondió: Haré todo lo que tú me mandares."}, {"numero": 6, "texto": "Descendió pues á la era, é hizo todo lo que su suegra le había mandado."}, {"numero": 7, "texto": "Y como Booz hubo comido y bebido, y su corazón estuvo contento, retiróse á dormir á un lado del montón. Entonces ella vino calladamente, y descubrió los pies, y acostóse."}, {"numero": 8, "texto": "Y aconteció, que á la media noche se estremeció aquel hombre, y palpó: y he aquí, la mujer que estaba acostada á sus pies."}, {"numero": 9, "texto": "Entonces él dijo: ¿Quién eres? Y ella respondió: Yo soy Ruth tu sierva: extiende el borde de tu capa sobre tu sierva, por cuanto eres pariente cercano."}, {"numero": 10, "texto": "Y él dijo: Bendita seas tú de Jehová, hija mía; que has hecho mejor tu postrera gracia que la primera, no yendo tras los mancebos, sean pobres ó ricos."}, {"numero": 11, "texto": "Ahora pues, no temas, hija mía: yo haré contigo lo que tú dijeres, pues que toda la puerta de mi pueblo sabe que eres mujer virtuosa."}, {"numero": 12, "texto": "Y ahora, aunque es cierto que yo soy pariente cercano, con todo eso hay pariente más cercano que yo."}, {"numero": 13, "texto": "Reposa esta noche, y cuando sea de día, si él te redimiere, bien, redímate; mas si él no te quisiere redimir, yo te redimiré, vive Jehová. Descansa pues hasta la mañana."}, {"numero": 14, "texto": "Y después que reposó á sus pies hasta la mañana, levantóse, antes que nadie pudiese conocer á otro. Y él dijo: No se sepa que haya venido mujer á la era."}, {"numero": 15, "texto": "Después le dijo: Llega el lienzo que traes sobre ti, y ten de él. Y teniéndolo ella, él midió seis medidas de cebada, y púsoselas á cuestas: y vínose ella á la ciudad."}, {"numero": 16, "texto": "Así que vino á su suegra, ésta le dijo: ¿Qué pues, hija mía? Y declaróle ella todo lo que con aquel varón le había acontecido."}, {"numero": 17, "texto": "Y dijo: Estas seis medidas de cebada me dió, diciéndome: Porque no vayas vacía á tu suegra."}, {"numero": 18, "texto": "Entonces Noemi dijo: Reposa, hija mía, hasta que sepas cómo cae la cosa: porque aquel hombre no parará hasta que hoy concluya el negocio."}]'::jsonb, 'Reina-Valera 1909'),
  ('Rt', 4, 'pt', '[{"numero": 1, "texto": "E Boaz subiu à porta da cidade e sentou-se ali: e eis que passava aquele parente do qual havia Boaz falado, e disse-lhe: Ei, fulano, vem aqui e senta-te. E ele veio, e sentou-se."}, {"numero": 2, "texto": "Então ele tomou dez homens dos anciãos da cidade, e disse: Sentai-vos aqui. E eles se sentaram."}, {"numero": 3, "texto": "Logo disse ao parente: Noemi, que voltou do campo de Moabe, vende uma parte das terras que teve nosso irmão Elimeleque;"}, {"numero": 4, "texto": "E eu decidi fazê-lo saber a ti, e dizer-te que a tomes diante dos que estão aqui sentados, e diante dos anciãos de meu povo. Se houveres de redimir, redime; e se não quiseres redimir, declara-o a mim para que eu o saiba: porque não há outro que redima a não ser tu, e eu depois de ti. E ele respondeu: Eu redimirei."}, {"numero": 5, "texto": "Então replicou Boaz: O mesmo dia que tomares as terras da mão de Noemi, hás de tomar também a Rute moabita, mulher do defunto, para que suscites o nome do morto sobre sua possessão."}, {"numero": 6, "texto": "E respondeu o parente: Não posso redimir por minha parte, porque lançaria a perder minha propriedade: redime tu usando de meu direito, porque eu não poderei redimir."}, {"numero": 7, "texto": "Havia já de longo tempo este costume em Israel na remissão ou contrato, que para a confirmação de qualquer negócio, o um se tirava o sapato e o dava a seu companheiro: e este era o testemunho em Israel."}, {"numero": 8, "texto": "Então o parente disse a Boaz: Toma-o tu. E descalçou seu sapato."}, {"numero": 9, "texto": "E Boaz disse aos anciãos e a todo aquele povo: Vós sois hoje testemunhas de que tomo todas as coisas que foram de Elimeleque, e tudo o que foi de Quiliom e de Malom, da mão de Noemi."}, {"numero": 10, "texto": "E que também tomo por minha mulher a Rute moabita, mulher de Malom, para suscitar o nome do defunto sobre sua herança, para que o nome do morto não se apague dentre seus irmãos e da porta de seu lugar. Vós sois hoje testemunhas."}, {"numero": 11, "texto": "E disseram todos os do povo que estavam à porta com os anciãos: Testemunhas somos. O SENHOR faça à mulher que entra em tua casa como a Raquel e a Lia, as quais duas edificaram a casa de Israel; e tu sejas ilustre em Efrata, e tenhas renome em Belém."}, {"numero": 12, "texto": "E da semente que o SENHOR te der desta moça, seja tua casa como a casa de Perez, o que Tamar deu a Judá."}, {"numero": 13, "texto": "Então Boaz tomou a Rute, e ela foi sua mulher; e logo que entrou a ela, o SENHOR lhe deu que concebesse e desse à luz um filho."}, {"numero": 14, "texto": "E as mulheres diziam a Noemi: Louvado seja o SENHOR, que fez que não te faltasse hoje parente, cujo nome será nomeado em Israel."}, {"numero": 15, "texto": "O qual será restaurador de tua alma, e o que sustentará tua velhice; pois que tua nora, a qual te ama e te vale mais que sete filhos, o fez nascer."}, {"numero": 16, "texto": "E tomando Noemi o filho, o pôs em seu colo, e foi-lhe sua ama."}, {"numero": 17, "texto": "E as vizinhas dizendo, a Noemi nasceu um filho, lhe puseram nome; e chamaram-lhe Obede. Este é pai de Jessé, pai de Davi."}, {"numero": 18, "texto": "E estas são as gerações de Perez: Perez gerou a Hezrom;"}, {"numero": 19, "texto": "E Hezrom gerou a Rão, e Rão gerou a Aminadabe;"}, {"numero": 20, "texto": "E Aminadabe gerou a Naassom, e Naassom gerou a Salmom;"}, {"numero": 21, "texto": "E Salmom gerou a Boaz, e Boaz gerou a Obede;"}, {"numero": 22, "texto": "E Obede gerou a Jessé, e Jessé gerou a Davi."}]'::jsonb, 'Almeida Livre'),
  ('Rt', 4, 'en', '[{"numero": 1, "texto": "Then went Boaz up to the gate, and sat him down there: and, behold, the kinsman of whom Boaz spake came by; unto whom he said, Ho, such a one! turn aside, sit down here. And he turned aside, and sat down."}, {"numero": 2, "texto": "And he took ten men of the elders of the city, and said, Sit ye down here. And they sat down."}, {"numero": 3, "texto": "And he said unto the kinsman, Naomi, that is come again out of the country of Moab, selleth a parcel of land, which was our brother Elimelech''s:"}, {"numero": 4, "texto": "And I thought to advertise thee, saying, Buy it before the inhabitants, and before the elders of my people. If thou wilt redeem it, redeem it: but if thou wilt not redeem it, then tell me, that I may know: for there is none to redeem it beside thee; and I am after thee. And he said, I will redeem it."}, {"numero": 5, "texto": "Then said Boaz, What day thou buyest the field of the hand of Naomi, thou must buy it also of Ruth the Moabitess, the wife of the dead, to raise up the name of the dead upon his inheritance."}, {"numero": 6, "texto": "And the kinsman said, I cannot redeem it for myself, lest I mar mine own inheritance: redeem thou my right to thyself; for I cannot redeem it."}, {"numero": 7, "texto": "Now this was the manner in former time in Israel concerning redeeming and concerning changing, for to confirm all things; a man plucked off his shoe, and gave it to his neighbour: and this was a testimony in Israel."}, {"numero": 8, "texto": "Therefore the kinsman said unto Boaz, Buy it for thee. So he drew off his shoe."}, {"numero": 9, "texto": "And Boaz said unto the elders, and unto all the people, Ye are witnesses this day, that I have bought all that was Elimelech''s, and all that was Chilion''s and Mahlon''s, of the hand of Naomi."}, {"numero": 10, "texto": "Moreover Ruth the Moabitess, the wife of Mahlon, have I purchased to be my wife, to raise up the name of the dead upon his inheritance, that the name of the dead be not cut off from among his brethren, and from the gate of his place: ye are witnesses this day."}, {"numero": 11, "texto": "And all the people that were in the gate, and the elders, said, We are witnesses. The Lord make the woman that is come into thine house like Rachel and like Leah, which two did build the house of Israel: and do thou worthily in Ephratah, and be famous in Bethlehem:"}, {"numero": 12, "texto": "And let thy house be like the house of Pharez, whom Tamar bare unto Judah, of the seed which the Lord shall give thee of this young woman."}, {"numero": 13, "texto": "So Boaz took Ruth, and she was his wife: and when he went in unto her, the Lord gave her conception, and she bare a son."}, {"numero": 14, "texto": "And the women said unto Naomi, Blessed be the Lord, which hath not left thee this day without a kinsman, that his name may be famous in Israel."}, {"numero": 15, "texto": "And he shall be unto thee a restorer of thy life, and a nourisher of thine old age: for thy daughter in law, which loveth thee, which is better to thee than seven sons, hath born him."}, {"numero": 16, "texto": "And Naomi took the child, and laid it in her bosom, and became nurse unto it."}, {"numero": 17, "texto": "And the women her neighbours gave it a name, saying, There is a son born to Naomi; and they called his name Obed: he is the father of Jesse, the father of David."}, {"numero": 18, "texto": "Now these are the generations of Pharez: Pharez begat Hezron,"}, {"numero": 19, "texto": "And Hezron begat Ram, and Ram begat Amminadab,"}, {"numero": 20, "texto": "And Amminadab begat Nahshon, and Nahshon begat Salmon,"}, {"numero": 21, "texto": "And Salmon begat Boaz, and Boaz begat Obed,"}, {"numero": 22, "texto": "And Obed begat Jesse, and Jesse begat David."}]'::jsonb, 'King James Version'),
  ('Rt', 4, 'fr', '[{"numero": 1, "texto": "Boaz monta à la porte, et s''''y arrêta. Or voici, celui qui avait droit de rachat, et dont Boaz avait parlé, vint à passer. Boaz lui dit: Approche, reste ici, toi un tel. Et il s''''approcha, et s''''arrêta."}, {"numero": 2, "texto": "Boaz prit alors dix hommes parmi les anciens de la ville, et il dit: Asseyez-vous ici. Et ils s''''assirent."}, {"numero": 3, "texto": "Puis il dit à celui qui avait le droit de rachat: Naomi, revenue du pays de Moab, a vendu la pièce de terre qui appartenait à notre frère Elimélec."}, {"numero": 4, "texto": "J''''ai cru devoir t''''en informer, et te dire: Acquiers-la, en présence des habitants et en présence des anciens de mon peuple. Si tu veux racheter, rachète; mais si tu ne veux pas, déclare-le-moi, afin que je le sache. Car il n''''y a personne avant toi qui ait le droit de rachat, et je l''''ai après toi. Et il répondit: je rachèterai."}, {"numero": 5, "texto": "Boaz dit: Le jour où tu acquerras le champ de la main de Naomi, tu l''''acquerras en même temps de Ruth la Moabite, femme du défunt, pour relever le nom du défunt dans son héritage."}, {"numero": 6, "texto": "Et celui qui avait le droit de rachat répondit: Je ne puis pas racheter pour mon compte, crainte de détruire mon héritage; prends pour toi mon droit de rachat, car je ne puis pas racheter."}, {"numero": 7, "texto": "Autrefois en Israël, pour valider une affaire quelconque relative à un rachat ou à un échange, l''''un ôtait son soulier et le donnait à l''''autre: cela servait de témoignage en Israël."}, {"numero": 8, "texto": "Celui qui avait le droit de rachat dit donc à Boaz: Acquiers pour ton compte! Et il ôta son soulier."}, {"numero": 9, "texto": "Alors Boaz dit aux anciens et à tout le peuple: Vous êtes témoins aujourd''''hui que j''''ai acquis de la main de Naomi tout ce qui appartenait à Elimélec, à Kiljon et à Machlon,"}, {"numero": 10, "texto": "et que je me suis également acquis pour femme Ruth la Moabite, femme de Machlon, pour relever le nom du défunt dans son héritage, et afin que le nom du défunt ne soit point retranché d''''entre ses frères et de la porte de son lieu. Vous en êtes témoins aujourd''''hui!"}, {"numero": 11, "texto": "Tout le peuple qui était à la porte et les anciens dirent: Nous en sommes témoins! Que l''''Eternel rende la femme qui entre dans ta maison semblable à Rachel et à Léa, qui toutes les deux ont bâti la maison d''''Israël! Manifeste ta force dans Ephrata, et fais-toi un nom dans Bethléhem!"}, {"numero": 12, "texto": "Puisse la postérité que l''''Eternel te donnera par cette jeune femme rendre ta maison semblable à la maison de Pérets, qui fut enfanté à Juda par Tamar!"}, {"numero": 13, "texto": "Boaz prit Ruth, qui devint sa femme, et il alla vers elle. L''''Eternel permit à Ruth de concevoir, et elle enfanta un fils."}, {"numero": 14, "texto": "Les femmes dirent à Naomi: Béni soit l''''Eternel, qui ne t''''a point laissé manquer aujourd''''hui d''''un homme ayant droit de rachat, et dont le nom sera célébré en Israël!"}, {"numero": 15, "texto": "Cet enfant restaurera ton âme, et sera le soutien de ta vieillesse; car ta belle-fille, qui t''''aime, l''''a enfanté, elle qui vaut mieux pour toi que sept fils."}, {"numero": 16, "texto": "Naomi prit l''''enfant et le mit sur son sein, et elle fut sa garde."}, {"numero": 17, "texto": "Les voisines lui donnèrent un nom, en disant: Un fils est né à Naomi! Et elles l''''appelèrent Obed. Ce fut le père d''''Isaï père de David."}, {"numero": 18, "texto": "Voici la postérité de Pérets. Pérets engendra Hetsron;"}, {"numero": 19, "texto": "Hetsron engendra Ram; Ram engendra Amminadab;"}, {"numero": 20, "texto": "Amminadab engendra Nachschon; Nachschon engendra Salmon;"}, {"numero": 21, "texto": "Salmon engendra Boaz; Boaz engendra Obed;"}, {"numero": 22, "texto": "Obed engendra Isaï; et Isaï engendra David."}]'::jsonb, 'Louis Segond 1910'),
  ('Rt', 4, 'es', '[{"numero": 1, "texto": "Y BOOZ subió á la puerta y sentóse allí: y he aquí pasaba aquel pariente del cual había Booz hablado, y díjole: Eh, fulano, ven acá y siéntate. Y él vino, y sentóse."}, {"numero": 2, "texto": "Entonces él tomó diez varones de los ancianos de la ciudad, y dijo: Sentaos aquí. Y ellos se sentaron."}, {"numero": 3, "texto": "Luego dijo al pariente: Noemi, que ha vuelto del campo de Moab, vende una parte de las tierras que tuvo nuestro hermano Elimelech;"}, {"numero": 4, "texto": "Y yo decidí hacértelo saber, y decirte que la tomes delante de los que están aquí sentados, y delante de los ancianos de mi pueblo. Si hubieres de redimir, redime; y si no quisieres redimir, decláramelo para que yo lo sepa: porque no hay otro que redima sino tú, y yo después de ti. Y él respondió: Yo redimiré."}, {"numero": 5, "texto": "Entonces replicó Booz: El mismo día que tomares las tierras de mano de Noemi, has de tomar también á Ruth Moabita, mujer del difunto, para que suscites el nombre del muerto sobre su posesión."}, {"numero": 6, "texto": "Y respondió el pariente: No puedo redimir por mi parte, porque echaría á perder mi heredad: redime tú usando de mi derecho, porque yo no podré redimir."}, {"numero": 7, "texto": "Había ya de largo tiempo esta costumbre en Israel en la redención ó contrato, que para la confirmación de cualquier negocio, el uno se quitaba el zapato y lo daba á su compañero: y este era el testimonio en Israel."}, {"numero": 8, "texto": "Entonces el pariente dijo á Booz: Tómalo tú. Y descalzó su zapato."}, {"numero": 9, "texto": "Y Booz dijo á los ancianos y á todo el pueblo: Vosotros sois hoy testigos de que tomo todas las cosas que fueron de Elimelech, y todo lo que fué de Chelión y de Mahalón, de mano de Noemi;"}, {"numero": 10, "texto": "Y que también tomo por mi mujer á Ruth Moabita, mujer de Mahalón, para suscitar el nombre del difunto sobre su heredad, para que el nombre del muerto no se borre de entre sus hermanos y de la puerta de su lugar. Vosotros sois hoy testigos."}, {"numero": 11, "texto": "Y dijeron todos los del pueblo que estaban á la puerta con los ancianos: Testigos somos. Jehová haga á la mujer que entra en tu casa como á Rachêl y á Lea, las cuales dos edificaron la casa de Israel; y tú seas ilustre en Ephrata, y tengas nombradía en Beth-lehem;"}, {"numero": 12, "texto": "Y de la simiente que Jehová te diere de aquesta moza, sea tu casa como la casa de Phares, al que parió Thamar á Judá."}, {"numero": 13, "texto": "Booz pues tomó á Ruth, y ella fué su mujer; y luego que entró á ella, Jehová le dió que concibiese y pariese un hijo."}, {"numero": 14, "texto": "Y las mujeres decían á Noemi: Loado sea Jehová, que hizo que no te faltase hoy pariente, cuyo nombre será nombrado en Israel."}, {"numero": 15, "texto": "El cual será restaurador de tu alma, y el que sustentará tu vejez; pues que tu nuera, la cual te ama y te vale más que siete hijos, le ha parido."}, {"numero": 16, "texto": "Y tomando Noemi el hijo, púsolo en su regazo, y fuéle su ama."}, {"numero": 17, "texto": "Y las vecinas diciendo, A Noemi ha nacido un hijo, le pusieron nombre; y llamáronle Obed. Este es padre de Isaí, padre de David."}, {"numero": 18, "texto": "Y estas son las generaciones de Phares: Phares engendró á Hesrón;"}, {"numero": 19, "texto": "Y Hesrón engendró á Ram, y Ram engendró á Aminadab;"}, {"numero": 20, "texto": "Y Aminadab engendró á Nahasón, y Nahasón engendró á Salmón;"}, {"numero": 21, "texto": "Y Salmón engendró á Booz, y Booz engendró á Obed;"}, {"numero": 22, "texto": "Y Obed engendró á Isaí, é Isaí engendró á David."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 1, 'pt', '[{"numero": 1, "texto": "Bem-aventurado o homem que não anda no conselho dos maus, nem fica parado no caminho dos pecadores, nem se senta junto dos escarnecedores."}, {"numero": 2, "texto": "Mas sim, que tem seu prazer na Lei do SENHOR; e medita em sua Lei de dia e de noite."}, {"numero": 3, "texto": "Porque ele será como uma árvore, plantada junto a ribeiros de águas, que dá fruto a seu [devido] tempo, e suas folhas não caem; e tudo quanto fizer prosperará."}, {"numero": 4, "texto": "Os maus não são assim; mas são como a palha que o vento dispersa."}, {"numero": 5, "texto": "Por isso os maus não subsistirão no julgamento, nem os pecadores no ajuntamento dos justos."}, {"numero": 6, "texto": "Porque o SENHOR conhece o caminho dos justos; porém o caminho dos maus perecerá."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 1, 'en', '[{"numero": 1, "texto": "Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful."}, {"numero": 2, "texto": "But his delight is in the law of the Lord; and in his law doth he meditate day and night."}, {"numero": 3, "texto": "And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper."}, {"numero": 4, "texto": "The ungodly are not so: but are like the chaff which the wind driveth away."}, {"numero": 5, "texto": "Therefore the ungodly shall not stand in the judgment, nor sinners in the congregation of the righteous."}, {"numero": 6, "texto": "For the Lord knoweth the way of the righteous: but the way of the ungodly shall perish."}]'::jsonb, 'King James Version'),
  ('Sl', 1, 'fr', '[{"numero": 1, "texto": "Heureux l''''homme qui ne marche pas selon le conseil des méchants, Qui ne s''''arrête pas sur la voie des pécheurs, Et qui ne s''''assied pas en compagnie des moqueurs,"}, {"numero": 2, "texto": "Mais qui trouve son plaisir dans la loi de l''''Eternel, Et qui la médite jour et nuit!"}, {"numero": 3, "texto": "Il est comme un arbre planté près d''''un courant d''''eau, Qui donne son fruit en sa saison, Et dont le feuillage ne se flétrit point: Tout ce qu''''il fait lui réussit."}, {"numero": 4, "texto": "Il n''''en est pas ainsi des méchants: Ils sont comme la paille que le vent dissipe."}, {"numero": 5, "texto": "C''''est pourquoi les méchants ne résistent pas au jour du jugement, Ni les pécheurs dans l''''assemblée des justes;"}, {"numero": 6, "texto": "Car l''''Eternel connaît la voie des justes, Et la voie des pécheurs mène à la ruine."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 1, 'es', '[{"numero": 1, "texto": "BIENAVENTURADO el varón que no anduvo en consejo de malos, ni estuvo en camino de pecadores, ni en silla de escarnecedores se ha sentado;"}, {"numero": 2, "texto": "Antes en la ley de Jehová está su delicia, y en su ley medita de día y de noche."}, {"numero": 3, "texto": "Y será como el árbol plantado junto á arroyos de aguas, que da su fruto en su tiempo, y su hoja no cae; y todo lo que hace, prosperará."}, {"numero": 4, "texto": "No así los malos: sino como el tamo que arrebata el viento."}, {"numero": 5, "texto": "Por tanto no se levantarán los malos en el juicio, ni los pecadores en la congregación de los justos."}, {"numero": 6, "texto": "Porque Jehová conoce el camino de los justos; mas la senda de los malos perecerá."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 15, 'pt', '[{"numero": 1, "texto": "Salmo de Davi: SENHOR, quem morará em tua tenda? Quem habitará no monte de tua santidade?"}, {"numero": 2, "texto": "Aquele que anda sinceramente, e pratica a justiça; e com seu coração fala a verdade;"}, {"numero": 3, "texto": "[Aquele que] não murmura com sua língua; não faz mal ao seu companheiro, nem aceita insulto contra seu próximo."}, {"numero": 4, "texto": "Em seus olhos despreza à pessoa que é digna de reprovação, mas honra aos que temem ao SENHOR; mantém seu juramento até sob [seu próprio] prejuízo, e não muda."}, {"numero": 5, "texto": "[Tal pessoa] não empresta seu dinheiro com juros; nem aceita suborno contra o inocente; quem faz isto, nunca se abalará."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 15, 'en', '[{"numero": 1, "texto": "Lord, who shall abide in thy tabernacle? who shall dwell in thy holy hill?"}, {"numero": 2, "texto": "He that walketh uprightly, and worketh righteousness, and speaketh the truth in his heart."}, {"numero": 3, "texto": "He that backbiteth not with his tongue, nor doeth evil to his neighbour, nor taketh up a reproach against his neighbour."}, {"numero": 4, "texto": "In whose eyes a vile person is contemned; but he honoureth them that fear the Lord. He that sweareth to his own hurt, and changeth not."}, {"numero": 5, "texto": "He that putteth not out his money to usury, nor taketh reward against the innocent. He that doeth these things shall never be moved."}]'::jsonb, 'King James Version'),
  ('Sl', 15, 'fr', '[{"numero": 1, "texto": "Psaume de David. O Eternel! qui séjournera dans ta tente? Qui demeurera sur ta montagne sainte? -"}, {"numero": 2, "texto": "Celui qui marche dans l''''intégrité, qui pratique la justice Et qui dit la vérité selon son coeur."}, {"numero": 3, "texto": "Il ne calomnie point avec sa langue, Il ne fait point de mal à son semblable, Et il ne jette point l''''opprobre sur son prochain."}, {"numero": 4, "texto": "Il regarde avec dédain celui qui est méprisable, Mais il honore ceux qui craignent l''''Eternel; Il ne se rétracte point, s''''il fait un serment à son préjudice."}, {"numero": 5, "texto": "Il n''''exige point d''''intérêt de son argent, Et il n''''accepte point de don contre l''''innocent. Celui qui se conduit ainsi ne chancelle jamais."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 15, 'es', '[{"numero": 1, "texto": "JEHOVÁ, ¿quién habitará en tu tabernáculo? ¿quién residirá en el monte de tu santidad?"}, {"numero": 2, "texto": "El que anda en integridad, y obra justicia, y habla verdad en su corazón."}, {"numero": 3, "texto": "El que no detrae con su lengua, ni hace mal á su prójimo, ni contra su prójimo acoge oprobio alguno."}, {"numero": 4, "texto": "Aquel á cuyos ojos es menospreciado el vil; mas honra á los que temen á Jehová: y habiendo jurado en daño suyo, no por eso muda."}, {"numero": 5, "texto": "Quien su dinero no dió á usura, ni contra el inocente tomó cohecho. El que hace estas cosas, no resbalará para siempre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 19, 'pt', '[{"numero": 1, "texto": "Salmo de Davi, para o regente: Os céus declaram a glória de Deus; e o firmamento anuncia a obra de suas mãos."}, {"numero": 2, "texto": "Dia após dia ele fala; e noite após noite ele mostra sabedoria."}, {"numero": 3, "texto": "Não há língua, nem palavras, onde não se ouça a voz deles."}, {"numero": 4, "texto": "Por toda a terra sai sua corda, e suas palavras até o fim do mundo; para o sol ele pôs uma tenda neles."}, {"numero": 5, "texto": "E ele [é] como o noivo, que sai de sua câmara; [e] se alegra como um homem valente, para correr [seu] caminho."}, {"numero": 6, "texto": "Desde uma extremidade dos céus [é] sua saída, e seu curso até as [outras] extremidades deles; e nada se esconde de seu calor."}, {"numero": 7, "texto": "A lei do SENHOR é perfeita, [e] restaura a alma; o testemunho do SENHOR é fiel, [e] da sabedoria aos simples."}, {"numero": 8, "texto": "Os preceitos do SENHOR são corretos, [e] alegram ao coração; o mandamento do SENHOR é puro, [e] ilumina aos olhos."}, {"numero": 9, "texto": "O temor ao SENHOR é limpo, [e] permanece para sempre; os juízos do SENHOR são verdade; juntamente são justos."}, {"numero": 10, "texto": "[São] mais desejáveis que ouro, mais do que muito ouro fino; e mais doces que o mel, e o licor de seus favos."}, {"numero": 11, "texto": "Também por eles teu servo é advertido; por guardá-los, [há] muita recompensa."}, {"numero": 12, "texto": "Quem pode entender [seus próprios] erros? Limpa-me dos que [me] são ocultos."}, {"numero": 13, "texto": "Também retém a teu servo de arrogâncias, para que elas não me controlem; então eu serei sincero, e ficarei limpo de grande transgressão."}, {"numero": 14, "texto": "Sejam agradáveis as palavras de minha boca, e o pensamento do meu coração, diante de ti, ó SENHOR, minha rocha e meu Libertador."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 19, 'en', '[{"numero": 1, "texto": "The heavens declare the glory of God; and the firmament sheweth his handywork."}, {"numero": 2, "texto": "Day unto day uttereth speech, and night unto night sheweth knowledge."}, {"numero": 3, "texto": "There is no speech nor language, where their voice is not heard."}, {"numero": 4, "texto": "Their line is gone out through all the earth, and their words to the end of the world. In them hath he set a tabernacle for the sun,"}, {"numero": 5, "texto": "Which is as a bridegroom coming out of his chamber, and rejoiceth as a strong man to run a race."}, {"numero": 6, "texto": "His going forth is from the end of the heaven, and his circuit unto the ends of it: and there is nothing hid from the heat thereof."}, {"numero": 7, "texto": "The law of the Lord is perfect, converting the soul: the testimony of the Lord is sure, making wise the simple."}, {"numero": 8, "texto": "The statutes of the Lord are right, rejoicing the heart: the commandment of the Lord is pure, enlightening the eyes."}, {"numero": 9, "texto": "The fear of the Lord is clean, enduring for ever: the judgments of the Lord are true and righteous altogether."}, {"numero": 10, "texto": "More to be desired are they than gold, yea, than much fine gold: sweeter also than honey and the honeycomb."}, {"numero": 11, "texto": "Moreover by them is thy servant warned: and in keeping of them there is great reward."}, {"numero": 12, "texto": "Who can understand his errors? cleanse thou me from secret faults."}, {"numero": 13, "texto": "Keep back thy servant also from presumptuous sins; let them not have dominion over me: then shall I be upright, and I shall be innocent from the great transgression."}, {"numero": 14, "texto": "Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O Lord, my strength, and my redeemer."}]'::jsonb, 'King James Version'),
  ('Sl', 19, 'fr', '[{"numero": 1, "texto": "Au chef des chantres. Psaume de David. Les cieux racontent la gloire de Dieu, Et l''''étendue manifeste l''''oeuvre de ses mains."}, {"numero": 2, "texto": "Le jour en instruit un autre jour, La nuit en donne connaissance à une autre nuit."}, {"numero": 3, "texto": "Ce n''''est pas un langage, ce ne sont pas des paroles Dont le son ne soit point entendu:"}, {"numero": 4, "texto": "Leur retentissement parcourt toute la terre, Leurs accents vont aux extrémités du monde, Où il a dressé une tente pour le soleil."}, {"numero": 5, "texto": "Et le soleil, semblable à un époux qui sort de sa chambre, S''''élance dans la carrière avec la joie d''''un héros;"}, {"numero": 6, "texto": "Il se lève à une extrémité des cieux, Et achève sa course à l''''autre extrémité: Rien ne se dérobe à sa chaleur."}, {"numero": 7, "texto": "La loi de l''''Eternel est parfaite, elle restaure l''''âme; Le témoignage de l''''Eternel est véritable, il rend sage l''''ignorant."}, {"numero": 8, "texto": "Les ordonnances de l''''Eternel sont droites, elles réjouissent le coeur; Les commandements de l''''Eternel sont purs, ils éclairent les yeux."}, {"numero": 9, "texto": "La crainte de l''''Eternel est pure, elle subsiste à toujours; Les jugements de l''''Eternel sont vrais, ils sont tous justes."}, {"numero": 10, "texto": "Ils sont plus précieux que l''''or, que beaucoup d''''or fin; Ils sont plus doux que le miel, que celui qui coule des rayons."}, {"numero": 11, "texto": "Ton serviteur aussi en reçoit instruction; Pour qui les observe la récompense est grande."}, {"numero": 12, "texto": "Qui connaît ses égarements? Pardonne-moi ceux que j''''ignore."}, {"numero": 13, "texto": "Préserve aussi ton serviteur des orgueilleux; Qu''''ils ne dominent point sur moi! Alors je serai intègre, innocent de grands péchés."}, {"numero": 14, "texto": "Reçois favorablement les paroles de ma bouche Et les sentiments de mon coeur, O Eternel, mon rocher et mon libérateur!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 19, 'es', '[{"numero": 1, "texto": "LOS cielos cuentan la gloria de Dios, y la expansión denuncia la obra de sus manos."}, {"numero": 2, "texto": "El un día emite palabra al otro día, y la una noche á la otra noche declara sabiduría."}, {"numero": 3, "texto": "No hay dicho, ni palabras, ni es oída su voz."}, {"numero": 4, "texto": "Por toda la tierra salió su hilo, y al cabo del mundo sus palabras. En ellos puso tabernáculo para el sol."}, {"numero": 5, "texto": "Y él, como un novio que sale de su tálamo, alégrase cual gigante para correr el camino."}, {"numero": 6, "texto": "Del un cabo de los cielos es su salida, y su giro hasta la extremidad de ellos: y no hay quien se esconda de su calor."}, {"numero": 7, "texto": "La ley de Jehová es perfecta, que vuelve el alma: el testimonio de Jehová, fiel, que hace sabio al pequeño."}, {"numero": 8, "texto": "Los mandamientos de Jehová son rectos, que alegran el corazón: el precepto de Jehová, puro, que alumbra los ojos."}, {"numero": 9, "texto": "El temor de Jehová, limpio, que permanece para siempre; los juicios de Jehová son verdad, todos justos."}, {"numero": 10, "texto": "Deseables son más que el oro, y más que mucho oro afinado; y dulces más que miel, y que la que destila del panal."}, {"numero": 11, "texto": "Tu siervo es además amonestado con ellos: en guardarlos hay grande galardón."}, {"numero": 12, "texto": "Los errores, ¿quién los entenderá? Líbrame de los que me son ocultos."}, {"numero": 13, "texto": "Detén asimismo á tu siervo de las soberbias; que no se enseñoreen de mí: entonces seré íntegro, y estaré limpio de gran rebelión."}, {"numero": 14, "texto": "Sean gratos los dichos de mi boca y la meditación de mi corazón delante de ti, oh Jehová, roca mía, y redentor mío."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 23, 'pt', '[{"numero": 1, "texto": "Salmo de Davi: O SENHOR é meu pastor, nada me faltará."}, {"numero": 2, "texto": "Ele me faz deitar em pastos verdes, [e] me leva a águas quietas."}, {"numero": 3, "texto": "Ele restaura minha alma, [e] me guia pelos caminhos da justiça por seu nome."}, {"numero": 4, "texto": "Ainda que eu venha a andar pelo vale da sombra da morte, não temerei mal algum, porque tu estás comigo; tua vara e teu cajado me consolam."}, {"numero": 5, "texto": "Tu preparas uma mesa diante de mim à vista de meus adversários; unges a minha cabeça com azeite, meu cálice transborda."}, {"numero": 6, "texto": "Certamente o bem e a bondade me seguirão todos os dias de minha vida; e habitarei na casa do SENHOR por muitos e muitos dias."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 23, 'en', '[{"numero": 1, "texto": "The Lord is my shepherd; I shall not want."}, {"numero": 2, "texto": "He maketh me to lie down in green pastures: he leadeth me beside the still waters."}, {"numero": 3, "texto": "He restoreth my soul: he leadeth me in the paths of righteousness for his name''s sake."}, {"numero": 4, "texto": "Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me."}, {"numero": 5, "texto": "Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over."}, {"numero": 6, "texto": "Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the Lord for ever."}]'::jsonb, 'King James Version'),
  ('Sl', 23, 'fr', '[{"numero": 1, "texto": "Cantique de David. L''''Eternel est mon berger: je ne manquerai de rien."}, {"numero": 2, "texto": "Il me fait reposer dans de verts pâturages, Il me dirige près des eaux paisibles."}, {"numero": 3, "texto": "Il restaure mon âme, Il me conduit dans les sentiers de la justice, A cause de son nom."}, {"numero": 4, "texto": "Quand je marche dans la vallée de l''''ombre de la mort, Je ne crains aucun mal, car tu es avec moi: Ta houlette et ton bâton me rassurent."}, {"numero": 5, "texto": "Tu dresses devant moi une table, En face de mes adversaires; Tu oins d''''huile ma tête, Et ma coupe déborde."}, {"numero": 6, "texto": "Oui, le bonheur et la grâce m''''accompagneront Tous les jours de ma vie, Et j''''habiterai dans la maison de l''''Eternel Jusqu''''à la fin de mes jours."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 23, 'es', '[{"numero": 1, "texto": "JEHOVÁ es mi pastor; nada me faltará."}, {"numero": 2, "texto": "En lugares de delicados pastos me hará yacer: junto á aguas de reposo me pastoreará."}, {"numero": 3, "texto": "Confortará mi alma; guiaráme por sendas de justicia por amor de su nombre."}, {"numero": 4, "texto": "Aunque ande en valle de sombra de muerte, no temeré mal alguno; porque tú estarás conmigo: tu vara y tu cayado me infundirán aliento."}, {"numero": 5, "texto": "Aderezarás mesa delante de mí, en presencia de mis angustiadores: ungiste mi cabeza con aceite: mi copa está rebosando."}, {"numero": 6, "texto": "Ciertamente el bien y la misericordia me seguirán todos los días de mi vida: y en la casa de Jehová moraré por largos días."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 24, 'pt', '[{"numero": 1, "texto": "Salmo de Davi: Ao SENHOR [pertence] a terra, e sua plenitude; o mundo, e os que nele habitam."}, {"numero": 2, "texto": "Porque ele a fundou sobre os mares; e sobre os rios ele a firmou."}, {"numero": 3, "texto": "Quem subirá ao monte do SENHOR? E quem ficará de pé no lugar de sua santidade?"}, {"numero": 4, "texto": "Aquele que é limpo de mãos, e puro de coração, que não entrega sua alma para as coisas vãs, nem jura enganosamente."}, {"numero": 5, "texto": "Este receberá a bênção do SENHOR, e a justiça do Deus de sua salvação."}, {"numero": 6, "texto": "Esta é a geração dos que o buscam, dos que procuram a tua face: [a geração de] Jacó. (Selá)"}, {"numero": 7, "texto": "Levantai, portas, vossas cabeças; e levantai-vos vós, entradas eternas; para que entre o Rei da Glória."}, {"numero": 8, "texto": "Quem é o Rei da Glória? O SENHOR forte e poderoso, o SENHOR poderoso na guerra."}, {"numero": 9, "texto": "Levantai, portas, vossas cabeças; e levantai-vos vós, entradas eternas; para que entre o Rei da Glória."}, {"numero": 10, "texto": "Quem é este Rei da Glória? O SENHOR dos exércitos; ele é o Rei da Glória! (Selá)"}]'::jsonb, 'Almeida Livre'),
  ('Sl', 24, 'en', '[{"numero": 1, "texto": "The earth is the Lord''s, and the fulness thereof; the world, and they that dwell therein."}, {"numero": 2, "texto": "For he hath founded it upon the seas, and established it upon the floods."}, {"numero": 3, "texto": "Who shall ascend into the hill of the Lord? or who shall stand in his holy place?"}, {"numero": 4, "texto": "He that hath clean hands, and a pure heart; who hath not lifted up his soul unto vanity, nor sworn deceitfully."}, {"numero": 5, "texto": "He shall receive the blessing from the Lord, and righteousness from the God of his salvation."}, {"numero": 6, "texto": "This is the generation of them that seek him, that seek thy face, O Jacob. Selah."}, {"numero": 7, "texto": "Lift up your heads, O ye gates; and be ye lift up, ye everlasting doors; and the King of glory shall come in."}, {"numero": 8, "texto": "Who is this King of glory? The Lord strong and mighty, the Lord mighty in battle."}, {"numero": 9, "texto": "Lift up your heads, O ye gates; even lift them up, ye everlasting doors; and the King of glory shall come in."}, {"numero": 10, "texto": "Who is this King of glory? The Lord of hosts, he is the King of glory. Selah."}]'::jsonb, 'King James Version'),
  ('Sl', 24, 'fr', '[{"numero": 1, "texto": "Psaume de David. A l''''Eternel la terre et ce qu''''elle renferme, Le monde et ceux qui l''''habitent!"}, {"numero": 2, "texto": "Car il l''''a fondée sur les mers, Et affermie sur les fleuves."}, {"numero": 3, "texto": "Qui pourra monter à la montagne de l''''Eternel? Qui s''''élèvera jusqu''''à son lieu saint? -"}, {"numero": 4, "texto": "Celui qui a les mains innocentes et le coeur pur; Celui qui ne livre pas son âme au mensonge, Et qui ne jure pas pour tromper."}, {"numero": 5, "texto": "Il obtiendra la bénédiction de l''''Eternel, La miséricorde du Dieu de son salut."}, {"numero": 6, "texto": "Voilà le partage de la génération qui l''''invoque, De ceux qui cherchent ta face, de Jacob! -Pause."}, {"numero": 7, "texto": "Portes, élevez vos linteaux; Elevez-vous, portes éternelles! Que le roi de gloire fasse son entrée! -"}, {"numero": 8, "texto": "Qui est ce roi de gloire? -L''''Eternel fort et puissant, L''''Eternel puissant dans les combats."}, {"numero": 9, "texto": "Portes, élevez vos linteaux; Elevez-les, portes éternelles! Que le roi de gloire fasse son entrée! -"}, {"numero": 10, "texto": "Qui donc est ce roi de gloire? -L''''Eternel des armées: Voilà le roi de gloire! -Pause."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 24, 'es', '[{"numero": 1, "texto": "DE Jehová es la tierra y su plenitud; el mundo, y los que en él habitan."}, {"numero": 2, "texto": "Porque él la fundó sobre los mares, y afirmóla sobre los ríos."}, {"numero": 3, "texto": "¿Quién subirá al monte de Jehová? ¿y quién estará en el lugar de su santidad?"}, {"numero": 4, "texto": "El limpio de manos, y puro de corazón: el que no ha elevado su alma á la vanidad, ni jurado con engaño."}, {"numero": 5, "texto": "El recibirá bendición de Jehová, y justicia del Dios de salud."}, {"numero": 6, "texto": "Tal es la generación de los que le buscan, de los que buscan tu rostro, oh Dios de Jacob. (Selah.)"}, {"numero": 7, "texto": "Alzad, oh puertas, vuestras cabezas, y alzaos vosotras, puertas eternas, y entrará el Rey de gloria."}, {"numero": 8, "texto": "¿Quién es este Rey de gloria? Jehová el fuerte y valiente, Jehová el poderoso en batalla."}, {"numero": 9, "texto": "Alzad, oh puertas, vuestras cabezas, y alzaos vosotras, puertas eternas, y entrará el Rey de gloria."}, {"numero": 10, "texto": "¿Quién es este Rey de gloria? Jehová de los ejércitos, él es el Rey de la gloria. (Selah.)"}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 27, 'pt', '[{"numero": 1, "texto": "Salmo de Davi: O SENHOR é minha luz e minha salvação; a quem temerei? O SENHOR é a força da minha vida; de quem terei medo?"}, {"numero": 2, "texto": "Quando os maus chegaram perto de mim, meus adversários e meus inimigos contra mim, para devorarem minha carne; eles mesmos tropeçaram e caíram."}, {"numero": 3, "texto": "Ainda que um exército me cercasse, eu não temeria; ainda que uma guerra se levantasse contra mim, nisto mantenho confiança."}, {"numero": 4, "texto": "Pedi uma coisa ao SENHOR, [e] a ela buscarei: que eu possa morar na casa do SENHOR todos os dias de minha vida, para ver a beleza do SENHOR, e consultá-lo em seu Templo."}, {"numero": 5, "texto": "Porque no dia mal ele me esconderá em seu abrigo; ele me encobrirá no oculto de sua tenda; [e] me porá sobre as rochas."}, {"numero": 6, "texto": "E minha cabeça será exaltada acima de meus inimigos, que estão ao redor de mim; e eu sacrificarei na tenda dele sacrifícios com alta voz; cantarei e louvarei ao SENHOR."}, {"numero": 7, "texto": "Ouve, SENHOR, minha voz, [quando] eu clamo; tem piedade de mim, e responde-me."}, {"numero": 8, "texto": "Ele diz a ti, meu coração: Buscai a minha face.Eu busco a tua face, SENHOR."}, {"numero": 9, "texto": "Não escondas de mim a tua face, nem rejeites a teu servo com ira; tu tens sido meu socorro; não me deixes, nem me desampares, ó Deus de minha salvação."}, {"numero": 10, "texto": "Porque meu pai e minha mãe me abandonaram, mas o SENHOR me recolherá."}, {"numero": 11, "texto": "Ensina-me, SENHOR, o teu caminho; e guia-me pela via correta, por causa dos meus inimigos."}, {"numero": 12, "texto": "Não me entregues à vontade dos meus adversários, porque se levantaram contra mim falsas testemunhas, e também ao que sopra violência."}, {"numero": 13, "texto": "Se eu não tivesse crido que veria a bondade do SENHOR na terra dos viventes, [certamente já teria perecido] ."}, {"numero": 14, "texto": "Espera no SENHOR, esforça-te, e ele fortalecerá o teu coração; espera pois ao SENHOR."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 27, 'en', '[{"numero": 1, "texto": "The Lord is my light and my salvation; whom shall I fear? the Lord is the strength of my life; of whom shall I be afraid?"}, {"numero": 2, "texto": "When the wicked, even mine enemies and my foes, came upon me to eat up my flesh, they stumbled and fell."}, {"numero": 3, "texto": "Though an host should encamp against me, my heart shall not fear: though war should rise against me, in this will I be confident."}, {"numero": 4, "texto": "One thing have I desired of the Lord, that will I seek after; that I may dwell in the house of the Lord all the days of my life, to behold the beauty of the Lord, and to enquire in his temple."}, {"numero": 5, "texto": "For in the time of trouble he shall hide me in his pavilion: in the secret of his tabernacle shall he hide me; he shall set me up upon a rock."}, {"numero": 6, "texto": "And now shall mine head be lifted up above mine enemies round about me: therefore will I offer in his tabernacle sacrifices of joy; I will sing, yea, I will sing praises unto the Lord."}, {"numero": 7, "texto": "Hear, O Lord, when I cry with my voice: have mercy also upon me, and answer me."}, {"numero": 8, "texto": "When thou saidst, Seek ye my face; my heart said unto thee, Thy face, Lord, will I seek."}, {"numero": 9, "texto": "Hide not thy face far from me; put not thy servant away in anger: thou hast been my help; leave me not, neither forsake me, O God of my salvation."}, {"numero": 10, "texto": "When my father and my mother forsake me, then the Lord will take me up."}, {"numero": 11, "texto": "Teach me thy way, O Lord, and lead me in a plain path, because of mine enemies."}, {"numero": 12, "texto": "Deliver me not over unto the will of mine enemies: for false witnesses are risen up against me, and such as breathe out cruelty."}, {"numero": 13, "texto": "I had fainted, unless I had believed to see the goodness of the Lord in the land of the living."}, {"numero": 14, "texto": "Wait on the Lord: be of good courage, and he shall strengthen thine heart: wait, I say, on the Lord."}]'::jsonb, 'King James Version'),
  ('Sl', 27, 'fr', '[{"numero": 1, "texto": "De David. L''''Eternel est ma lumière et mon salut: De qui aurais-je crainte? L''''Eternel est le soutien de ma vie: De qui aurais-je peur?"}, {"numero": 2, "texto": "Quand des méchants s''''avancent contre moi, Pour dévorer ma chair, Ce sont mes persécuteurs et mes ennemis Qui chancellent et tombent."}, {"numero": 3, "texto": "Si une armée se campait contre moi, Mon coeur n''''aurait aucune crainte; Si une guerre s''''élevait contre moi, Je serais malgré cela plein de confiance."}, {"numero": 4, "texto": "Je demande à l''''Eternel une chose, que je désire ardemment: Je voudrais habiter toute ma vie dans la maison de l''''Eternel, Pour contempler la magnificence de l''''Eternel Et pour admirer son temple."}, {"numero": 5, "texto": "Car il me protégera dans son tabernacle au jour du malheur, Il me cachera sous l''''abri de sa tente; Il m''''élèvera sur un rocher."}, {"numero": 6, "texto": "Et déjà ma tête s''''élève sur mes ennemis qui m''''entourent; J''''offrirai des sacrifices dans sa tente, au son de la trompette; Je chanterai, je célébrerai l''''Eternel."}, {"numero": 7, "texto": "Eternel! écoute ma voix, je t''''invoque: Aie pitié de moi et exauce-moi!"}, {"numero": 8, "texto": "Mon coeur dit de ta part: Cherchez ma face! Je cherche ta face, ô Eternel!"}, {"numero": 9, "texto": "Ne me cache point ta face, Ne repousse pas avec colère ton serviteur! Tu es mon secours, ne me laisse pas, ne m''''abandonne pas, Dieu de mon salut!"}, {"numero": 10, "texto": "Car mon père et ma mère m''''abandonnent, Mais l''''Eternel me recueillera."}, {"numero": 11, "texto": "Eternel! enseigne-moi ta voie, Conduis-moi dans le sentier de la droiture, A cause de mes ennemis."}, {"numero": 12, "texto": "Ne me livre pas au bon plaisir de mes adversaires, Car il s''''élève contre moi de faux témoins Et des gens qui ne respirent que la violence."}, {"numero": 13, "texto": "Oh! si je n''''étais pas sûr de voir la bonté de l''''Eternel Sur la terre des vivants!..."}, {"numero": 14, "texto": "Espère en l''''Eternel! Fortifie-toi et que ton coeur s''''affermisse! Espère en l''''Eternel!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 27, 'es', '[{"numero": 1, "texto": "JEHOVÁ es mi luz y mi salvación: ¿de quién temeré? Jehová es la fortaleza de mi vida: ¿de quién he de atemorizarme?"}, {"numero": 2, "texto": "Cuando se allegaron contra mí los malignos, mis angustiadores y mis enemigos, para comer mis carnes, ellos tropezaron y cayeron."}, {"numero": 3, "texto": "Aunque se asiente campo contra mí, no temerá mi corazón: aunque contra mí se levante guerra, yo en esto confío."}, {"numero": 4, "texto": "Una cosa he demandado á Jehová, ésta buscaré: que esté yo en la casa de Jehová todos los días de mi vida, para contemplar la hermosura de Jehová, y para inquirir en su templo."}, {"numero": 5, "texto": "Porque él me esconderá en su tabernáculo en el día del mal; ocultaráme en lo reservado de su pabellón; pondráme en alto sobre una roca."}, {"numero": 6, "texto": "Y luego ensalzará mi cabeza sobre mis enemigos en derredor de mí: y yo sacrificaré en su tabernáculo sacrificios de júbilo: cantaré y salmearé á Jehová."}, {"numero": 7, "texto": "Oye, oh Jehová, mi voz con que á ti clamo; y ten misericordia de mí, respóndeme."}, {"numero": 8, "texto": "Mi corazón ha dicho de ti: Buscad mi rostro. Tu rostro buscaré, oh Jehová."}, {"numero": 9, "texto": "No escondas tu rostro de mí, no apartes con ira á tu siervo: mi ayuda has sido; no me dejes y no me desampares, Dios de mi salud."}, {"numero": 10, "texto": "Aunque mi padre y mi madre me dejaran, Jehová con todo me recogerá."}, {"numero": 11, "texto": "Enséñame, oh Jehová, tu camino, y guíame por senda de rectitud, á causa de mis enemigos."}, {"numero": 12, "texto": "No me entregues á la voluntad de mis enemigos; porque se han levantado contra mí testigos falsos, y los que respiran crueldad."}, {"numero": 13, "texto": "Hubiera yo desmayado, si no creyese que tengo de ver la bondad de Jehová en la tierra de los vivientes."}, {"numero": 14, "texto": "Aguarda á Jehová; esfuérzate, y aliéntese tu corazón: sí, espera á Jehová."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 37, 'pt', '[{"numero": 1, "texto": "Salmo de Davi: Não te irrites com os malfeitores, nem tenhas inveja dos que praticam perversidade."}, {"numero": 2, "texto": "Porque assim como a erva, eles logo serão cortados; e como a verdura eles cairão."}, {"numero": 3, "texto": "Confia no SENHOR, e faze o bem; habita a terra, e te alimentarás em segurança."}, {"numero": 4, "texto": "E agrada-te no SENHOR; e ele te dará os pedidos de teu coração."}, {"numero": 5, "texto": "Entrega o teu caminho ao SENHOR; confia nele, e ele agirá,"}, {"numero": 6, "texto": "e manifestará a tua justiça como a luz, e o teu direito como o sol do meio-dia."}, {"numero": 7, "texto": "Descansa no SENHOR, e espera nele; não te irrites contra aquele cujo caminho prospera, [nem] com o homem que planeja maldades."}, {"numero": 8, "texto": "Detém a ira, abandona o furor; não te irrites de maneira alguma para fazer o mal."}, {"numero": 9, "texto": "Porque os malfeitores serão exterminados; mas os que esperam no SENHOR herdarão a terra."}, {"numero": 10, "texto": "E ainda um pouco, e o perverso não [mais existirá] ; e tu olharás para o lugar dele, e ele não [aparecerá] ."}, {"numero": 11, "texto": "Mas os mansos herdarão a terra, e se agradarão com muita paz."}, {"numero": 12, "texto": "O perverso trama contra o justo, e range seus dentes contra ele."}, {"numero": 13, "texto": "O Senhor ri dele, porque vê que já vem o dia dele."}, {"numero": 14, "texto": "O perversos pegarão a espada e armarão seu arco, para abaterem ao miserável e necessitado, para matarem os corretos no caminho."}, {"numero": 15, "texto": "Mas sua espada entrará em seus corações, e seus arcos serão quebrados."}, {"numero": 16, "texto": "O pouco que o justo [tem] é melhor do que a riqueza de muitos perversos."}, {"numero": 17, "texto": "Porque os braços dos perversos serão quebrados, mas o SENHOR sustenta os justos."}, {"numero": 18, "texto": "O SENHOR conhece os dias dos corretos, e a herança deles permanecerá para sempre."}, {"numero": 19, "texto": "Eles não serão envergonhados no tempo mau, e terão fartura nos dias de fome."}, {"numero": 20, "texto": "Mas os perversos perecerão, e os inimigos do SENHOR desaparecerão tal como as melhores partes dos cordeiros; eles de desfarão na fumaça."}, {"numero": 21, "texto": "O perverso toma emprestado, e paga de volta; mas o justo se compadece e dá."}, {"numero": 22, "texto": "Porque os que são por ele abençoados herdarão a terra; mas os que são por ele amaldiçoados serão removidos."}, {"numero": 23, "texto": "Os passos do homem [justo] são preparados pelo SENHOR; e ele tem prazer em seu caminho."}, {"numero": 24, "texto": "Quando cai, ele não fica derrubado, pois o SENHOR sustenta a sua mão."}, {"numero": 25, "texto": "Eu já fui jovem, e já envelheci; mas nunca vi o justo desamparado, nem a sua semente a pedir pão."}, {"numero": 26, "texto": "O dia todo ele se compadece, e empresta; e sua semente é abençoada."}, {"numero": 27, "texto": "Afasta-te do mal, e faze o bem; e faça sua habitação eterna."}, {"numero": 28, "texto": "Porque o SENHOR ama o juízo, e não desampara a seus santos: eles estão guardados para sempre; mas a semente dos perversos será removida."}, {"numero": 29, "texto": "Os justos herdarão a terra, e para sempre nela habitarão."}, {"numero": 30, "texto": "A boca do justo fala de sabedoria, e sua língua fala do [bom] juízo."}, {"numero": 31, "texto": "A Lei de seu Deus [está] em seu coração; seus passos não serão abalados."}, {"numero": 32, "texto": "O perverso espia ao justo, e procura matá-lo."}, {"numero": 33, "texto": "[Mas] o SENHOR não o deixa em suas mãos; nem também o condenará, quando for julgado."}, {"numero": 34, "texto": "Espera no SENHOR, guarda o seu caminho, e ele te exaltará, para herdares a terra; tu verás que os perversos serão removidos."}, {"numero": 35, "texto": "Eu vi ao perverso violento crescer como a árvore verde, natural da terra."}, {"numero": 36, "texto": "Porém ele já foi embora, e eis que ele não [existe mais] ; eu o procurei, e não foi achado."}, {"numero": 37, "texto": "Olha ao sincero, e vê o correto; porque o fim de [tal] homem é a paz."}, {"numero": 38, "texto": "Mas os transgressores serão juntamente destruídos; o fim dos perversos será eliminado."}, {"numero": 39, "texto": "Porém a salvação dos justos [vem] do SENHOR, [que é] a força deles no tempo de angústia."}, {"numero": 40, "texto": "E o SENHOR os socorrerá, e os livrará; ele os livrará dos perversos, e os salvará, porque nele confiam."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 37, 'en', '[{"numero": 1, "texto": "Fret not thyself because of evildoers, neither be thou envious against the workers of iniquity."}, {"numero": 2, "texto": "For they shall soon be cut down like the grass, and wither as the green herb."}, {"numero": 3, "texto": "Trust in the Lord, and do good; so shalt thou dwell in the land, and verily thou shalt be fed."}, {"numero": 4, "texto": "Delight thyself also in the Lord: and he shall give thee the desires of thine heart."}, {"numero": 5, "texto": "Commit thy way unto the Lord; trust also in him; and he shall bring it to pass."}, {"numero": 6, "texto": "And he shall bring forth thy righteousness as the light, and thy judgment as the noonday."}, {"numero": 7, "texto": "Rest in the Lord, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass."}, {"numero": 8, "texto": "Cease from anger, and forsake wrath: fret not thyself in any wise to do evil."}, {"numero": 9, "texto": "For evildoers shall be cut off: but those that wait upon the Lord, they shall inherit the earth."}, {"numero": 10, "texto": "For yet a little while, and the wicked shall not be: yea, thou shalt diligently consider his place, and it shall not be."}, {"numero": 11, "texto": "But the meek shall inherit the earth; and shall delight themselves in the abundance of peace."}, {"numero": 12, "texto": "The wicked plotteth against the just, and gnasheth upon him with his teeth."}, {"numero": 13, "texto": "The Lord shall laugh at him: for he seeth that his day is coming."}, {"numero": 14, "texto": "The wicked have drawn out the sword, and have bent their bow, to cast down the poor and needy, and to slay such as be of upright conversation."}, {"numero": 15, "texto": "Their sword shall enter into their own heart, and their bows shall be broken."}, {"numero": 16, "texto": "A little that a righteous man hath is better than the riches of many wicked."}, {"numero": 17, "texto": "For the arms of the wicked shall be broken: but the Lord upholdeth the righteous."}, {"numero": 18, "texto": "The Lord knoweth the days of the upright: and their inheritance shall be for ever."}, {"numero": 19, "texto": "They shall not be ashamed in the evil time: and in the days of famine they shall be satisfied."}, {"numero": 20, "texto": "But the wicked shall perish, and the enemies of the Lord shall be as the fat of lambs: they shall consume; into smoke shall they consume away."}, {"numero": 21, "texto": "The wicked borroweth, and payeth not again: but the righteous sheweth mercy, and giveth."}, {"numero": 22, "texto": "For such as be blessed of him shall inherit the earth; and they that be cursed of him shall be cut off."}, {"numero": 23, "texto": "The steps of a good man are ordered by the Lord: and he delighteth in his way."}, {"numero": 24, "texto": "Though he fall, he shall not be utterly cast down: for the Lord upholdeth him with his hand."}, {"numero": 25, "texto": "I have been young, and now am old; yet have I not seen the righteous forsaken, nor his seed begging bread."}, {"numero": 26, "texto": "He is ever merciful, and lendeth; and his seed is blessed."}, {"numero": 27, "texto": "Depart from evil, and do good; and dwell for evermore."}, {"numero": 28, "texto": "For the Lord loveth judgment, and forsaketh not his saints; they are preserved for ever: but the seed of the wicked shall be cut off."}, {"numero": 29, "texto": "The righteous shall inherit the land, and dwell therein for ever."}, {"numero": 30, "texto": "The mouth of the righteous speaketh wisdom, and his tongue talketh of judgment."}, {"numero": 31, "texto": "The law of his God is in his heart; none of his steps shall slide."}, {"numero": 32, "texto": "The wicked watcheth the righteous, and seeketh to slay him."}, {"numero": 33, "texto": "The Lord will not leave him in his hand, nor condemn him when he is judged."}, {"numero": 34, "texto": "Wait on the Lord, and keep his way, and he shall exalt thee to inherit the land: when the wicked are cut off, thou shalt see it."}, {"numero": 35, "texto": "I have seen the wicked in great power, and spreading himself like a green bay tree."}, {"numero": 36, "texto": "Yet he passed away, and, lo, he was not: yea, I sought him, but he could not be found."}, {"numero": 37, "texto": "Mark the perfect man, and behold the upright: for the end of that man is peace."}, {"numero": 38, "texto": "But the transgressors shall be destroyed together: the end of the wicked shall be cut off."}, {"numero": 39, "texto": "But the salvation of the righteous is of the Lord: he is their strength in the time of trouble."}, {"numero": 40, "texto": "And the Lord shall help them, and deliver them: he shall deliver them from the wicked, and save them, because they trust in him."}]'::jsonb, 'King James Version'),
  ('Sl', 37, 'fr', '[{"numero": 1, "texto": "De David. Ne t''''irrite pas contre les méchants, N''''envie pas ceux qui font le mal."}, {"numero": 2, "texto": "Car ils sont fauchés aussi vite que l''''herbe, Et ils se flétrissent comme le gazon vert."}, {"numero": 3, "texto": "Confie-toi en l''''Eternel, et pratique le bien; Aie le pays pour demeure et la fidélité pour pâture."}, {"numero": 4, "texto": "Fais de l''''Eternel tes délices, Et il te donnera ce que ton coeur désire."}, {"numero": 5, "texto": "Recommande ton sort à l''''Eternel, Mets en lui ta confiance, et il agira."}, {"numero": 6, "texto": "Il fera paraître ta justice comme la lumière, Et ton droit comme le soleil à son midi."}, {"numero": 7, "texto": "Garde le silence devant l''''Eternel, et espère en lui; Ne t''''irrite pas contre celui qui réussit dans ses voies, Contre l''''homme qui vient à bout de ses mauvais desseins."}, {"numero": 8, "texto": "Laisse la colère, abandonne la fureur; Ne t''''irrite pas, ce serait mal faire."}, {"numero": 9, "texto": "Car les méchants seront retranchés, Et ceux qui espèrent en l''''Eternel posséderont le pays."}, {"numero": 10, "texto": "Encore un peu de temps, et le méchant n''''est plus; Tu regardes le lieu où il était, et il a disparu."}, {"numero": 11, "texto": "Les misérables possèdent le pays, Et ils jouissent abondamment de la paix."}, {"numero": 12, "texto": "Le méchant forme des projets contre le juste, Et il grince des dents contre lui."}, {"numero": 13, "texto": "Le Seigneur se rit du méchant, Car il voit que son jour arrive."}, {"numero": 14, "texto": "Les méchants tirent le glaive, Ils bandent leur arc, Pour faire tomber le malheureux et l''''indigent, Pour égorger ceux dont la voie est droite."}, {"numero": 15, "texto": "Leur glaive entre dans leur propre coeur, Et leurs arcs se brisent."}, {"numero": 16, "texto": "Mieux vaut le peu du juste Que l''''abondance de beaucoup de méchants;"}, {"numero": 17, "texto": "Car les bras des méchants seront brisés, Mais l''''Eternel soutient les justes."}, {"numero": 18, "texto": "L''''Eternel connaît les jours des hommes intègres, Et leur héritage dure à jamais."}, {"numero": 19, "texto": "Ils ne sont pas confondus au temps du malheur, Et ils sont rassasiés aux jours de la famine."}, {"numero": 20, "texto": "Mais les méchants périssent, Et les ennemis de l''''Eternel, comme les plus beaux pâturages; Ils s''''évanouissent, ils s''''évanouissent en fumée."}, {"numero": 21, "texto": "Le méchant emprunte, et il ne rend pas; Le juste est compatissant, et il donne."}, {"numero": 22, "texto": "Car ceux que bénit l''''Eternel possèdent le pays, Et ceux qu''''il maudit sont retranchés."}, {"numero": 23, "texto": "L''''Eternel affermit les pas de l''''homme, Et il prend plaisir à sa voie;"}, {"numero": 24, "texto": "S''''il tombe, il n''''est pas terrassé, Car l''''Eternel lui prend la main."}, {"numero": 25, "texto": "J''''ai été jeune, j''''ai vieilli; Et je n''''ai point vu le juste abandonné, Ni sa postérité mendiant son pain."}, {"numero": 26, "texto": "Toujours il est compatissant, et il prête; Et sa postérité est bénie."}, {"numero": 27, "texto": "Détourne-toi du mal, fais le bien, Et possède à jamais ta demeure."}, {"numero": 28, "texto": "Car l''''Eternel aime la justice, Et il n''''abandonne pas ses fidèles; Ils sont toujours sous sa garde, Mais la postérité des méchants est retranchée."}, {"numero": 29, "texto": "Les justes posséderont le pays, Et ils y demeureront à jamais."}, {"numero": 30, "texto": "La bouche du juste annonce la sagesse, Et sa langue proclame la justice."}, {"numero": 31, "texto": "La loi de son Dieu est dans son coeur; Ses pas ne chancellent point."}, {"numero": 32, "texto": "Le méchant épie le juste, Et il cherche à le faire mourir."}, {"numero": 33, "texto": "L''''Eternel ne le laisse pas entre ses mains, Et il ne le condamne pas quand il est en jugement."}, {"numero": 34, "texto": "Espère en l''''Eternel, garde sa voie, Et il t''''élèvera pour que tu possèdes le pays; Tu verras les méchants retranchés."}, {"numero": 35, "texto": "J''''ai vu le méchant dans toute sa puissance; Il s''''étendait comme un arbre verdoyant."}, {"numero": 36, "texto": "Il a passé, et voici, il n''''est plus; Je le cherche, et il ne se trouve plus."}, {"numero": 37, "texto": "Observe celui qui est intègre, et regarde celui qui est droit; Car il y a une postérité pour l''''homme de paix."}, {"numero": 38, "texto": "Mais les rebelles sont tous anéantis, La postérité des méchants est retranchée."}, {"numero": 39, "texto": "Le salut des justes vient de l''''Eternel; Il est leur protecteur au temps de la détresse."}, {"numero": 40, "texto": "L''''Eternel les secourt et les délivre; Il les délivre des méchants et les sauve, Parce qu''''ils cherchent en lui leur refuge."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 37, 'es', '[{"numero": 1, "texto": "NO te impacientes á causa de los malignos, ni tengas envidia de los que hacen iniquidad."}, {"numero": 2, "texto": "Porque como hierba serán presto cortados, y decaerán como verdor de renuevo."}, {"numero": 3, "texto": "Espera en Jehová, y haz bien; vivirás en la tierra, y en verdad serás alimentado."}, {"numero": 4, "texto": "Pon asimismo tu delicia en Jehová, y él te dará las peticiones de tu corazón."}, {"numero": 5, "texto": "Encomienda á Jehová tu camino, y espera en él; y él hará."}, {"numero": 6, "texto": "Y exhibirá tu justicia como la luz, y tus derechos como el medio día."}, {"numero": 7, "texto": "Calla á Jehová, y espera en él: no te alteres con motivo del que prospera en su camino, por el hombre que hace maldades."}, {"numero": 8, "texto": "Déjate de la ira, y depón el enojo: no te excites en manera alguna á hacer lo malo."}, {"numero": 9, "texto": "Porque los malignos serán talados, mas los que esperan en Jehová, ellos heredarán la tierra."}, {"numero": 10, "texto": "Pues de aquí á poco no será el malo: y contemplarás sobre su lugar, y no parecerá."}, {"numero": 11, "texto": "Pero los mansos heredarán la tierra, y se recrearán con abundancia de paz."}, {"numero": 12, "texto": "Maquina el impío contra el justo, y cruje sobre él sus dientes."}, {"numero": 13, "texto": "El Señor se reirá de él; porque ve que viene su día."}, {"numero": 14, "texto": "Los impíos desenvainaron espada, y entesaron su arco, para derribar al pobre y al menesteroso, para matar á los de recto proceder."}, {"numero": 15, "texto": "La espada de ellos entrará en su mismo corazón, y su arco será quebrado."}, {"numero": 16, "texto": "Mejor es lo poco del justo, que las riquezas de muchos pecadores."}, {"numero": 17, "texto": "Porque los brazos de los impíos serán quebrados: mas el que sostiene á los justos es Jehová."}, {"numero": 18, "texto": "Conoce Jehová los días de los perfectos: y la heredad de ellos será para siempre."}, {"numero": 19, "texto": "No serán avergonzados en el mal tiempo; y en los días de hambre serán hartos."}, {"numero": 20, "texto": "Mas los impíos perecerán, y los enemigos de Jehová como la grasa de los carneros serán consumidos: se disiparán como humo."}, {"numero": 21, "texto": "El impío toma prestado, y no paga; mas el justo tiene misericordia, y da."}, {"numero": 22, "texto": "Porque los benditos de él heredarán la tierra; y los malditos de él serán talados."}, {"numero": 23, "texto": "Por Jehová son ordenados los pasos del hombre, y aprueba su camino."}, {"numero": 24, "texto": "Cuando cayere, no quedará postrado; porque Jehová sostiene su mano."}, {"numero": 25, "texto": "Mozo fuí, y he envejecido, y no he visto justo desamparado, ni su simiente que mendigue pan."}, {"numero": 26, "texto": "En todo tiempo tiene misericordia, y presta; y su simiente es para bendición."}, {"numero": 27, "texto": "Apártate del mal, y haz el bien, y vivirás para siempre."}, {"numero": 28, "texto": "Porque Jehová ama la rectitud, y no desampara sus santos: para siempre serán guardados; mas la simiente de los impíos será extirpada."}, {"numero": 29, "texto": "Los justos heredarán la tierra, y vivirán para siempre sobre ella."}, {"numero": 30, "texto": "La boca del justo hablará sabiduría; y su lengua proferirá juicio."}, {"numero": 31, "texto": "La ley de su Dios está en su corazón; por tanto sus pasos no vacilarán."}, {"numero": 32, "texto": "Acecha el impío al justo, y procura matarlo."}, {"numero": 33, "texto": "Jehová no lo dejará en sus manos, ni lo condenará cuando le juzgaren."}, {"numero": 34, "texto": "Espera en Jehová, y guarda su camino, y él te ensalzará para heredar la tierra: cuando serán talados los pecadores, lo verás."}, {"numero": 35, "texto": "Vi yo al impío sumamente ensalzado, y que se extendía como un laurel verde."}, {"numero": 36, "texto": "Empero pasóse, y he aquí no parece; y busquélo, y no fué hallado."}, {"numero": 37, "texto": "Considera al íntegro, y mira al justo: que la postrimería de cada uno de ellos es paz."}, {"numero": 38, "texto": "Mas los transgresores fueron todos á una destruídos: la postrimería de los impíos fué talada."}, {"numero": 39, "texto": "Pero la salvación de los justos es de Jehová, y él es su fortaleza en el tiempo de angustia."}, {"numero": 40, "texto": "Y Jehová los ayudará, y los librará: y libertarálos de los impíos, y los salvará, por cuanto en él esperaron."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 39, 'pt', '[{"numero": 1, "texto": "Salmo de Davi, para o regente, conforme “Jedutum”: Eu dizia: Vigiarei os meus caminhos, para eu não pecar com minha língua; vigiarei minha boca com freio, enquanto o perverso ainda estiver em frente a mim."}, {"numero": 2, "texto": "Eu fiquei calado, nada falei de bom; e minha dor se agravou."}, {"numero": 3, "texto": "Meu coração se esquentou dentro de mim, fogo se acendeu em minha meditação; [então] eu disse com minha língua:"}, {"numero": 4, "texto": "Conta-me, SENHOR, o meu fim, e a duração dos meus dias, para que eu saiba como eu sou frágil."}, {"numero": 5, "texto": "Eis que a palmos tu ordenaste os meus dias, e o tempo de minha vida [é] como nada diante de ti; pois todo homem que existe [é] um nada. (Selá)"}, {"numero": 6, "texto": "Certamente o homem anda pela aparência, certamente se inquietam em vão; ajuntam [bens] , e não sabem que [os] levará."}, {"numero": 7, "texto": "E agora, SENHOR, o que eu espero? Minha esperança [está] em ti."}, {"numero": 8, "texto": "Livra-me de todas as minhas transgressões; não me ponhas como humilhado pelo tolo."}, {"numero": 9, "texto": "Eu estou calado, não abrirei a minha boca, porque tu fizeste [assim] ."}, {"numero": 10, "texto": "Tira teu tormento de sobre mim; estou consumido pelo golpe de tua mão."}, {"numero": 11, "texto": "Ao castigares alguém com repreensões pela maldade, logo tu desfaz o que lhe agrada como traça; certamente todo homem é um nada. (Selá)"}, {"numero": 12, "texto": "Ouve a minha oração, SENHOR; e dá ouvidos ao meu clamor; não te cales de minhas lágrimas, porque eu sou [como] um peregrino para contigo; estrangeiro, como todos os meus pais."}, {"numero": 13, "texto": "Não prestes atenção em mim [em tua ira] , antes que eu vá, e pereça."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 39, 'en', '[{"numero": 1, "texto": "I said, I will take heed to my ways, that I sin not with my tongue: I will keep my mouth with a bridle, while the wicked is before me."}, {"numero": 2, "texto": "I was dumb with silence, I held my peace, even from good; and my sorrow was stirred."}, {"numero": 3, "texto": "My heart was hot within me, while I was musing the fire burned: then spake I with my tongue,"}, {"numero": 4, "texto": "Lord, make me to know mine end, and the measure of my days, what it is: that I may know how frail I am."}, {"numero": 5, "texto": "Behold, thou hast made my days as an handbreadth; and mine age is as nothing before thee: verily every man at his best state is altogether vanity. Selah."}, {"numero": 6, "texto": "Surely every man walketh in a vain shew: surely they are disquieted in vain: he heapeth up riches, and knoweth not who shall gather them."}, {"numero": 7, "texto": "And now, Lord, what wait I for? my hope is in thee."}, {"numero": 8, "texto": "Deliver me from all my transgressions: make me not the reproach of the foolish."}, {"numero": 9, "texto": "I was dumb, I opened not my mouth; because thou didst it."}, {"numero": 10, "texto": "Remove thy stroke away from me: I am consumed by the blow of thine hand."}, {"numero": 11, "texto": "When thou with rebukes dost correct man for iniquity, thou makest his beauty to consume away like a moth: surely every man is vanity. Selah."}, {"numero": 12, "texto": "Hear my prayer, O Lord, and give ear unto my cry; hold not thy peace at my tears: for I am a stranger with thee, and a sojourner, as all my fathers were."}, {"numero": 13, "texto": "O spare me, that I may recover strength, before I go hence, and be no more."}]'::jsonb, 'King James Version'),
  ('Sl', 39, 'fr', '[{"numero": 1, "texto": "Au chef des chantres. A Jeduthun, Psaume de David. Je disais: Je veillerai sur mes voies, De peur de pécher par ma langue; Je mettrai un frein à ma bouche, Tant que le méchant sera devant moi."}, {"numero": 2, "texto": "Je suis resté muet, dans le silence; Je me suis tu, quoique malheureux; Et ma douleur n''''était pas moins vive."}, {"numero": 3, "texto": "Mon coeur brûlait au dedans de moi, Un feu intérieur me consumait, Et la parole est venue sur ma langue."}, {"numero": 4, "texto": "Eternel! dis-moi quel est le terme de ma vie, Quelle est la mesure de mes jours; Que je sache combien je suis fragile."}, {"numero": 5, "texto": "Voici, tu as donné à mes jours la largeur de la main, Et ma vie est comme un rien devant toi. Oui, tout homme debout n''''est qu''''un souffle. -Pause."}, {"numero": 6, "texto": "Oui, l''''homme se promène comme une ombre, Il s''''agite vainement; Il amasse, et il ne sait qui recueillera."}, {"numero": 7, "texto": "Maintenant, Seigneur, que puis-je espérer? En toi est mon espérance."}, {"numero": 8, "texto": "Délivre-moi de toutes mes transgressions! Ne me rends pas l''''opprobre de l''''insensé!"}, {"numero": 9, "texto": "Je reste muet, je n''''ouvre pas la bouche, Car c''''est toi qui agis."}, {"numero": 10, "texto": "Détourne de moi tes coups! Je succombe sous les attaques de ta main."}, {"numero": 11, "texto": "Tu châties l''''homme en le punissant de son iniquité, Tu détruis comme la teigne ce qu''''il a de plus cher. Oui, tout homme est un souffle. -Pause."}, {"numero": 12, "texto": "Ecoute ma prière, Eternel, et prête l''''oreille à mes cris! Ne sois pas insensible à mes larmes! Car je suis un étranger chez toi, Un habitant, comme tous mes pères."}, {"numero": 13, "texto": "Détourne de moi le regard, et laisse-moi respirer, Avant que je m''''en aille et que ne sois plus!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 39, 'es', '[{"numero": 1, "texto": "YO DIJE: Atenderé á mis caminos, para no pecar con mi lengua: guardaré mi boca con freno, en tanto que el impío fuere contra mí."}, {"numero": 2, "texto": "Enmudecí con silencio, calléme aun respecto de lo bueno: y excitóse mi dolor."}, {"numero": 3, "texto": "Enardecióse mi corazón dentro de mí; encendióse fuego en mi meditación, y así proferí con mi lengua:"}, {"numero": 4, "texto": "Hazme saber, Jehová, mi fin, y cuánta sea la medida de mis días; sepa yo cuánto tengo de ser del mundo."}, {"numero": 5, "texto": "He aquí diste á mis días término corto, y mi edad es como nada delante de ti: ciertamente es completa vanidad todo hombre que vive. (Selah.)"}, {"numero": 6, "texto": "Ciertamente en tinieblas anda el hombre; ciertamente en vano se inquieta: junta, y no sabe quién lo allegará."}, {"numero": 7, "texto": "Y ahora, Señor, ¿qué esperaré? Mi esperanza en ti está."}, {"numero": 8, "texto": "Líbrame de todas mis rebeliones; no me pongas por escarnio del insensato."}, {"numero": 9, "texto": "Enmudecí, no abrí mi boca; porque tú lo hiciste."}, {"numero": 10, "texto": "Quita de sobre mí tu plaga; de la guerra de tu mano soy consumido."}, {"numero": 11, "texto": "Con castigos sobre el pecado corriges al hombre, y haces consumirse como de polilla su grandeza: ciertamente vanidad es todo hombre. (Selah.)"}, {"numero": 12, "texto": "Oye mi oración, oh Jehová, y escucha mi clamor: no calles á mis lágrimas; porque peregrino soy para contigo, y advenedizo, como todos mis padres."}, {"numero": 13, "texto": "Déjame, y tomaré fuerzas, antes que vaya y perezca."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 42, 'pt', '[{"numero": 1, "texto": "Salmo de instrução para o regente; dos filhos de Coré: Assim como a corça geme de desejo pelas correntes de águas, assim também minha alma geme de desejo por ti, Deus."}, {"numero": 2, "texto": "Minha alma tem sede de Deus, do Deus vivente: Quando entrarei, e me apresentarei diante de Deus?"}, {"numero": 3, "texto": "Minhas lágrimas têm sido [meu] alimento dia e noite, porque o dia todo me dizem: Onde [está] o teu Deus?"}, {"numero": 4, "texto": "Disto eu me lembro, e derramo minha alma em mim [com choros] , porque eu ia entre a multidão, [e] com eles entrava na casa de Deus, com voz de alegria e louvor, na festa da multidão."}, {"numero": 5, "texto": "Minha alma, por que tu estás abatida, e te inquietas em mim? Espera em Deus; pois eu o louvarei pelas suas salvações."}, {"numero": 6, "texto": "Deus meu, minha alma está abatida dentro de mim; por isso eu me lembro de ti desde a terra do Jordão, e dos hermonitas, desde o monte Mizar."}, {"numero": 7, "texto": "Um abismo chama [outro] abismo, ao ruído de suas cascatas; todos as tuas ondas e vagas têm passado sobre mim."}, {"numero": 8, "texto": "[Mas] de dia o SENHOR mandará sua misericórdia, e de noite a canção dele estará comigo; uma oração ao Deus de minha vida."}, {"numero": 9, "texto": "Direi a Deus, minha rocha: Por que tu te esqueces de mim? Por que eu ando em sofrimento pela opressão do inimigo?"}, {"numero": 10, "texto": "Meus adversários me afrontam com uma ferida mortal em meus ossos, ao me dizerem todo dia: Onde [está] o teu Deus?"}, {"numero": 11, "texto": "Por que estás abatida, minha alma? E por que te inquietas em mim? Espera em Deus; porque eu ainda o louvarei; ele é a minha salvação e o meu Deus."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 42, 'en', '[{"numero": 1, "texto": "As the hart panteth after the water brooks, so panteth my soul after thee, O God."}, {"numero": 2, "texto": "My soul thirsteth for God, for the living God: when shall I come and appear before God?"}, {"numero": 3, "texto": "My tears have been my meat day and night, while they continually say unto me, Where is thy God?"}, {"numero": 4, "texto": "When I remember these things, I pour out my soul in me: for I had gone with the multitude, I went with them to the house of God, with the voice of joy and praise, with a multitude that kept holyday."}, {"numero": 5, "texto": "Why art thou cast down, O my soul? and why art thou disquieted in me? hope thou in God: for I shall yet praise him for the help of his countenance."}, {"numero": 6, "texto": "O my God, my soul is cast down within me: therefore will I remember thee from the land of Jordan, and of the Hermonites, from the hill Mizar."}, {"numero": 7, "texto": "Deep calleth unto deep at the noise of thy waterspouts: all thy waves and thy billows are gone over me."}, {"numero": 8, "texto": "Yet the Lord will command his lovingkindness in the day time, and in the night his song shall be with me, and my prayer unto the God of my life."}, {"numero": 9, "texto": "I will say unto God my rock, Why hast thou forgotten me? why go I mourning because of the oppression of the enemy?"}, {"numero": 10, "texto": "As with a sword in my bones, mine enemies reproach me; while they say daily unto me, Where is thy God?"}, {"numero": 11, "texto": "Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God."}]'::jsonb, 'King James Version'),
  ('Sl', 42, 'fr', '[{"numero": 1, "texto": "Au chef des chantres. Cantique des fils de Koré. Comme une biche soupire après des courants d''''eau, Ainsi mon âme soupire après toi, ô Dieu!"}, {"numero": 2, "texto": "Mon âme a soif de Dieu, du Dieu vivant: Quand irai-je et paraîtrai-je devant la face de Dieu?"}, {"numero": 3, "texto": "Mes larmes sont ma nourriture jour et nuit, Pendant qu''''on me dit sans cesse: Où est ton Dieu?"}, {"numero": 4, "texto": "Je me rappelle avec effusion de coeur Quand je marchais entouré de la foule, Et que je m''''avançais à sa tête vers la maison de Dieu, Au milieu des cris de joie et des actions de grâces D''''une multitude en fête."}, {"numero": 5, "texto": "Pourquoi t''''abats-tu, mon âme, et gémis-tu au dedans de moi? Espère en Dieu, car je le louerai encore; Il est mon salut et mon Dieu."}, {"numero": 6, "texto": "Mon âme est abattue au dedans de moi: Aussi c''''est à toi que je pense, depuis le pays du Jourdain, Depuis l''''Hermon, depuis la montagne de Mitsear."}, {"numero": 7, "texto": "Un flot appelle un autre flot au bruit de tes ondées; Toutes tes vagues et tous tes flots passent sur moi."}, {"numero": 8, "texto": "Le jour, l''''Eternel m''''accordait sa grâce; La nuit, je chantais ses louanges, J''''adressais une prière au Dieu de ma vie."}, {"numero": 9, "texto": "Je dis à Dieu, mon rocher: Pourquoi m''''oublies-tu? Pourquoi dois-je marcher dans la tristesse, Sous l''''oppression de l''''ennemi?"}, {"numero": 10, "texto": "Mes os se brisent quand mes persécuteurs m''''outragent, En me disant sans cesse: Où est ton Dieu?"}, {"numero": 11, "texto": "Pourquoi t''''abats-tu, mon âme, et gémis-tu au dedans de moi? Espère en Dieu, car je le louerai encore; Il est mon salut et mon Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 42, 'es', '[{"numero": 1, "texto": "COMO el ciervo brama por las corrientes de las aguas, así clama por ti, oh Dios, el alma mía."}, {"numero": 2, "texto": "Mi alma tiene sed de Dios, del Dios vivo: ¡cuándo vendré, y pareceré delante de Dios!"}, {"numero": 3, "texto": "Fueron mis lágrimas mi pan de día y de noche, mientras me dicen todos los días: ¿Dónde está tu Dios?"}, {"numero": 4, "texto": "Acordaréme de estas cosas, y derramaré sobre mí mi alma: cuando pasaré en el número, iré con ellos hasta la casa de Dios, con voz de alegría y de alabanza, haciendo fiesta la multitud."}, {"numero": 5, "texto": "¿Por qué te abates, oh alma mía, y te conturbas en mí? Espera á Dios; porque aun le tengo de alabar por las saludes de su presencia."}, {"numero": 6, "texto": "Dios mío, mi alma está en mí abatida: acordaréme por tanto de ti desde tierra del Jordán, y de los Hermonitas, desde el monte de Mizhar."}, {"numero": 7, "texto": "Un abismo llama á otro á la voz de tus canales: todas tus ondas y tus olas han pasado sobre mí."}, {"numero": 8, "texto": "De día mandará Jehová su misericordia, y de noche su canción será conmigo, y oración al Dios de mi vida."}, {"numero": 9, "texto": "Diré á Dios: Roca mía, ¿por qué te has olvidado de mí? ¿Por qué andaré yo enlutado por la opresión del enemigo?"}, {"numero": 10, "texto": "Mientras se están quebrantando mis huesos, mis enemigos me afrentan, diciéndome cada día: ¿Dónde está tu Dios?"}, {"numero": 11, "texto": "¿Por qué te abates, oh alma mía, y por qué te conturbas en mí? Espera á Dios; porque aun le tengo de alabar; es él salvamento delante de mí, y el Dios mío."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 46, 'pt', '[{"numero": 1, "texto": "Cântico sobre “Alamote”; para o regente, dos filhos de Coré: Deus [é] nosso refúgio e força; socorro oportuno nas angústias."}, {"numero": 2, "texto": "Por isso não temeremos, ainda que a terra se mova, e ainda que as montanhas passem ao interior dos mares;"}, {"numero": 3, "texto": "[Ainda que] suas águas rujam [e] se perturbem, [e] as montanhas tremam por sua braveza. (Selá)"}, {"numero": 4, "texto": "[Há] um rio cujos ribeiros alegram a cidade de Deus, o santuário das habitações do Altíssimo."}, {"numero": 5, "texto": "Deus [está] no meio dela; ela não será abalada; Deus a ajudará ao romper da manhã."}, {"numero": 6, "texto": "As nações gritarão, os reinos se abalarão; [quando] ele levantou a sua voz, a terra se dissolveu."}, {"numero": 7, "texto": "O SENHOR dos exércitos [está] conosco; o Deus de Jacó [é] nosso alto refúgio. (Selá)"}, {"numero": 8, "texto": "Vinde, observai os feitos do SENHOR, que faz assolações na terra;"}, {"numero": 9, "texto": "Que termina as guerras até o fim da terra; ele quebra o arco e corta a lança; ele queima os carros com fogo."}, {"numero": 10, "texto": "Ficai quietos, e sabei que eu sou Deus; eu serei exaltado entre as nações; serei exaltado sobre a terra."}, {"numero": 11, "texto": "O SENHOR dos exércitos [está] conosco; o Deus de Jacó [é] nosso alto refúgio. (Selá)"}]'::jsonb, 'Almeida Livre'),
  ('Sl', 46, 'en', '[{"numero": 1, "texto": "God is our refuge and strength, a very present help in trouble."}, {"numero": 2, "texto": "Therefore will not we fear, though the earth be removed, and though the mountains be carried into the midst of the sea;"}, {"numero": 3, "texto": "Though the waters thereof roar and be troubled, though the mountains shake with the swelling thereof. Selah."}, {"numero": 4, "texto": "There is a river, the streams whereof shall make glad the city of God, the holy place of the tabernacles of the most High."}, {"numero": 5, "texto": "God is in the midst of her; she shall not be moved: God shall help her, and that right early."}, {"numero": 6, "texto": "The heathen raged, the kingdoms were moved: he uttered his voice, the earth melted."}, {"numero": 7, "texto": "The Lord of hosts is with us; the God of Jacob is our refuge. Selah."}, {"numero": 8, "texto": "Come, behold the works of the Lord, what desolations he hath made in the earth."}, {"numero": 9, "texto": "He maketh wars to cease unto the end of the earth; he breaketh the bow, and cutteth the spear in sunder; he burneth the chariot in the fire."}, {"numero": 10, "texto": "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth."}, {"numero": 11, "texto": "The Lord of hosts is with us; the God of Jacob is our refuge. Selah."}]'::jsonb, 'King James Version'),
  ('Sl', 46, 'fr', '[{"numero": 1, "texto": "Au chef des chantres. Des fils de Koré. Sur alamoth. Cantique. Dieu est pour nous un refuge et un appui, Un secours qui ne manque jamais dans la détresse."}, {"numero": 2, "texto": "C''''est pourquoi nous sommes sans crainte quand la terre est bouleversée, Et que les montagnes chancellent au coeur des mers,"}, {"numero": 3, "texto": "Quand les flots de la mer mugissent, écument, Se soulèvent jusqu''''à faire trembler les montagnes. -Pause."}, {"numero": 4, "texto": "Il est un fleuve dont les courants réjouissent la cité de Dieu, Le sanctuaire des demeures du Très-Haut."}, {"numero": 5, "texto": "Dieu est au milieu d''''elle: elle n''''est point ébranlée; Dieu la secourt dès l''''aube du matin."}, {"numero": 6, "texto": "Des nations s''''agitent, des royaumes s''''ébranlent; Il fait entendre sa voix: la terre se fond d''''épouvante."}, {"numero": 7, "texto": "L''''Eternel des armées est avec nous, Le Dieu de Jacob est pour nous une haute retraite. -Pause."}, {"numero": 8, "texto": "Venez, contemplez les oeuvres de l''''Eternel, Les ravages qu''''il a opérés sur la terre!"}, {"numero": 9, "texto": "C''''est lui qui a fait cesser les combats jusqu''''au bout de la terre; Il a brisé l''''arc, et il a rompu la lance, Il a consumé par le feu les chars de guerre. -"}, {"numero": 10, "texto": "Arrêtez, et sachez que je suis Dieu: Je domine sur les nations, je domine sur la terre. -"}, {"numero": 11, "texto": "L''''Eternel des armées est avec nous, Le Dieu de Jacob est pour nous une haute retraite. -Pause."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 46, 'es', '[{"numero": 1, "texto": "DIOS es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones."}, {"numero": 2, "texto": "Por tanto no temeremos aunque la tierra sea removida; aunque se traspasen los montes al corazón de la mar."}, {"numero": 3, "texto": "Bramarán, turbaránse sus aguas; temblarán los montes á causa de su braveza. (Selah.)"}, {"numero": 4, "texto": "Del río sus conductos alegrarán la ciudad de Dios, el santuario de las tiendas del Altísimo."}, {"numero": 5, "texto": "Dios está en medio de ella; no será conmovida: Dios la ayudará al clarear la mañana."}, {"numero": 6, "texto": "Bramaron las gentes, titubearon los reinos; dió él su voz, derritióse la tierra."}, {"numero": 7, "texto": "Jehová de los ejércitos es con nosotros; nuestro refugio es el Dios de Jacob. (Selah.)"}, {"numero": 8, "texto": "Venid, ved las obras de Jehová, que ha puesto asolamientos en la tierra."}, {"numero": 9, "texto": "Que hace cesar las guerras hasta los fines de la tierra: que quiebra el arco, corta la lanza, y quema los carros en el fuego."}, {"numero": 10, "texto": "Estad quietos, y conoced que yo soy Dios: ensalzado he de ser entre las gentes, ensalzado seré en la tierra."}, {"numero": 11, "texto": "Jehová de los ejércitos es con nosotros; nuestro refugio es el Dios de Jacob. (Selah.)"}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 67, 'pt', '[{"numero": 1, "texto": "Salmo e cântico, para o regente, com instrumento de cordas: Que Deus tenha misericórdia de nós, e nos abençoe; que ele brilhe seu rosto sobre nós. (Selá)"}, {"numero": 2, "texto": "Para que o teu caminho seja conhecido na terra, [e] todos as nações [conheçam] tua salvação."}, {"numero": 3, "texto": "Louvem os povos a ti, ó Deus, louvem a ti todos os povos."}, {"numero": 4, "texto": "Que as nações se alegrem e cantem de alegria, pois tu julgarás aos povos com equidade, e guiarás as nações na terra. (Selá)"}, {"numero": 5, "texto": "Louvem os povos a ti, ó Deus, louvem a ti todos os povos."}, {"numero": 6, "texto": "Que a terra dê seu fruto, [e] que Deus, nosso Deus, nos abençoe."}, {"numero": 7, "texto": "Deus nos abençoará, e todos os limites da terra o temerão."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 67, 'en', '[{"numero": 1, "texto": "God be merciful unto us, and bless us; and cause his face to shine upon us; Selah."}, {"numero": 2, "texto": "That thy way may be known upon earth, thy saving health among all nations."}, {"numero": 3, "texto": "Let the people praise thee, O God; let all the people praise thee."}, {"numero": 4, "texto": "O let the nations be glad and sing for joy: for thou shalt judge the people righteously, and govern the nations upon earth. Selah."}, {"numero": 5, "texto": "Let the people praise thee, O God; let all the people praise thee."}, {"numero": 6, "texto": "Then shall the earth yield her increase; and God, even our own God, shall bless us."}, {"numero": 7, "texto": "God shall bless us; and all the ends of the earth shall fear him."}]'::jsonb, 'King James Version'),
  ('Sl', 67, 'fr', '[{"numero": 1, "texto": "Au chef des chantres. Avec instruments à cordes. Psaume. Cantique. Que Dieu ait pitié de nous et qu''''il nous bénisse, Qu''''il fasse luire sur nous sa face, -Pause."}, {"numero": 2, "texto": "Afin que l''''on connaisse sur la terre ta voie, Et parmi toutes les nations ton salut!"}, {"numero": 3, "texto": "Les peuples te louent, ô Dieu! Tous les peuples te louent."}, {"numero": 4, "texto": "Les nations se réjouissent et sont dans l''''allégresse; Car tu juges les peuples avec droiture, Et tu conduis les nations sur la terre. -Pause."}, {"numero": 5, "texto": "Les peuples te louent, ô Dieu! Tous les peuples te louent."}, {"numero": 6, "texto": "La terre donne ses produits; Dieu, notre Dieu, nous bénit."}, {"numero": 7, "texto": "Dieu, nous bénit, Et toutes les extrémités de la terre le craignent."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 67, 'es', '[{"numero": 1, "texto": "DIOS tenga misericordia de nosotros, y nos bendiga; haga resplandecer su rostro sobre nosotros (Selah);"}, {"numero": 2, "texto": "Para que sea conocido en la tierra tu camino, en todas las gentes tu salud."}, {"numero": 3, "texto": "Alábente los pueblos, oh Dios; alábente los pueblos todos."}, {"numero": 4, "texto": "Alégrense y gócense las gentes; porque juzgarás los pueblos con equidad, y pastorearás las naciones en la tierra. (Selah.)"}, {"numero": 5, "texto": "Alábente los pueblos, oh Dios: todos los pueblos te alaben."}, {"numero": 6, "texto": "La tierra dará su fruto: nos bendecirá Dios, el Dios nuestro."}, {"numero": 7, "texto": "Bendíganos Dios, y témanlo todos los fines de la tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 73, 'pt', '[{"numero": 1, "texto": "Salmo de Asafe: Sim, certamente Deus [é] bom para Israel, para os limpos de coração."}, {"numero": 2, "texto": "Eu porém, quase que meus pés se desviaram; quase nada [faltou] para meus passos escorregarem."}, {"numero": 3, "texto": "Porque eu tinha inveja dos arrogantes, quando via a prosperidade dos perversos."}, {"numero": 4, "texto": "Porque não há problemas para eles até sua morte, e o vigor deles continua firme."}, {"numero": 5, "texto": "Não são tão oprimidos como o homem comum, nem são afligidos como os outros homens;"}, {"numero": 6, "texto": "Por isso eles são rodeados de arrogância como um colar; estão cobertos de violência como [se fosse] um vestido."}, {"numero": 7, "texto": "Seus olhos incham de gordura; são excessivos os desejos do coração deles."}, {"numero": 8, "texto": "Eles são escarnecedores e oprimem falando mal e falando arrogantemente."}, {"numero": 9, "texto": "Elevam suas bocas ao céu, e suas línguas andam na terra."}, {"numero": 10, "texto": "Por isso seu povo volta para cá, e as águas lhes são espremidas por completo."}, {"numero": 11, "texto": "E dizem: Como Deus saberia? Será que o Altíssimo tem conhecimento [disto] ?"}, {"numero": 12, "texto": "Eis que estes [são] perversos, sempre estão confortáveis e aumentam seus bens."}, {"numero": 13, "texto": "[Cheguei a pensar] : Certamente purifiquei meu coração e lavei minhas mãos na inocência inutilmente,"}, {"numero": 14, "texto": "Porque sou afligido o dia todo, e castigado toda manhã."}, {"numero": 15, "texto": "Se eu tivesse dito [isto] , eu falaria dessa maneira; eis que teria decepcionado a geração de teus filhos."}, {"numero": 16, "texto": "Quando tentei entender, isto me pareceu trabalhoso."}, {"numero": 17, "texto": "Até que entrei nos santuários de Deus, [e] entendi o fim de tais pessoas."}, {"numero": 18, "texto": "Certamente tu os fazes escorregarem, [e] os lança em assolações."}, {"numero": 19, "texto": "Como eles foram assolados tão repentinamente! Eles se acabaram, [e] se consumiram de medo."}, {"numero": 20, "texto": "Como o sonho depois de acordar, ó Senhor, quando tu acordares desprezarás a aparência deles;"}, {"numero": 21, "texto": "Porque meu coração tem se amargurado, e meus rins têm sentido dolorosas picadas."}, {"numero": 22, "texto": "Então me comportei como tolo, e nada sabia; tornei-me como um animal para contigo."}, {"numero": 23, "texto": "Porém [agora estarei] continuamente contigo; tu tens segurado minha mão direita."}, {"numero": 24, "texto": "Tu me guiarás com teu conselho, e depois me receberás [em] glória."}, {"numero": 25, "texto": "A quem tenho no céu [além de ti] ? E [quando estou] contigo, nada há na terra que eu deseje."}, {"numero": 26, "texto": "Minha carne e meu coração desfalecem; [porém] Deus [será] a rocha do meu coração e minha porção para sempre."}, {"numero": 27, "texto": "Porque eis que os que ficaram longe de ti perecerão; tu destróis todo infiel a ti."}, {"numero": 28, "texto": "Mas [quanto] a mim, bom me é me aproximar de Deus; ponho minha confiança no Senhor DEUS, para que eu conte todas as tuas obras."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 73, 'en', '[{"numero": 1, "texto": "Truly God is good to Israel, even to such as are of a clean heart."}, {"numero": 2, "texto": "But as for me, my feet were almost gone; my steps had well nigh slipped."}, {"numero": 3, "texto": "For I was envious at the foolish, when I saw the prosperity of the wicked."}, {"numero": 4, "texto": "For there are no bands in their death: but their strength is firm."}, {"numero": 5, "texto": "They are not in trouble as other men; neither are they plagued like other men."}, {"numero": 6, "texto": "Therefore pride compasseth them about as a chain; violence covereth them as a garment."}, {"numero": 7, "texto": "Their eyes stand out with fatness: they have more than heart could wish."}, {"numero": 8, "texto": "They are corrupt, and speak wickedly concerning oppression: they speak loftily."}, {"numero": 9, "texto": "They set their mouth against the heavens, and their tongue walketh through the earth."}, {"numero": 10, "texto": "Therefore his people return hither: and waters of a full cup are wrung out to them."}, {"numero": 11, "texto": "And they say, How doth God know? and is there knowledge in the most High?"}, {"numero": 12, "texto": "Behold, these are the ungodly, who prosper in the world; they increase in riches."}, {"numero": 13, "texto": "Verily I have cleansed my heart in vain, and washed my hands in innocency."}, {"numero": 14, "texto": "For all the day long have I been plagued, and chastened every morning."}, {"numero": 15, "texto": "If I say, I will speak thus; behold, I should offend against the generation of thy children."}, {"numero": 16, "texto": "When I thought to know this, it was too painful for me;"}, {"numero": 17, "texto": "Until I went into the sanctuary of God; then understood I their end."}, {"numero": 18, "texto": "Surely thou didst set them in slippery places: thou castedst them down into destruction."}, {"numero": 19, "texto": "How are they brought into desolation, as in a moment! they are utterly consumed with terrors."}, {"numero": 20, "texto": "As a dream when one awaketh; so, O Lord, when thou awakest, thou shalt despise their image."}, {"numero": 21, "texto": "Thus my heart was grieved, and I was pricked in my reins."}, {"numero": 22, "texto": "So foolish was I, and ignorant: I was as a beast before thee."}, {"numero": 23, "texto": "Nevertheless I am continually with thee: thou hast holden me by my right hand."}, {"numero": 24, "texto": "Thou shalt guide me with thy counsel, and afterward receive me to glory."}, {"numero": 25, "texto": "Whom have I in heaven but thee? and there is none upon earth that I desire beside thee."}, {"numero": 26, "texto": "My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever."}, {"numero": 27, "texto": "For, lo, they that are far from thee shall perish: thou hast destroyed all them that go a whoring from thee."}, {"numero": 28, "texto": "But it is good for me to draw near to God: I have put my trust in the Lord God, that I may declare all thy works."}]'::jsonb, 'King James Version'),
  ('Sl', 73, 'fr', '[{"numero": 1, "texto": "Psaume d''''Asaph. Oui, Dieu est bon pour Israël, Pour ceux qui ont le coeur pur."}, {"numero": 2, "texto": "Toutefois, mon pied allait fléchir, Mes pas étaient sur le point de glisser;"}, {"numero": 3, "texto": "Car je portais envie aux insensés, En voyant le bonheur des méchants."}, {"numero": 4, "texto": "Rien ne les tourmente jusqu''''à leur mort, Et leur corps est chargé d''''embonpoint;"}, {"numero": 5, "texto": "Ils n''''ont aucune part aux souffrances humaines, Ils ne sont point frappés comme le reste des hommes."}, {"numero": 6, "texto": "Aussi l''''orgueil leur sert de collier, La violence est le vêtement qui les enveloppe;"}, {"numero": 7, "texto": "L''''iniquité sort de leurs entrailles, Les pensées de leur coeur se font jour."}, {"numero": 8, "texto": "Ils raillent, et parlent méchamment d''''opprimer; Ils profèrent des discours hautains,"}, {"numero": 9, "texto": "Ils élèvent leur bouche jusqu''''aux cieux, Et leur langue se promène sur la terre."}, {"numero": 10, "texto": "Voilà pourquoi son peuple se tourne de leur côté, Il avale l''''eau abondamment,"}, {"numero": 11, "texto": "Et il dit: Comment Dieu saurait-il, Comment le Très-Haut connaîtrait-il?"}, {"numero": 12, "texto": "Ainsi sont les méchants: Toujours heureux, ils accroissent leurs richesses."}, {"numero": 13, "texto": "C''''est donc en vain que j''''ai purifié mon coeur, Et que j''''ai lavé mes mains dans l''''innocence:"}, {"numero": 14, "texto": "Chaque jour je suis frappé, Tous les matins mon châtiment est là."}, {"numero": 15, "texto": "Si je disais: Je veux parler comme eux, Voici, je trahirais la race de tes enfants."}, {"numero": 16, "texto": "Quand j''''ai réfléchi là-dessus pour m''''éclairer, La difficulté fut grande à mes yeux,"}, {"numero": 17, "texto": "Jusqu''''à ce que j''''eusse pénétré dans les sanctuaires de Dieu, Et que j''''eusse pris garde au sort final des méchants."}, {"numero": 18, "texto": "Oui, tu les places sur des voies glissantes, Tu les fais tomber et les mets en ruines."}, {"numero": 19, "texto": "Eh quoi! en un instant les voilà détruits! Ils sont enlevés, anéantis par une fin soudaine!"}, {"numero": 20, "texto": "Comme un songe au réveil, Seigneur, à ton réveil, tu repousses leur image."}, {"numero": 21, "texto": "Lorsque mon coeur s''''aigrissait, Et que je me sentais percé dans les entrailles,"}, {"numero": 22, "texto": "J''''étais stupide et sans intelligence, J''''étais à ton égard comme les bêtes."}, {"numero": 23, "texto": "Cependant je suis toujours avec toi, Tu m''''as saisi la main droite;"}, {"numero": 24, "texto": "Tu me conduiras par ton conseil, Puis tu me recevras dans la gloire."}, {"numero": 25, "texto": "Quel autre ai-je au ciel que toi! Et sur la terre je ne prends plaisir qu''''en toi."}, {"numero": 26, "texto": "Ma chair et mon coeur peuvent se consumer: Dieu sera toujours le rocher de mon coeur et mon partage."}, {"numero": 27, "texto": "Car voici, ceux qui s''''éloignent de toi périssent; Tu anéantis tous ceux qui te sont infidèles."}, {"numero": 28, "texto": "Pour moi, m''''approcher de Dieu, c''''est mon bien: Je place mon refuge dans le Seigneur, l''''Eternel, Afin de raconter toutes tes oeuvres."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 73, 'es', '[{"numero": 1, "texto": "CIERTAMENTE bueno es Dios á Israel, á los limpios de corazón."}, {"numero": 2, "texto": "Mas yo, casi se deslizaron mis pies; por poco resbalaron mis pasos."}, {"numero": 3, "texto": "Porque tuve envidia de los insensatos, viendo la prosperidad de los impíos."}, {"numero": 4, "texto": "Porque no hay ataduras para su muerte; antes su fortaleza está entera."}, {"numero": 5, "texto": "No están ellos en el trabajo humano; ni son azotados con los otros hombres."}, {"numero": 6, "texto": "Por tanto soberbia los corona: cúbrense de vestido de violencia."}, {"numero": 7, "texto": "Sus ojos están salidos de gruesos: logran con creces los antojos del corazón."}, {"numero": 8, "texto": "Soltáronse, y hablan con maldad de hacer violencia; hablan con altanería."}, {"numero": 9, "texto": "Ponen en el cielo su boca, y su lengua pasea la tierra."}, {"numero": 10, "texto": "Por eso su pueblo vuelve aquí, y aguas de lleno les son exprimidas."}, {"numero": 11, "texto": "Y dicen: ¿Cómo sabe Dios? ¿y hay conocimiento en lo alto?"}, {"numero": 12, "texto": "He aquí estos impíos, sin ser turbados del mundo, alcanzaron riquezas."}, {"numero": 13, "texto": "Verdaderamente en vano he limpiado mi corazón, y lavado mis manos en inocencia;"}, {"numero": 14, "texto": "Pues he sido azotado todo el día, y empezaba mi castigo por las mañanas."}, {"numero": 15, "texto": "Si dijera yo, Discurriré de esa suerte; he aquí habría negado la nación de tus hijos:"}, {"numero": 16, "texto": "Pensaré pues para saber esto: es á mis ojos duro trabajo,"}, {"numero": 17, "texto": "Hasta que venido al santuario de Dios, entenderé la postrimería de ellos."}, {"numero": 18, "texto": "Ciertamente los has puesto en deslizaderos; en asolamientos los harás caer."}, {"numero": 19, "texto": "¡Cómo han sido asolados! ¡cuán en un punto! Acabáronse, fenecieron con turbaciones."}, {"numero": 20, "texto": "Como sueño del que despierta, así, Señor, cuando despertares, menospreciarás sus apariencias."}, {"numero": 21, "texto": "Desazonóse á la verdad mi corazón, y en mis riñones sentía punzadas."}, {"numero": 22, "texto": "Mas yo era ignorante, y no entendía: era como una bestia acerca de ti."}, {"numero": 23, "texto": "Con todo, yo siempre estuve contigo: trabaste de mi mano derecha."}, {"numero": 24, "texto": "Hasme guiado según tu consejo, y después me recibirás en gloria."}, {"numero": 25, "texto": "¿A quién tengo yo en los cielos? Y fuera de ti nada deseo en la tierra."}, {"numero": 26, "texto": "Mi carne y mi corazón desfallecen: mas la roca de mi corazón y mi porción es Dios para siempre."}, {"numero": 27, "texto": "Porque he aquí, los que se alejan de ti perecerán: tú cortarás á todo aquel que fornicando, de ti se aparta."}, {"numero": 28, "texto": "Y en cuanto á mí, el acercarme á Dios es el bien: he puesto en el Señor Jehová mi esperanza, para contar todas tus obras."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 84, 'pt', '[{"numero": 1, "texto": "Para o regente, com “Gitite”. Salmo dos filhos de Coré: Quão agradáveis são tuas moradas, SENHOR dos exércitos!"}, {"numero": 2, "texto": "Minha alma está desejosa, ao ponto de desmaiar, pelos pátios do SENHOR; meu coração e minha carne clamam ao Deus vivente."}, {"numero": 3, "texto": "Até o pardal acha casa, e a andorinha ninho para si, onde ponha filhotes perto de teus altares, ó SENHOR dos exércitos, Rei meu e Deus meu."}, {"numero": 4, "texto": "Bem-aventurados os que habitam em tua casa; eles louvam a ti continuamente. (Selá)"}, {"numero": 5, "texto": "Bem-aventurados aqueles cuja força está em ti, em cujos corações estão os caminhos [corretos] ."}, {"numero": 6, "texto": "Eles, ao passarem pelo Vale de Baca, fazem dele uma fonte; e a chuva o cobre de bênçãos."}, {"numero": 7, "texto": "Eles vão de força em força; [cada um deles] comparece diante de Deus em Sião."}, {"numero": 8, "texto": "SENHOR Deus dos exércitos, escuta minha oração; inclina os teus ouvidos, ó Deus de Jacó. (Selá)"}, {"numero": 9, "texto": "Olha o nosso escudo, ó Deus; e observa o rosto do teu ungido."}, {"numero": 10, "texto": "Porque melhor é um dia nos teus pátios, do que mil [fora] . Prefiro estar à porta da casa do meu Deus, a morar nas tendas dos perversos."}, {"numero": 11, "texto": "Porque o SENHOR Deus é sol e escudo; o SENHOR concederá graça e honra; ele não negará o bem aos que andam em integridade."}, {"numero": 12, "texto": "Ó SENHOR dos exércitos, bem-aventurado é o homem que confia em ti!"}]'::jsonb, 'Almeida Livre'),
  ('Sl', 84, 'en', '[{"numero": 1, "texto": "How amiable are thy tabernacles, O Lord of hosts!"}, {"numero": 2, "texto": "My soul longeth, yea, even fainteth for the courts of the Lord: my heart and my flesh crieth out for the living God."}, {"numero": 3, "texto": "Yea, the sparrow hath found an house, and the swallow a nest for herself, where she may lay her young, even thine altars, O Lord of hosts, my King, and my God."}, {"numero": 4, "texto": "Blessed are they that dwell in thy house: they will be still praising thee. Selah."}, {"numero": 5, "texto": "Blessed is the man whose strength is in thee; in whose heart are the ways of them."}, {"numero": 6, "texto": "Who passing through the valley of Baca make it a well; the rain also filleth the pools."}, {"numero": 7, "texto": "They go from strength to strength, every one of them in Zion appeareth before God."}, {"numero": 8, "texto": "O Lord God of hosts, hear my prayer: give ear, O God of Jacob. Selah."}, {"numero": 9, "texto": "Behold, O God our shield, and look upon the face of thine anointed."}, {"numero": 10, "texto": "For a day in thy courts is better than a thousand. I had rather be a doorkeeper in the house of my God, than to dwell in the tents of wickedness."}, {"numero": 11, "texto": "For the Lord God is a sun and shield: the Lord will give grace and glory: no good thing will he withhold from them that walk uprightly."}, {"numero": 12, "texto": "O Lord of hosts, blessed is the man that trusteth in thee."}]'::jsonb, 'King James Version'),
  ('Sl', 84, 'fr', '[{"numero": 1, "texto": "Au chef des chantres. Sur la guitthith. Des fils de Koré. Psaume. Que tes demeures sont aimables, Eternel des armées!"}, {"numero": 2, "texto": "Mon âme soupire et languit après les parvis de l''''Eternel, Mon coeur et ma chair poussent des cris vers le Dieu vivant."}, {"numero": 3, "texto": "Le passereau même trouve une maison, Et l''''hirondelle un nid où elle dépose ses petits... Tes autels, Eternel des armées! Mon roi et mon Dieu!"}, {"numero": 4, "texto": "Heureux ceux qui habitent ta maison! Ils peuvent te célébrer encore. Pause."}, {"numero": 5, "texto": "Heureux ceux qui placent en toi leur appui! Ils trouvent dans leur coeur des chemins tout tracés."}, {"numero": 6, "texto": "Lorsqu''''ils traversent la vallée de Baca, Ils la transforment en un lieu plein de sources, Et la pluie la couvre aussi de bénédictions."}, {"numero": 7, "texto": "Leur force augmente pendant la marche, Et ils se présentent devant Dieu à Sion."}, {"numero": 8, "texto": "Eternel, Dieu des armées, écoute ma prière! Prête l''''oreille, Dieu de Jacob! Pause."}, {"numero": 9, "texto": "Toi qui es notre bouclier, vois, ô Dieu! Et regarde la face de ton oint!"}, {"numero": 10, "texto": "Mieux vaut un jour dans tes parvis que mille ailleurs; Je préfère me tenir sur le seuil de la maison de mon Dieu, Plutôt que d''''habiter sous les tentes de la méchanceté."}, {"numero": 11, "texto": "Car l''''Eternel Dieu est un soleil et un bouclier, L''''Eternel donne la grâce et la gloire, Il ne refuse aucun bien à ceux qui marchent dans l''''intégrité."}, {"numero": 12, "texto": "Eternel des armées! Heureux l''''homme qui se confie en toi!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 84, 'es', '[{"numero": 1, "texto": "¡CUÁN amables son tus moradas, oh Jehová de los ejércitos!"}, {"numero": 2, "texto": "Codicia y aun ardientemente desea mi alma los atrios de Jehová: mi corazón y mi carne cantan al Dios vivo."}, {"numero": 3, "texto": "Aun el gorrión halla casa, y la golondrina nido para sí, donde ponga sus pollos en tus altares, oh Jehová de los ejércitos, rey mío, y Dios mío."}, {"numero": 4, "texto": "Bienaventurados los que habitan en tu casa: perpetuamente te alabarán. (Selah.)"}, {"numero": 5, "texto": "Bienaventurado el hombre que tiene su fortaleza en ti; en cuyo corazón están tus caminos."}, {"numero": 6, "texto": "Atravesando el valle de Baca pónenle por fuente, cuando la lluvia llena los estanques."}, {"numero": 7, "texto": "Irán de fortaleza en fortaleza, verán á Dios en Sión."}, {"numero": 8, "texto": "Jehová Dios de los ejércitos, oye mi oración: escucha, oh Dios de Jacob. (Selah.)"}, {"numero": 9, "texto": "Mira, oh Dios, escudo nuestro, y pon los ojos en el rostro de tu ungido."}, {"numero": 10, "texto": "Porque mejor es un día en tus atrios que mil fuera de ellos: escogería antes estar á la puerta de la casa de mi Dios, que habitar en las moradas de maldad."}, {"numero": 11, "texto": "Porque sol y escudo es Jehová Dios: gracia y gloria dará Jehová: no quitará el bien á los que en integridad andan."}, {"numero": 12, "texto": "Jehová de los ejércitos, dichoso el hombre que en ti confía."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 90, 'pt', '[{"numero": 1, "texto": "Oração de Moisés, homem de Deus: Senhor, tu tens sido nossa habitação, de geração em geração."}, {"numero": 2, "texto": "Antes que os montes surgissem, e tu produzisses a terra e o mundo, desde à eternidade até a eternidade tu és Deus."}, {"numero": 3, "texto": "Tu fazes o homem voltar ao pó, e dizes: Retornai-vos, filhos dos homens!"}, {"numero": 4, "texto": "Porque mil anos aos teus olhos são como o dia de ontem, que passou, e como a vigília da noite."}, {"numero": 5, "texto": "Tu os levas como correntes de águas; são como o sono; de madrugada são como a erva que brota:"}, {"numero": 6, "texto": "De madrugada floresce, e brota; à tarde é cortada, e se seca."}, {"numero": 7, "texto": "Porque perecemos com tua ira, e nos assombramos com teu furor."}, {"numero": 8, "texto": "Tu pões nossas perversidades perante ti, nosso [pecado] oculto [perante] a luz do teu rosto."}, {"numero": 9, "texto": "Porque todos os nossos dias se vão por causa de tua irritação; acabamos nossos anos como um suspiro."}, {"numero": 10, "texto": "Os dias de nossa vida [chegam até] os setenta anos; e os que são mais fortes, até os oitenta anos; e o melhor deles é canseira e opressão, porque logo é cortado, e saímos voando."}, {"numero": 11, "texto": "Quem conhece a força de tua ira? O teu furor é conforme o temor a ti."}, {"numero": 12, "texto": "Ensina [-nos] a contar nossos dias de tal maneira que alcancemos um coração sábio."}, {"numero": 13, "texto": "Retorna, SENHOR! Até quando? [Tem] compaixão para com teus servos."}, {"numero": 14, "texto": "Farta-nos de manhã com tua bondade; e nos alegraremos e seremos cheios de alegria por todos os nossos dias."}, {"numero": 15, "texto": "Alegra-nos conforme os dias [em que] tu nos afligiste, os anos [em que] vimos o mal."}, {"numero": 16, "texto": "Que tua obra apareça aos teus servos, e tua glória sobre seus filhos."}, {"numero": 17, "texto": "E que o agrado do SENHOR nosso Deus seja sobre nós; e confirma as obras de nossas mãos sobre nós; sim, a obra de nossas mãos, confirma!"}]'::jsonb, 'Almeida Livre'),
  ('Sl', 90, 'en', '[{"numero": 1, "texto": "Lord, thou hast been our dwelling place in all generations."}, {"numero": 2, "texto": "Before the mountains were brought forth, or ever thou hadst formed the earth and the world, even from everlasting to everlasting, thou art God."}, {"numero": 3, "texto": "Thou turnest man to destruction; and sayest, Return, ye children of men."}, {"numero": 4, "texto": "For a thousand years in thy sight are but as yesterday when it is past, and as a watch in the night."}, {"numero": 5, "texto": "Thou carriest them away as with a flood; they are as a sleep: in the morning they are like grass which groweth up."}, {"numero": 6, "texto": "In the morning it flourisheth, and groweth up; in the evening it is cut down, and withereth."}, {"numero": 7, "texto": "For we are consumed by thine anger, and by thy wrath are we troubled."}, {"numero": 8, "texto": "Thou hast set our iniquities before thee, our secret sins in the light of thy countenance."}, {"numero": 9, "texto": "For all our days are passed away in thy wrath: we spend our years as a tale that is told."}, {"numero": 10, "texto": "The days of our years are threescore years and ten; and if by reason of strength they be fourscore years, yet is their strength labour and sorrow; for it is soon cut off, and we fly away."}, {"numero": 11, "texto": "Who knoweth the power of thine anger? even according to thy fear, so is thy wrath."}, {"numero": 12, "texto": "So teach us to number our days, that we may apply our hearts unto wisdom."}, {"numero": 13, "texto": "Return, O Lord, how long? and let it repent thee concerning thy servants."}, {"numero": 14, "texto": "O satisfy us early with thy mercy; that we may rejoice and be glad all our days."}, {"numero": 15, "texto": "Make us glad according to the days wherein thou hast afflicted us, and the years wherein we have seen evil."}, {"numero": 16, "texto": "Let thy work appear unto thy servants, and thy glory unto their children."}, {"numero": 17, "texto": "And let the beauty of the Lord our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it."}]'::jsonb, 'King James Version'),
  ('Sl', 90, 'fr', '[{"numero": 1, "texto": "Prière de Moïse, homme de Dieu. Seigneur! tu as été pour nous un refuge, De génération en génération."}, {"numero": 2, "texto": "Avant que les montagnes fussent nées, Et que tu eusses créé la terre et le monde, D''''éternité en éternité tu es Dieu."}, {"numero": 3, "texto": "Tu fais rentrer les hommes dans la poussière, Et tu dis: Fils de l''''homme, retournez!"}, {"numero": 4, "texto": "Car mille ans sont, à tes yeux, Comme le jour d''''hier, quand il n''''est plus, Et comme une veille de la nuit."}, {"numero": 5, "texto": "Tu les emportes, semblables à un songe, Qui, le matin, passe comme l''''herbe:"}, {"numero": 6, "texto": "Elle fleurit le matin, et elle passe, On la coupe le soir, et elle sèche."}, {"numero": 7, "texto": "Nous sommes consumés par ta colère, Et ta fureur nous épouvante."}, {"numero": 8, "texto": "Tu mets devant toi nos iniquités, Et à la lumière de ta face nos fautes cachées."}, {"numero": 9, "texto": "Tous nos jours disparaissent par ton courroux; Nous voyons nos années s''''évanouir comme un son."}, {"numero": 10, "texto": "Les jours de nos années s''''élèvent à soixante-dix ans, Et, pour les plus robustes, à quatre-vingts ans; Et l''''orgueil qu''''ils en tirent n''''est que peine et misère, Car il passe vite, et nous nous envolons."}, {"numero": 11, "texto": "Qui prend garde à la force de ta colère, Et à ton courroux, selon la crainte qui t''''est due?"}, {"numero": 12, "texto": "Enseigne-nous à bien compter nos jours, Afin que nous appliquions notre coeur à la sagesse."}, {"numero": 13, "texto": "Reviens, Eternel! Jusques à quand?... Aie pitié de tes serviteurs!"}, {"numero": 14, "texto": "Rassasie-nous chaque matin de ta bonté, Et nous serons toute notre vie dans la joie et l''''allégresse."}, {"numero": 15, "texto": "Réjouis-nous autant de jours que tu nous as humiliés, Autant d''''années que nous avons vu le malheur."}, {"numero": 16, "texto": "Que ton oeuvre se manifeste à tes serviteurs, Et ta gloire sur leurs enfants!"}, {"numero": 17, "texto": "Que la grâce de l''''Eternel, notre Dieu, soit sur nous! Affermis l''''ouvrage de nos mains, Oui, affermis l''''ouvrage de nos mains!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 90, 'es', '[{"numero": 1, "texto": "SEÑOR, tú nos has sido refugio en generación y en generación."}, {"numero": 2, "texto": "Antes que naciesen los montes, y formases la tierra y el mundo, y desde el siglo y hasta el siglo, tú eres Dios."}, {"numero": 3, "texto": "Vuelves al hombre hasta ser quebrantado, y dices: Convertíos, hijos de los hombres."}, {"numero": 4, "texto": "Porque mil años delante de tus ojos, son como el día de ayer, que pasó, y como una de las vigilias de la noche."}, {"numero": 5, "texto": "Háceslos pasar como avenida de aguas; son como sueño; como la hierba que crece en la mañana:"}, {"numero": 6, "texto": "En la mañana florece y crece; á la tarde es cortada, y se seca."}, {"numero": 7, "texto": "Porque con tu furor somos consumidos, y con tu ira somos conturbados."}, {"numero": 8, "texto": "Pusiste nuestras maldades delante de ti, nuestros yerros á la luz de tu rostro."}, {"numero": 9, "texto": "Porque todos nuestros días declinan á causa de tu ira; acabamos nuestros años como un pensamiento."}, {"numero": 10, "texto": "Los días de nuestra edad son setenta años; que si en los más robustos son ochenta años, con todo su fortaleza es molestia y trabajo; porque es cortado presto, y volamos."}, {"numero": 11, "texto": "¿Quién conoce la fortaleza de tu ira, y tu indignación según que debes ser temido?"}, {"numero": 12, "texto": "Enséñanos de tal modo á contar nuestros días, que traigamos al corazón sabiduría."}, {"numero": 13, "texto": "Vuélvete, oh Jehová: ¿hasta cuándo? y aplácate para con tus siervos."}, {"numero": 14, "texto": "Sácianos presto de tu misericordia: y cantaremos y nos alegraremos todos nuestros días."}, {"numero": 15, "texto": "Alégranos conforme á los días que nos afligiste, y los años que vimos mal."}, {"numero": 16, "texto": "Aparezca en tus siervos tu obra, y tu gloria sobre sus hijos."}, {"numero": 17, "texto": "Y sea la luz de Jehová nuestro Dios sobre nosotros: y ordena en nosotros la obra de nuestras manos, la obra de nuestras manos confirma."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 91, 'pt', '[{"numero": 1, "texto": "Aquele que mora no esconderijo do Altíssimo, à sombra do Todo-Poderoso habitará."}, {"numero": 2, "texto": "Direi ao SENHOR: [Tu és] meu refúgio e minha fortaleza; Deus meu, em quem confio."}, {"numero": 3, "texto": "Porque ele te livrará do laço do caçador e da peste maligna."}, {"numero": 4, "texto": "Com suas penas ele te cobrirá, e debaixo de suas asas estarás protegido; a verdade dele é escudo grande e protetor."}, {"numero": 5, "texto": "Não terás medo do terror da noite, [nem] da flecha que voa de dia;"}, {"numero": 6, "texto": "[Nem] da peste que anda às escuras, [nem] da mortandade que assola ao meio-dia."}, {"numero": 7, "texto": "Cairão mil ao teu lado, e dez mil à tua direita, [mas] a ti nada alcançará."}, {"numero": 8, "texto": "Somente verás com teus olhos, e observarás o pagamento dos perversos;"}, {"numero": 9, "texto": "Porque tu fizeste como morada ao SENHOR: o meu refúgio, o Altíssimo."}, {"numero": 10, "texto": "Mal nenhum te sucederá, nem praga alguma chegará à tua tenda;"}, {"numero": 11, "texto": "Porque ele ordenou aos anjos quanto a ti, para que guardem todos os teus caminhos."}, {"numero": 12, "texto": "Pelas mãos te levarão, para que não tropeces teu pé em alguma pedra."}, {"numero": 13, "texto": "Tu pisarás sobre o leão e a cobra; passarás esmagando ao filho do leão e à serpente."}, {"numero": 14, "texto": "Por ele ter me amado tanto, eu também o livrarei; em alto retiro eu o porei, porque ele conhece o meu nome."}, {"numero": 15, "texto": "Ele me chamará, e eu o responderei; estarei com ele na angústia; [dela] eu o livrarei, e o honrarei."}, {"numero": 16, "texto": "Eu o satisfarei com uma longa vida , e lhe mostrarei a minha salvação."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 91, 'en', '[{"numero": 1, "texto": "He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty."}, {"numero": 2, "texto": "I will say of the Lord, He is my refuge and my fortress: my God; in him will I trust."}, {"numero": 3, "texto": "Surely he shall deliver thee from the snare of the fowler, and from the noisome pestilence."}, {"numero": 4, "texto": "He shall cover thee with his feathers, and under his wings shalt thou trust: his truth shall be thy shield and buckler."}, {"numero": 5, "texto": "Thou shalt not be afraid for the terror by night; nor for the arrow that flieth by day;"}, {"numero": 6, "texto": "Nor for the pestilence that walketh in darkness; nor for the destruction that wasteth at noonday."}, {"numero": 7, "texto": "A thousand shall fall at thy side, and ten thousand at thy right hand; but it shall not come nigh thee."}, {"numero": 8, "texto": "Only with thine eyes shalt thou behold and see the reward of the wicked."}, {"numero": 9, "texto": "Because thou hast made the Lord, which is my refuge, even the most High, thy habitation;"}, {"numero": 10, "texto": "There shall no evil befall thee, neither shall any plague come nigh thy dwelling."}, {"numero": 11, "texto": "For he shall give his angels charge over thee, to keep thee in all thy ways."}, {"numero": 12, "texto": "They shall bear thee up in their hands, lest thou dash thy foot against a stone."}, {"numero": 13, "texto": "Thou shalt tread upon the lion and adder: the young lion and the dragon shalt thou trample under feet."}, {"numero": 14, "texto": "Because he hath set his love upon me, therefore will I deliver him: I will set him on high, because he hath known my name."}, {"numero": 15, "texto": "He shall call upon me, and I will answer him: I will be with him in trouble; I will deliver him, and honour him."}, {"numero": 16, "texto": "With long life will I satisfy him, and shew him my salvation."}]'::jsonb, 'King James Version'),
  ('Sl', 91, 'fr', '[{"numero": 1, "texto": "Celui qui demeure sous l''''abri du Très-Haut Repose à l''''ombre du Tout Puissant."}, {"numero": 2, "texto": "Je dis à l''''Eternel: Mon refuge et ma forteresse, Mon Dieu en qui je me confie!"}, {"numero": 3, "texto": "Car c''''est lui qui te délivre du filet de l''''oiseleur, De la peste et de ses ravages."}, {"numero": 4, "texto": "Il te couvrira de ses plumes, Et tu trouveras un refuge sous ses ailes; Sa fidélité est un bouclier et une cuirasse."}, {"numero": 5, "texto": "Tu ne craindras ni les terreurs de la nuit, Ni la flèche qui vole de jour,"}, {"numero": 6, "texto": "Ni la peste qui marche dans les ténèbres, Ni la contagion qui frappe en plein midi."}, {"numero": 7, "texto": "Que mille tombent à ton côté, Et dix mille à ta droite, Tu ne seras pas atteint;"}, {"numero": 8, "texto": "De tes yeux seulement tu regarderas, Et tu verras la rétribution des méchants."}, {"numero": 9, "texto": "Car tu es mon refuge, ô Eternel! Tu fais du Très-Haut ta retraite."}, {"numero": 10, "texto": "Aucun malheur ne t''''arrivera, Aucun fléau n''''approchera de ta tente."}, {"numero": 11, "texto": "Car il ordonnera à ses anges De te garder dans toutes tes voies;"}, {"numero": 12, "texto": "Ils te porteront sur les mains, De peur que ton pied ne heurte contre une pierre."}, {"numero": 13, "texto": "Tu marcheras sur le lion et sur l''''aspic, Tu fouleras le lionceau et le dragon."}, {"numero": 14, "texto": "Puisqu''''il m''''aime, je le délivrerai; Je le protégerai, puisqu''''il connaît mon nom."}, {"numero": 15, "texto": "Il m''''invoquera, et je lui répondrai; Je serai avec lui dans la détresse, Je le délivrerai et je le glorifierai."}, {"numero": 16, "texto": "Je le rassasierai de longs jours, Et je lui ferai voir mon salut."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 91, 'es', '[{"numero": 1, "texto": "EL que habita al abrigo del Altísimo, morará bajo la sombra del Omnipotente."}, {"numero": 2, "texto": "Diré yo á Jehová: Esperanza mía, y castillo mío; mi Dios, en él confiaré."}, {"numero": 3, "texto": "Y él te librará del lazo del cazador: de la peste destruidora."}, {"numero": 4, "texto": "Con sus plumas te cubrirá, y debajo de sus alas estarás seguro: escudo y adarga es su verdad."}, {"numero": 5, "texto": "No tendrás temor de espanto nocturno, ni de saeta que vuele de día;"}, {"numero": 6, "texto": "Ni de pestilencia que ande en oscuridad, ni de mortandad que en medio del día destruya."}, {"numero": 7, "texto": "Caerán á tu lado mil, y diez mil á tu diestra: mas á ti no llegará."}, {"numero": 8, "texto": "Ciertamente con tus ojos mirarás, y verás la recompensa de los impíos."}, {"numero": 9, "texto": "Porque tú has puesto á Jehová, que es mi esperanza, al Altísimo por tu habitación,"}, {"numero": 10, "texto": "No te sobrevendrá mal, ni plaga tocará tu morada."}, {"numero": 11, "texto": "Pues que á sus ángeles mandará acerca de ti, que te guarden en todos tus caminos."}, {"numero": 12, "texto": "En las manos te llevarán, porque tu pie no tropiece en piedra."}, {"numero": 13, "texto": "Sobre el león y el basilisco pisarás; hollarás al cachorro del león y al dragón."}, {"numero": 14, "texto": "Por cuanto en mí ha puesto su voluntad, yo también lo libraré: pondrélo en alto, por cuanto ha conocido mi nombre."}, {"numero": 15, "texto": "Me invocará, y yo le responderé: con él estaré yo en la angustia: lo libraré, y le glorificaré."}, {"numero": 16, "texto": "Saciarélo de larga vida, y mostraréle mi salud."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 92, 'pt', '[{"numero": 1, "texto": "Salmo e cântico para o dia do Sábado: Bom é louvar ao SENHOR, e cantar louvores ao teu nome, ó Altíssimo;"}, {"numero": 2, "texto": "Para anunciar tua bondade pela manhã, e tua fidelidade durante as noites."}, {"numero": 3, "texto": "Com o instrumento de dez cordas, com a lira, e com música de harpa."}, {"numero": 4, "texto": "Porque tu, SENHOR, tens me alegrado com teus feitos; cantarei de alegria pelas obras de tuas mãos."}, {"numero": 5, "texto": "Ó SENHOR, como são grandes tuas obras! Muito profundos são teus pensamentos!"}, {"numero": 6, "texto": "O homem bruto não os conhece, nem o tolo entende isto."}, {"numero": 7, "texto": "Quando os perversos crescem como a erva, e florescem todos os praticantes de maldade, [assim então] serão destruídos para sempre."}, {"numero": 8, "texto": "Mas tu és Altíssimo para sempre, SENHOR."}, {"numero": 9, "texto": "Porque eis que teus inimigos, SENHOR, porque eis que teus inimigos pereceram; serão dispersos todos os praticantes de maldade."}, {"numero": 10, "texto": "Porém tu exaltaste o meu poder, como que um chifre de touro selvagem; eu fui ungido com óleo fresco."}, {"numero": 11, "texto": "E meus olhos verão [o fim] dos meus inimigos; meus ouvidos ouvirão [o fim] dos malfeitores que se levantam contra mim."}, {"numero": 12, "texto": "O justo florescerá como a palma; crescerá como o cedro do Líbano."}, {"numero": 13, "texto": "Os [justos] estão plantados na casa do SENHOR, crescerão nos pátios do nosso Deus."}, {"numero": 14, "texto": "[Até] na velhice ainda darão fruto; serão fortes e verdes;"}, {"numero": 15, "texto": "Para anunciarem que o SENHOR é correto; ele é minha rocha, e não há perversidade nele."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 92, 'en', '[{"numero": 1, "texto": "It is a good thing to give thanks unto the Lord, and to sing praises unto thy name, O Most High:"}, {"numero": 2, "texto": "To shew forth thy lovingkindness in the morning, and thy faithfulness every night,"}, {"numero": 3, "texto": "Upon an instrument of ten strings, and upon the psaltery; upon the harp with a solemn sound."}, {"numero": 4, "texto": "For thou, Lord, hast made me glad through thy work: I will triumph in the works of thy hands."}, {"numero": 5, "texto": "O Lord, how great are thy works! and thy thoughts are very deep."}, {"numero": 6, "texto": "A brutish man knoweth not; neither doth a fool understand this."}, {"numero": 7, "texto": "When the wicked spring as the grass, and when all the workers of iniquity do flourish; it is that they shall be destroyed for ever:"}, {"numero": 8, "texto": "But thou, Lord, art most high for evermore."}, {"numero": 9, "texto": "For, lo, thine enemies, O Lord, for, lo, thine enemies shall perish; all the workers of iniquity shall be scattered."}, {"numero": 10, "texto": "But my horn shalt thou exalt like the horn of an unicorn: I shall be anointed with fresh oil."}, {"numero": 11, "texto": "Mine eye also shall see my desire on mine enemies, and mine ears shall hear my desire of the wicked that rise up against me."}, {"numero": 12, "texto": "The righteous shall flourish like the palm tree: he shall grow like a cedar in Lebanon."}, {"numero": 13, "texto": "Those that be planted in the house of the Lord shall flourish in the courts of our God."}, {"numero": 14, "texto": "They shall still bring forth fruit in old age; they shall be fat and flourishing;"}, {"numero": 15, "texto": "To shew that the Lord is upright: he is my rock, and there is no unrighteousness in him."}]'::jsonb, 'King James Version'),
  ('Sl', 92, 'fr', '[{"numero": 1, "texto": "Psaume. Cantique pour le jour du sabbat. Il est beau de louer l''''Eternel, Et de célébrer ton nom, ô Très-Haut!"}, {"numero": 2, "texto": "D''''annoncer le matin ta bonté, Et ta fidélité pendant les nuits,"}, {"numero": 3, "texto": "Sur l''''instrument à dix cordes et sur le luth, Aux sons de la harpe."}, {"numero": 4, "texto": "Tu me réjouis par tes oeuvres, ô Eternel! Et je chante avec allégresse l''''ouvrage de tes mains."}, {"numero": 5, "texto": "Que tes oeuvres sont grandes, ô Eternel! Que tes pensées sont profondes!"}, {"numero": 6, "texto": "L''''homme stupide n''''y connaît rien, Et l''''insensé n''''y prend point garde."}, {"numero": 7, "texto": "Si les méchants croissent comme l''''herbe, Si tous ceux qui font le mal fleurissent, C''''est pour être anéantis à jamais."}, {"numero": 8, "texto": "Mais toi, tu es le Très-Haut, A perpétuité, ô Eternel!"}, {"numero": 9, "texto": "Car voici, tes ennemis, ô Eternel! Car voici, tes ennemis périssent; Tous ceux qui font le mal sont dispersés."}, {"numero": 10, "texto": "Et tu me donnes la force du buffle; Je suis arrosé avec une huile fraîche."}, {"numero": 11, "texto": "Mon oeil se plaît à contempler mes ennemis, Et mon oreille à entendre mes méchants adversaires."}, {"numero": 12, "texto": "Les justes croissent comme le palmier, Ils s''''élèvent comme le cèdre du Liban."}, {"numero": 13, "texto": "Plantés dans la maison de l''''Eternel, Ils prospèrent dans les parvis de notre Dieu;"}, {"numero": 14, "texto": "Ils portent encore des fruits dans la vieillesse, Ils sont pleins de sève et verdoyants,"}, {"numero": 15, "texto": "Pour faire connaître que l''''Eternel est juste. Il est mon rocher, et il n''''y a point en lui d''''iniquité."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 92, 'es', '[{"numero": 1, "texto": "BUENO es alabar á Jehová, y cantar salmos á tu nombre, oh Altísimo;"}, {"numero": 2, "texto": "Anunciar por la mañana tu misericordia, y tu verdad en las noches,"}, {"numero": 3, "texto": "En el decacordio y en el salterio, en tono suave con el arpa."}, {"numero": 4, "texto": "Por cuanto me has alegrado, oh Jehová, con tus obras; en las obras de tus manos me gozo."}, {"numero": 5, "texto": "¡Cuán grandes son tus obras, oh Jehová! Muy profundos son tus pensamientos."}, {"numero": 6, "texto": "El hombre necio no sabe, y el insensato no entiende esto:"}, {"numero": 7, "texto": "Que brotan los impíos como la hierba, y florecen todos los que obran iniquidad, para ser destruídos para siempre."}, {"numero": 8, "texto": "Mas tú, Jehová, para siempre eres Altísimo."}, {"numero": 9, "texto": "Porque he aquí tus enemigos, oh Jehová, porque he aquí, perecerán tus enemigos; serán disipados todos los que obran maldad."}, {"numero": 10, "texto": "Empero tú ensalzarás mi cuerno como el de unicornio: seré ungido con aceite fresco."}, {"numero": 11, "texto": "Y mirarán mis ojos sobre mis enemigos: oirán mis oídos de los que se levantaron contra mí, de los malignos."}, {"numero": 12, "texto": "El justo florecerá como la palma: crecerá como cedro en el Líbano."}, {"numero": 13, "texto": "Plantados en la casa de Jehová, en los atrios de nuestro Dios florecerán."}, {"numero": 14, "texto": "Aun en la vejez fructificarán; estarán vigorosos y verdes;"}, {"numero": 15, "texto": "Para anunciar que Jehová mi fortaleza es recto, y que en él no hay injusticia."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 97, 'pt', '[{"numero": 1, "texto": "O SENHOR reina; que a terra se encha de alegria; alegrem-se as muitas ilhas."}, {"numero": 2, "texto": "Nuvens e escuridão há ao redor dele; justiça e juízo são a base de seu trono."}, {"numero": 3, "texto": "Fogo vai adiante dele, que inflama seus adversários ao redor."}, {"numero": 4, "texto": "Seus relâmpagos iluminam o mundo; a terra os vê, e treme."}, {"numero": 5, "texto": "Os montes se derretem como cera na presença do SENHOR, na presença do Senhor de toda a terra."}, {"numero": 6, "texto": "Os céus anunciam sua justiça, e todos os povos veem sua glória."}, {"numero": 7, "texto": "Sejam envergonhados todos os que servem a imagens, e os que se orgulham de ídolos; prostrai-vos diante dele todos os deuses."}, {"numero": 8, "texto": "Sião ouviu, e se alegrou; e as filhas de Judá tiveram muita alegria, por causa de teus juízos, SENHOR;"}, {"numero": 9, "texto": "Pois tu, SENHOR, és o Altíssimo sobre toda a terra; tu és muito mais elevado que todos os deuses."}, {"numero": 10, "texto": "Vós que amais ao SENHOR: odiai o mal; ele guarda a alma de seus santos, [e] os resgata da mão dos perversos."}, {"numero": 11, "texto": "A luz é semeada para o justo, e a alegria para os corretos de coração."}, {"numero": 12, "texto": "Vós justos, alegrai-vos no SENHOR; e agradecei em memória de sua santidade."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 97, 'en', '[{"numero": 1, "texto": "The Lord reigneth; let the earth rejoice; let the multitude of isles be glad thereof."}, {"numero": 2, "texto": "Clouds and darkness are round about him: righteousness and judgment are the habitation of his throne."}, {"numero": 3, "texto": "A fire goeth before him, and burneth up his enemies round about."}, {"numero": 4, "texto": "His lightnings enlightened the world: the earth saw, and trembled."}, {"numero": 5, "texto": "The hills melted like wax at the presence of the Lord, at the presence of the Lord of the whole earth."}, {"numero": 6, "texto": "The heavens declare his righteousness, and all the people see his glory."}, {"numero": 7, "texto": "Confounded be all they that serve graven images, that boast themselves of idols: worship him, all ye gods."}, {"numero": 8, "texto": "Zion heard, and was glad; and the daughters of Judah rejoiced because of thy judgments, O Lord."}, {"numero": 9, "texto": "For thou, Lord, art high above all the earth: thou art exalted far above all gods."}, {"numero": 10, "texto": "Ye that love the Lord, hate evil: he preserveth the souls of his saints; he delivereth them out of the hand of the wicked."}, {"numero": 11, "texto": "Light is sown for the righteous, and gladness for the upright in heart."}, {"numero": 12, "texto": "Rejoice in the Lord, ye righteous; and give thanks at the remembrance of his holiness."}]'::jsonb, 'King James Version'),
  ('Sl', 97, 'fr', '[{"numero": 1, "texto": "L''''Eternel règne: que la terre soit dans l''''allégresse, Que les îles nombreuses se réjouissent!"}, {"numero": 2, "texto": "Les nuages et l''''obscurité l''''environnent, La justice et l''''équité sont la base de son trône."}, {"numero": 3, "texto": "Le feu marche devant lui, Et embrase à l''''entour ses adversaires."}, {"numero": 4, "texto": "Ses éclairs illuminent le monde, La terre le voit et tremble;"}, {"numero": 5, "texto": "Les montagnes se fondent comme la cire devant l''''Eternel, Devant le Seigneur de toute la terre."}, {"numero": 6, "texto": "Les cieux publient sa justice, Et tous les peuples voient sa gloire."}, {"numero": 7, "texto": "Ils sont confus, tous ceux qui servent les images, Qui se font gloire des idoles. Tous les dieux se prosternent devant lui."}, {"numero": 8, "texto": "Sion l''''entend et se réjouit, Les filles de Juda sont dans l''''allégresse, A cause de tes jugements, ô Eternel!"}, {"numero": 9, "texto": "Car toi, Eternel! tu es le Très-Haut sur toute la terre, Tu es souverainement élevé au-dessus de tous les dieux."}, {"numero": 10, "texto": "Vous qui aimez l''''Eternel, haïssez le mal! Il garde les âmes de ses fidèles, Il les délivre de la main des méchants."}, {"numero": 11, "texto": "La lumière est semée pour le juste, Et la joie pour ceux dont le coeur est droit."}, {"numero": 12, "texto": "Justes, réjouissez-vous en l''''Eternel, Et célébrez par vos louanges sa sainteté!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 97, 'es', '[{"numero": 1, "texto": "JEHOVÁ reinó: regocíjese la tierra: alégrense las muchas islas."}, {"numero": 2, "texto": "Nube y oscuridad alrededor de él: justicia y juicio son el asiento de su trono."}, {"numero": 3, "texto": "Fuego irá delante de él, y abrasará en derredor sus enemigos."}, {"numero": 4, "texto": "Sus relámpagos alumbraron el mundo: la tierra vió, y estremecióse."}, {"numero": 5, "texto": "Los montes se derritieron como cera delante de Jehová, delante del Señor de toda la tierra."}, {"numero": 6, "texto": "Los cielos denunciaron su justicia, y todos los pueblos vieron su gloria."}, {"numero": 7, "texto": "Avergüéncense todos los que sirven á las imágenes de talla, los que se alaban de los ídolos: los dioses todos á él se encorven."}, {"numero": 8, "texto": "Oyó Sión, y alegróse; y las hijas de Judá, oh Jehová, se gozaron por tus juicios."}, {"numero": 9, "texto": "Porque tú, Jehová, eres alto sobre toda la tierra: eres muy ensalzado sobre todos los dioses."}, {"numero": 10, "texto": "Los que á Jehová amáis, aborreced el mal: guarda él las almas de sus santos; de mano de los impíos los libra."}, {"numero": 11, "texto": "Luz está sembrada para el justo, y alegría para los rectos de corazón."}, {"numero": 12, "texto": "Alegraos, justos, en Jehová: y alabad la memoria de su santidad."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 98, 'pt', '[{"numero": 1, "texto": "Salmo: Cantai ao SENHOR uma canção nova, porque ele fez maravilhas; sua mão direita e seu santo braço lhe fez ter a salvação."}, {"numero": 2, "texto": "O SENHOR fez ser conhecida sua salvação; perante os olhos das nações ele mostrou sua justiça."}, {"numero": 3, "texto": "Ele se lembrou de sua bondade e de sua fidelidade para com a casa de Israel; todos os confins da terra viram a salvação de nosso Deus."}, {"numero": 4, "texto": "Gritai de alegria ao SENHOR, toda a terra; clamai, cantai alegres, e tocai salmos."}, {"numero": 5, "texto": "Tocai ao SENHOR com harpa; com harpa, e com a voz da música;"}, {"numero": 6, "texto": "Com trombetas, e som de cornetas, clamai alegremente diante do Rei SENHOR."}, {"numero": 7, "texto": "Faça barulho o mar com sua plenitude; o mundo com os que nele habitam."}, {"numero": 8, "texto": "Que os rios batam palmas, que as montanhas juntamente se alegrem,"}, {"numero": 9, "texto": "Diante do SENHOR, porque ele vem para julgar a terra; ele julgará ao mundo com justiça, e aos povos de forma correta."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 98, 'en', '[{"numero": 1, "texto": "O sing unto the Lord a new song; for he hath done marvellous things: his right hand, and his holy arm, hath gotten him the victory."}, {"numero": 2, "texto": "The Lord hath made known his salvation: his righteousness hath he openly shewed in the sight of the heathen."}, {"numero": 3, "texto": "He hath remembered his mercy and his truth toward the house of Israel: all the ends of the earth have seen the salvation of our God."}, {"numero": 4, "texto": "Make a joyful noise unto the Lord, all the earth: make a loud noise, and rejoice, and sing praise."}, {"numero": 5, "texto": "Sing unto the Lord with the harp; with the harp, and the voice of a psalm."}, {"numero": 6, "texto": "With trumpets and sound of cornet make a joyful noise before the Lord, the King."}, {"numero": 7, "texto": "Let the sea roar, and the fulness thereof; the world, and they that dwell therein."}, {"numero": 8, "texto": "Let the floods clap their hands: let the hills be joyful together"}, {"numero": 9, "texto": "Before the Lord; for he cometh to judge the earth: with righteousness shall he judge the world, and the people with equity."}]'::jsonb, 'King James Version'),
  ('Sl', 98, 'fr', '[{"numero": 1, "texto": "Psaume. Chantez à l''''Eternel un cantique nouveau! Car il a fait des prodiges. Sa droite et son bras saint lui sont venus en aide."}, {"numero": 2, "texto": "L''''Eternel a manifesté son salut, Il a révélé sa justice aux yeux des nations."}, {"numero": 3, "texto": "Il s''''est souvenu de sa bonté et de sa fidélité envers la maison d''''Israël, Toutes les extrémités de la terre ont vu le salut de notre Dieu."}, {"numero": 4, "texto": "Poussez vers l''''Eternel des cris de joie, Vous tous, habitants de la terre! Faites éclater votre allégresse, et chantez!"}, {"numero": 5, "texto": "Chantez à l''''Eternel avec la harpe; Avec la harpe chantez des cantiques!"}, {"numero": 6, "texto": "Avec les trompettes et au son du cor, Poussez des cris de joie devant le roi, l''''Eternel!"}, {"numero": 7, "texto": "Que la mer retentisse avec tout ce qu''''elle contient, Que le monde et ceux qui l''''habitent éclatent d''''allégresse,"}, {"numero": 8, "texto": "Que les fleuves battent des mains, Que toutes les montagnes poussent des cris de joie,"}, {"numero": 9, "texto": "Devant l''''Eternel! Car il vient pour juger la terre; Il jugera le monde avec justice, Et les peuples avec équité."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 98, 'es', '[{"numero": 1, "texto": "CANTAD á Jehová canción nueva; porque ha hecho maravillas: su diestra lo ha salvado, y su santo brazo."}, {"numero": 2, "texto": "Jehová ha hecho notoria su salud: en ojos de las gentes ha descubierto su justicia."}, {"numero": 3, "texto": "Hase acordado de su misericordia y de su verdad para con la casa de Israel: todos los términos de la tierra han visto la salud de nuestro Dios."}, {"numero": 4, "texto": "Cantad alegres á Jehová, toda la tierra; levantad la voz, y aplaudid, y salmead."}, {"numero": 5, "texto": "Salmead á Jehová con arpa; con arpa y voz de cántico."}, {"numero": 6, "texto": "Aclamad con trompetas y sonidos de bocina delante del rey Jehová."}, {"numero": 7, "texto": "Brame la mar y su plenitud; el mundo y los que en él habitan;"}, {"numero": 8, "texto": "Los ríos batan las manos; los montes todos hagan regocijo,"}, {"numero": 9, "texto": "Delante de Jehová; porque vino á juzgar la tierra: juzgará al mundo con justicia, y á los pueblos con rectitud."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 103, 'pt', '[{"numero": 1, "texto": "Salmo de Davi: Louva ao SENHOR, ó minha alma; e que todo o meu interior [louve] ao seu santo nome."}, {"numero": 2, "texto": "Louva ao SENHOR, ó minha alma; e não te esqueças de nenhum dos benefícios dele;"}, {"numero": 3, "texto": "Que perdoa todas as tuas perversidades, e te sara de todas as tuas enfermidades."}, {"numero": 4, "texto": "Que resgata tua vida da perdição; que te coroa com bondade e misericórdia."}, {"numero": 5, "texto": "Que farta tua boca de coisas boas, e tua juventude é renovada como a águia."}, {"numero": 6, "texto": "O SENHOR faz justiça e juízos a todos os oprimidos."}, {"numero": 7, "texto": "Ele fez Moisés conhecer seus caminhos, e os filhos de Israel [conhecerem] as obras dele."}, {"numero": 8, "texto": "Misericordioso e piedoso é o SENHOR, que demora para se irar, e é grande em bondade."}, {"numero": 9, "texto": "Ele não reclamará perpetuamente, nem manterá [sua ira] para sempre."}, {"numero": 10, "texto": "Ele não nos trata conforme nossos pecados, nem nos retribui conforme nossas perversidades."}, {"numero": 11, "texto": "Porque, assim como os céus estão bem mais elevados que a terra, assim também prevalece a bondade dele sobre aqueles que o temem."}, {"numero": 12, "texto": "Assim como o oriente está longe do ocidente, assim também ele tira para longe de nós nossas transgressões."}, {"numero": 13, "texto": "Assim como um pai se compadece dos filhos, assim também o SENHOR se compadece daqueles que o temem."}, {"numero": 14, "texto": "Porque ele sabe como fomos formados; ele se lembra de que somos pó."}, {"numero": 15, "texto": "Os dias do homem são como a erva, como a flor do campo, assim ele floresce."}, {"numero": 16, "texto": "Mas quando o vento passa por ele, logo perece; e seu lugar deixa de ser conhecido."}, {"numero": 17, "texto": "Porém a bondade do SENHOR [continua] de eternidade em eternidade sobre os que o temem; e a justiça dele [está] sobre os filhos de [seus] filhos."}, {"numero": 18, "texto": "Sobre os que guardam o seu pacto dele, e sobre os que se lembram de dos mandamentos dele, para os praticarem."}, {"numero": 19, "texto": "O SENHOR firmou o seu trono nos céus, e seu reino domina sobre tudo."}, {"numero": 20, "texto": "Bendizei ao SENHOR, ó anjos dele; vós, fortes valentes, que guardais sua palavra, ao ouvirem a voz de sua palavra."}, {"numero": 21, "texto": "Bendizei ao SENHOR todos os seus exércitos; vós que servis a ele, que fazeis o que lhe agrada."}, {"numero": 22, "texto": "Bendizei ao SENHOR todas as suas obras, em todos os lugares de seu domínio; louva, minha alma, ao SENHOR!"}]'::jsonb, 'Almeida Livre'),
  ('Sl', 103, 'en', '[{"numero": 1, "texto": "Bless the Lord, O my soul: and all that is within me, bless his holy name."}, {"numero": 2, "texto": "Bless the Lord, O my soul, and forget not all his benefits:"}, {"numero": 3, "texto": "Who forgiveth all thine iniquities; who healeth all thy diseases;"}, {"numero": 4, "texto": "Who redeemeth thy life from destruction; who crowneth thee with lovingkindness and tender mercies;"}, {"numero": 5, "texto": "Who satisfieth thy mouth with good things; so that thy youth is renewed like the eagle''s."}, {"numero": 6, "texto": "The Lord executeth righteousness and judgment for all that are oppressed."}, {"numero": 7, "texto": "He made known his ways unto Moses, his acts unto the children of Israel."}, {"numero": 8, "texto": "The Lord is merciful and gracious, slow to anger, and plenteous in mercy."}, {"numero": 9, "texto": "He will not always chide: neither will he keep his anger for ever."}, {"numero": 10, "texto": "He hath not dealt with us after our sins; nor rewarded us according to our iniquities."}, {"numero": 11, "texto": "For as the heaven is high above the earth, so great is his mercy toward them that fear him."}, {"numero": 12, "texto": "As far as the east is from the west, so far hath he removed our transgressions from us."}, {"numero": 13, "texto": "Like as a father pitieth his children, so the Lord pitieth them that fear him."}, {"numero": 14, "texto": "For he knoweth our frame; he remembereth that we are dust."}, {"numero": 15, "texto": "As for man, his days are as grass: as a flower of the field, so he flourisheth."}, {"numero": 16, "texto": "For the wind passeth over it, and it is gone; and the place thereof shall know it no more."}, {"numero": 17, "texto": "But the mercy of the Lord is from everlasting to everlasting upon them that fear him, and his righteousness unto children''s children;"}, {"numero": 18, "texto": "To such as keep his covenant, and to those that remember his commandments to do them."}, {"numero": 19, "texto": "The Lord hath prepared his throne in the heavens; and his kingdom ruleth over all."}, {"numero": 20, "texto": "Bless the Lord, ye his angels, that excel in strength, that do his commandments, hearkening unto the voice of his word."}, {"numero": 21, "texto": "Bless ye the Lord, all ye his hosts; ye ministers of his, that do his pleasure."}, {"numero": 22, "texto": "Bless the Lord, all his works in all places of his dominion: bless the Lord, O my soul."}]'::jsonb, 'King James Version'),
  ('Sl', 103, 'fr', '[{"numero": 1, "texto": "De David. Mon âme, bénis l''''Eternel! Que tout ce qui est en moi bénisse son saint nom!"}, {"numero": 2, "texto": "Mon âme, bénis l''''Eternel, Et n''''oublie aucun de ses bienfaits!"}, {"numero": 3, "texto": "C''''est lui qui pardonne toutes tes iniquités, Qui guérit toutes tes maladies;"}, {"numero": 4, "texto": "C''''est lui qui délivre ta vie de la fosse, Qui te couronne de bonté et de miséricorde;"}, {"numero": 5, "texto": "C''''est lui qui rassasie de biens ta vieillesse, Qui te fait rajeunir comme l''''aigle."}, {"numero": 6, "texto": "L''''Eternel fait justice, Il fait droit à tous les opprimés."}, {"numero": 7, "texto": "Il a manifesté ses voies à Moïse, Ses oeuvres aux enfants d''''Israël."}, {"numero": 8, "texto": "L''''Eternel est miséricordieux et compatissant, Lent à la colère et riche en bonté;"}, {"numero": 9, "texto": "Il ne conteste pas sans cesse, Il ne garde pas sa colère à toujours;"}, {"numero": 10, "texto": "Il ne nous traite pas selon nos péchés, Il ne nous punit pas selon nos iniquités."}, {"numero": 11, "texto": "Mais autant les cieux sont élevés au-dessus de la terre, Autant sa bonté est grande pour ceux qui le craignent;"}, {"numero": 12, "texto": "Autant l''''orient est éloigné de l''''occident, Autant il éloigne de nous nos transgressions."}, {"numero": 13, "texto": "Comme un père a compassion de ses enfants, L''''Eternel a compassion de ceux qui le craignent."}, {"numero": 14, "texto": "Car il sait de quoi nous sommes formés, Il se souvient que nous sommes poussière."}, {"numero": 15, "texto": "L''''homme! ses jours sont comme l''''herbe, Il fleurit comme la fleur des champs."}, {"numero": 16, "texto": "Lorsqu''''un vent passe sur elle, elle n''''est plus, Et le lieu qu''''elle occupait ne la reconnaît plus."}, {"numero": 17, "texto": "Mais la bonté de l''''Eternel dure à jamais pour ceux qui le craignent, Et sa miséricorde pour les enfants de leurs enfants,"}, {"numero": 18, "texto": "Pour ceux qui gardent son alliance, Et se souviennent de ses commandements afin de les accomplir."}, {"numero": 19, "texto": "L''''Eternel a établi son trône dans les cieux, Et son règne domine sur toutes choses."}, {"numero": 20, "texto": "Bénissez l''''Eternel, vous ses anges, Qui êtes puissants en force, et qui exécutez ses ordres, En obéissant à la voix de sa parole!"}, {"numero": 21, "texto": "Bénissez l''''Eternel, vous toutes ses armées, Qui êtes ses serviteurs, et qui faites sa volonté!"}, {"numero": 22, "texto": "Bénissez l''''Eternel, vous toutes ses oeuvres, Dans tous les lieux de sa domination! Mon âme, bénis l''''Eternel!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 103, 'es', '[{"numero": 1, "texto": "BENDICE, alma mía, á Jehová; y bendigan todas mis entrañas su santo nombre."}, {"numero": 2, "texto": "Bendice, alma mía á Jehová, y no olvides ninguno de sus beneficios."}, {"numero": 3, "texto": "El es quien perdona todas tus iniquidades, el que sana todas tus dolencias;"}, {"numero": 4, "texto": "El que rescata del hoyo tu vida, el que te corona de favores y misericordias;"}, {"numero": 5, "texto": "El que sacia de bien tu boca de modo que te rejuvenezcas como el águila."}, {"numero": 6, "texto": "Jehová el que hace justicia y derecho á todos los que padecen violencia."}, {"numero": 7, "texto": "Sus caminos notificó á Moisés, y á los hijos de Israel sus obras."}, {"numero": 8, "texto": "Misericordioso y clemente es Jehová; lento para la ira, y grande en misericordia."}, {"numero": 9, "texto": "No contenderá para siempre, ni para siempre guardará el enojo."}, {"numero": 10, "texto": "No ha hecho con nosotros conforme á nuestras iniquidades; ni nos ha pagado conforme á nuestros pecados."}, {"numero": 11, "texto": "Porque como la altura de los cielos sobre la tierra, engrandeció su misericordia sobre los que le temen."}, {"numero": 12, "texto": "Cuanto está lejos el oriente del occidente, hizo alejar de nosotros nuestras rebeliones."}, {"numero": 13, "texto": "Como el padre se compadece de los hijos, se compadece Jehová de los que le temen."}, {"numero": 14, "texto": "Porque él conoce nuestra condición; acuérdase que somos polvo."}, {"numero": 15, "texto": "El hombre, como la hierba son sus días: florece como la flor del campo."}, {"numero": 16, "texto": "Que pasó el viento por ella, y pereció: y su lugar no la conoce más."}, {"numero": 17, "texto": "Mas la misericordia de Jehová desde el siglo y hasta el siglo sobre los que le temen, y su justicia sobre los hijos de los hijos;"}, {"numero": 18, "texto": "Sobre los que guardan su pacto, y los que se acuerdan de sus mandamientos para ponerlos por obra."}, {"numero": 19, "texto": "Jehová afirmó en los cielos su trono; y su reino domina sobre todos."}, {"numero": 20, "texto": "Bendecid á Jehová, vosotros sus ángeles, poderosos en fortaleza, que ejecutáis su palabra, obedeciendo á la voz de su precepto."}, {"numero": 21, "texto": "Bendecid á Jehová, vosotros todos sus ejércitos, ministros suyos, que hacéis su voluntad."}, {"numero": 22, "texto": "Bendecid á Jehová, vosotras todas sus obras, en todos los lugares de su señorío. Bendice, alma mía, á Jehová."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 117, 'pt', '[{"numero": 1, "texto": "Louvai ao SENHOR, todas as nações; celebrai a ele, todos os povos."}, {"numero": 2, "texto": "Porque sua bondade prevaleceu sobre nós, e a fidelidade do SENHOR [dura] para sempre. Aleluia!"}]'::jsonb, 'Almeida Livre'),
  ('Sl', 117, 'en', '[{"numero": 1, "texto": "O praise the Lord, all ye nations: praise him, all ye people."}, {"numero": 2, "texto": "For his merciful kindness is great toward us: and the truth of the Lord endureth for ever. Praise ye the Lord."}]'::jsonb, 'King James Version'),
  ('Sl', 117, 'fr', '[{"numero": 1, "texto": "Louez l''''Eternel, vous toutes les nations, Célébrez-le, vous tous les peuples!"}, {"numero": 2, "texto": "Car sa bonté pour nous est grande, Et sa fidélité dure à toujours. Louez l''''Eternel!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 117, 'es', '[{"numero": 1, "texto": "ALABAD á Jehová, naciones todas; pueblos todos, alabadle."}, {"numero": 2, "texto": "Porque ha engrandecido sobre nosotros su misericordia; y la verdad de Jehová es para siempre. Aleluya."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 119, 'pt', '[{"numero": 1, "texto": "[Álefe] :Bem-aventurados são os puros em [seus] caminhos, os que andam na lei do SENHOR."}, {"numero": 2, "texto": "Bem-aventurados são os que guardam os testemunhos dele, [e] o buscam com todo o coração;"}, {"numero": 3, "texto": "E não praticam perversidade, [mas] andam nos caminhos dele."}, {"numero": 4, "texto": "Tu mandaste que teus mandamentos fossem cuidadosamente obedecidos."}, {"numero": 5, "texto": "Ah! Como gostaria que meus caminhos fossem dirigidos a guardar teus estatutos!"}, {"numero": 6, "texto": "Então não me envergonharia, quando eu observasse todos os teus mandamentos."}, {"numero": 7, "texto": "Louvarei a ti com um coração correto, enquanto aprendo os juízos de tua justiça."}, {"numero": 8, "texto": "Eu guardarei teus estatutos; não me abandones por completo."}, {"numero": 9, "texto": "[Bete] : Com que um rapaz purificará o seu caminho? Sendo obediente conforme a tua palavra."}, {"numero": 10, "texto": "Eu te busco como todo o meu coração; não me deixes desviar de teus mandamentos."}, {"numero": 11, "texto": "Guardei a tua palavra em meu coração, para eu não pecar contra ti."}, {"numero": 12, "texto": "Bendito [és] tu, SENHOR; ensina-me os teus estatutos."}, {"numero": 13, "texto": "Com meus lábios contei todos os juízos de tua boca."}, {"numero": 14, "texto": "Eu me alegro mais com o caminho de teus estatutos, do que com todas as riquezas."}, {"numero": 15, "texto": "Meditarei em teus mandamentos, e darei atenção aos teus caminhos."}, {"numero": 16, "texto": "Terei prazer em teus estatutos; não me esquecerei de tua palavra."}, {"numero": 17, "texto": "[Guímel] :Trata bem o teu servo, [para] que eu viva, e obedeça tua palavra."}, {"numero": 18, "texto": "Abre meus olhos, para que eu veja as maravilhas de tua lei."}, {"numero": 19, "texto": "Eu sou peregrino na terra, não escondas de mim os teus mandamentos."}, {"numero": 20, "texto": "Minha alma está despedaçada de tanto desejar os teus juízos em todo tempo."}, {"numero": 21, "texto": "Tu repreendes aos malditos arrogantes, que se desviam de teus mandamentos."}, {"numero": 22, "texto": "Tira-me de minha humilhação e desprezo, pois eu guardei teus testemunhos."}, {"numero": 23, "texto": "Até mesmo os príncipes se sentaram, e falaram contra mim; porém o teu servo estava meditando em teus estatutos."}, {"numero": 24, "texto": "Pois teus testemunhos são meus prazeres [e] meus conselheiros."}, {"numero": 25, "texto": "[Dálete] :Minha alma está grudada ao pó; vivifica-me conforme tua palavra."}, {"numero": 26, "texto": "Eu [te] contei os meus caminhos, e tu me respondeste; ensina-me conforme teus estatutos."}, {"numero": 27, "texto": "Faze-me entender o caminho de teus preceitos, para eu falar de tuas maravilhas."}, {"numero": 28, "texto": "Minha alma se derrama de tristeza; levanta-me conforme tua palavra."}, {"numero": 29, "texto": "Desvia de mim o caminho de falsidade; e sê piedoso dando-me tua lei."}, {"numero": 30, "texto": "Eu escolhi o caminho da fidelidade; e pus [diante de mim] os teus juízos."}, {"numero": 31, "texto": "Estou apegado a teus testemunhos; ó SENHOR, não me envergonhes."}, {"numero": 32, "texto": "Correrei pelo caminho de teus mandamentos, porque tu alargaste o meu coração."}, {"numero": 33, "texto": "[Hê] :Ensina-me, SENHOR, o caminho de teus estatutos, e eu o guardarei até o fim."}, {"numero": 34, "texto": "Dá-me entendimento, e eu guardarei a tua lei, e a obedecerei de todo [o meu] coração."}, {"numero": 35, "texto": "Faze-me andar na trilha de teus mandamentos, porque nela tenho prazer."}, {"numero": 36, "texto": "Inclina meu coração a teus testemunhos, e não à ganância."}, {"numero": 37, "texto": "Desvia meus olhos para que não olhem para coisas inúteis; vivifica-me pelo teu caminho."}, {"numero": 38, "texto": "Confirma tua promessa a teu servo, que tem temor a ti."}, {"numero": 39, "texto": "Desvia de mim a humilhação que eu tenho medo, pois teus juízos são bons."}, {"numero": 40, "texto": "Eis que amo os teus mandamentos; vivifica-me por tua justiça."}, {"numero": 41, "texto": "[Vau] :E venham sobre mim tuas bondades, SENHOR; [e também] a tua salvação, segundo tua promessa."}, {"numero": 42, "texto": "Para que eu tenha resposta ao que me insulta; pois eu confio em tua palavra."}, {"numero": 43, "texto": "E nunca tires de minha boca a palavra da verdade, pois eu espero em teus juízos."}, {"numero": 44, "texto": "Assim obedecerei a tua lei continuamente, para todo o sempre."}, {"numero": 45, "texto": "E andarei [livremente] por longas distâncias, pois busquei teus preceitos."}, {"numero": 46, "texto": "Também falarei de teus testemunhos perante reis, e não me envergonharei."}, {"numero": 47, "texto": "E terei prazer em teus mandamentos, que eu amo."}, {"numero": 48, "texto": "E levantarei as minhas mãos a teus mandamentos, que eu amo; e meditarei em teus estatutos."}, {"numero": 49, "texto": "[Záin] :Lembra-te da palavra [dada] a teu servo, à qual mantenho esperança."}, {"numero": 50, "texto": "Isto é meu consolo na minha aflição, porque tua promessa me vivifica."}, {"numero": 51, "texto": "Os arrogantes têm zombado de mim demasiadamente; [porém] não me desviei de tua lei."}, {"numero": 52, "texto": "Eu me lembrei de teus juízos muito antigos, SENHOR; e [assim] me consolei."}, {"numero": 53, "texto": "Eu me enchi de ira por causa dos perversos, que abandonam tua lei."}, {"numero": 54, "texto": "Teus estatutos foram meus cânticos no lugar de minhas peregrinações."}, {"numero": 55, "texto": "De noite tenho me lembrado de teu nome, SENHOR; e tenho guardado tua lei."}, {"numero": 56, "texto": "Isto eu tenho feito, porque guardo teus mandamentos."}, {"numero": 57, "texto": "[Hete] :O SENHOR é minha porção; eu disse que guardaria tuas palavras."}, {"numero": 58, "texto": "Busquei a tua face com todo o [meu] coração; tem piedade de mim segundo tua palavra."}, {"numero": 59, "texto": "Eu dei atenção a meus caminhos, e dirigi meus pés a teus testemunhos."}, {"numero": 60, "texto": "Eu me apressei, e não demorei a guardar os teus mandamentos."}, {"numero": 61, "texto": "Bandos de perversos me roubaram; [porém] não me esqueci de tua lei."}, {"numero": 62, "texto": "No meio da noite eu me levanto para te louvar, por causa dos juízos de tua justiça."}, {"numero": 63, "texto": "Sou companheiro de todos os que te temem, e dos que guardam os teus mandamentos."}, {"numero": 64, "texto": "A terra está cheia de tua bondade, SENHOR; ensina-me os teus estatutos."}, {"numero": 65, "texto": "[Tete] :Tu fizeste bem a teu servo, SENHOR, conforme tua palavra."}, {"numero": 66, "texto": "Ensina-me bom senso e conhecimento, pois tenho crido em teus mandamentos."}, {"numero": 67, "texto": "Antes de ter sido afligido, eu andava errado; mas agora guardo tua palavra."}, {"numero": 68, "texto": "Tu és bom, e fazes o bem; ensina-me os teus estatutos."}, {"numero": 69, "texto": "Os arrogantes forjaram mentiras contra mim; [mas] eu com todo o [meu] coração guardo os teus mandamentos."}, {"numero": 70, "texto": "O coração deles se incha como gordura; [mas] eu tenho prazer em tua lei."}, {"numero": 71, "texto": "Foi bom pra mim ter sido afligido, para assim eu aprender os teus estatutos."}, {"numero": 72, "texto": "Melhor para mim é a lei de tua boca, do que milhares de [peças] de ouro ou prata."}, {"numero": 73, "texto": "[Iode] :Tuas mãos me fizeram e me formaram; faze-me ter entendimento, para que eu aprenda teus mandamentos."}, {"numero": 74, "texto": "Os que te temem olham para mim e se alegram, porque eu mantive esperança em tua palavra."}, {"numero": 75, "texto": "Eu sei, SENHOR, que teus juízos são justos; e que tu me afligiste [por] tua fidelidade."}, {"numero": 76, "texto": "Seja agora tua bondade para me consolar, segundo a promessa [que fizeste] a teu servo."}, {"numero": 77, "texto": "Venham tuas misericórdias sobre mim, para que eu viva; pois tua lei é o meu prazer."}, {"numero": 78, "texto": "Sejam envergonhados os arrogantes, porque eles me prejudicaram com mentiras; [porém] eu medito em teus mandamentos."}, {"numero": 79, "texto": "Virem-se a mim os que te temem e conhecem os teus testemunhos."}, {"numero": 80, "texto": "Seja meu coração correto em teus estatutos, para eu não ser envergonhado."}, {"numero": 81, "texto": "[Cafe] :Minha alma desfalece por tua salvação; em tua palavra mantenho esperança."}, {"numero": 82, "texto": "Meus olhos desfaleceram por tua promessa, enquanto eu dizia: Quando tu me consolarás?"}, {"numero": 83, "texto": "Porque fiquei como um odre na fumaça, [porém] não me esqueci teus testemunhos."}, {"numero": 84, "texto": "Quantos serão os dias de teu servo? Quando farás julgamento aos meus perseguidores?"}, {"numero": 85, "texto": "Os arrogantes me cavaram covas, aqueles que não são conforme a tua lei."}, {"numero": 86, "texto": "Todos os teus mandamentos são verdade; com mentiras me perseguem; ajuda-me."}, {"numero": 87, "texto": "Estou quase que destruído por completo sobre a terra; porém eu não deixei teus mandamentos."}, {"numero": 88, "texto": "Vivifica-me conforme tua bondade, então guardarei o testemunho de tua boca."}, {"numero": 89, "texto": "[Lâmede] :Para sempre, SENHOR, tua palavra permanece nos céus."}, {"numero": 90, "texto": "Tua fidelidade [dura] de geração em geração; tu firmaste a terra, e [assim] ela permanece."}, {"numero": 91, "texto": "Elas continuam por tuas ordens até hoje, porque todos são teus servos."}, {"numero": 92, "texto": "Se a tua lei não fosse meu prazer, eu já teria perecido em minha aflição."}, {"numero": 93, "texto": "Nunca esquecerei de teus mandamentos, porque tu me vivificaste por eles."}, {"numero": 94, "texto": "Eu sou teu, salva-me, porque busquei teus preceitos."}, {"numero": 95, "texto": "Os perversos me esperaram, para me destruírem; [porém] eu dou atenção a teus testemunhos."}, {"numero": 96, "texto": "A toda perfeição eu vi fim; [mas] teu mandamento é extremamente grande."}, {"numero": 97, "texto": "[Mem] :Ah, como eu amo a tua lei! O dia todo eu medito nela."}, {"numero": 98, "texto": "Ela me faz mais sábio do que meus inimigos [por meio de] teus mandamentos, porque ela está sempre comigo."}, {"numero": 99, "texto": "Sou mais inteligente que todos os meus instrutores, porque medito em teus testemunhos."}, {"numero": 100, "texto": "Sou mais prudente que os anciãos, porque guardei teus mandamentos."}, {"numero": 101, "texto": "Afastei meus pés de todo mau caminho, para guardar tua palavra."}, {"numero": 102, "texto": "Não me desviei de teus juízos, porque tu me ensinaste."}, {"numero": 103, "texto": "Como são doces tuas palavras ao meu paladar! Mais que o mel em minha boca."}, {"numero": 104, "texto": "Obtenho conhecimento por meio de teus preceitos; por isso odeio todo caminho de mentira."}, {"numero": 105, "texto": "[Nun] :Tua palavra é lâmpada para meus pés e luz para meu caminho."}, {"numero": 106, "texto": "Eu jurei, e [assim] cumprirei, de guardar os juízos de tua justiça."}, {"numero": 107, "texto": "Eu estou muito aflito, SENHOR; vivifica-me conforme a tua palavra."}, {"numero": 108, "texto": "Agrada-te das ofertas voluntárias de minha boca, SENHOR; e ensina-me teus juízos."}, {"numero": 109, "texto": "Continuamente arrisco minha alma, porém não me esqueço de tua lei."}, {"numero": 110, "texto": "Os perversos me armaram um laço de armadilha, mas não me desviei de teus mandamentos."}, {"numero": 111, "texto": "Tomei teus testemunhos por herança para sempre, pois eles são a alegria de meu coração."}, {"numero": 112, "texto": "Inclinei meu coração para praticar os teus testemunhos para todo o sempre."}, {"numero": 113, "texto": "[Sâmeque] :Odeio os inconstantes, mas amo a tua lei."}, {"numero": 114, "texto": "Tu és meu refúgio e meu escudo; eu espero em tua palavra."}, {"numero": 115, "texto": "Afastai-vos de mim, malfeitores, para que eu guarde os mandamentos de meu Deus."}, {"numero": 116, "texto": "Sustenta-me conforme a tua promessa, para que eu viva; e não me faças ser humilhado em minha esperança."}, {"numero": 117, "texto": "Segura-me, e estarei protegido; então continuamente pensarei em teus estatutos."}, {"numero": 118, "texto": "Tu atropelas a todos que se desviam de teus estatutos; pois o engano deles é mentira."}, {"numero": 119, "texto": "Tu tiras a todos os perversos da terra como [se fossem] lixo; por isso eu amo teus testemunhos."}, {"numero": 120, "texto": "Meu corpo se arrepia de medo de ti; e temo os teus juízos."}, {"numero": 121, "texto": "[Áin] :Eu fiz juízo e justiça; não me abandones com os meus opressores."}, {"numero": 122, "texto": "Sê tu a garantia do bem de teu servo; não me deixes ser oprimido pelos arrogantes."}, {"numero": 123, "texto": "Meus olhos desfaleceram [de esperar] por tua salvação, e pela palavra de tua justiça."}, {"numero": 124, "texto": "Age para com teu servo segundo tua bondade, e ensina-me teus estatutos."}, {"numero": 125, "texto": "Eu sou teu servo. Dá-me entendimento; então conhecerei teus testemunhos."}, {"numero": 126, "texto": "É tempo do SENHOR agir, porque estão violando tua lei."}, {"numero": 127, "texto": "Por isso eu amo teus mandamentos mais que o ouro, o mais fino ouro."}, {"numero": 128, "texto": "Por isso considero corretos todos os [teus] mandamentos quanto a tudo, e odeio todo caminho de falsidade."}, {"numero": 129, "texto": "[Pê] :Maravilhosos são teus testemunhos, por isso minha alma os guarda."}, {"numero": 130, "texto": "A entrada de tuas palavras dá luz, dando entendimento aos simples."}, {"numero": 131, "texto": "Abri minha boca, e respirei; porque desejei teus mandamentos."}, {"numero": 132, "texto": "Olha-me, e tem piedade de mim; conforme [teu] costume para com os que amam o teu nome."}, {"numero": 133, "texto": "Firma meus passos em tua palavra, e que nenhuma perversidade me domine."}, {"numero": 134, "texto": "Resgata-me da opressão dos homens; então guardarei teus mandamentos."}, {"numero": 135, "texto": "Brilha teu rosto sobre teu servo, e ensina-me teus estatutos."}, {"numero": 136, "texto": "Ribeiros d''água descem de meus olhos, porque eles não guardam tua lei."}, {"numero": 137, "texto": "[Tsadê] :Tu és justo, SENHOR; e corretos são teus juízos."}, {"numero": 138, "texto": "Tu ensinaste teus testemunhos justos e muito fiéis."}, {"numero": 139, "texto": "Meu zelo me consumiu, porque meus adversários se esqueceram de tuas palavras."}, {"numero": 140, "texto": "Refinada é a tua palavra, e teu servo a ama."}, {"numero": 141, "texto": "Eu sou pequeno e desprezado; [porém] não me esqueço de teus mandamentos."}, {"numero": 142, "texto": "Tua justiça é justa para sempre, e tua lei é verdade."}, {"numero": 143, "texto": "Aperto e angústia me encontraram; [ainda assim] teus mandamentos são meus prazeres."}, {"numero": 144, "texto": "A justiça de teus testemunhos [dura] para sempre; dá-me entendimento, e então viverei."}, {"numero": 145, "texto": "[Cofe] :Clamei com todo o [meu] coração; responde-me, SENHOR; guardarei teus estatutos."}, {"numero": 146, "texto": "Clamei a ti; salva-me, e então guardarei os teus testemunhos."}, {"numero": 147, "texto": "Eu me antecedi ao amanhecer, e gritei; [e] mantive esperança em tua palavra."}, {"numero": 148, "texto": "Meus olhos antecederam as vigílias da noite, para meditar em tua palavra."}, {"numero": 149, "texto": "Ouve minha voz, segundo tua bondade, SENHOR; vivifica-me conforme teu juízo."}, {"numero": 150, "texto": "Aproximam-se [de mim] os que praticam maldade; eles estão longe de tua lei."}, {"numero": 151, "texto": "[Porém] tu, SENHOR, estás perto [de mim] ; e todos os teus mandamentos são verdade."}, {"numero": 152, "texto": "Desde antigamente eu soube de teus testemunhos, que tu os fundaste para sempre."}, {"numero": 153, "texto": "[Rexe] :Olha a minha aflição, e livra-me [dela] ; pois não me esqueci de tua lei."}, {"numero": 154, "texto": "Defende minha causa, e resgata-me; vivifica-me conforme tua palavra."}, {"numero": 155, "texto": "A salvação está longe dos perversos, porque eles não buscam teus estatutos."}, {"numero": 156, "texto": "Muitas são tuas misericórdias, SENHOR; vivifica-me conforme teus juízos."}, {"numero": 157, "texto": "Muitos são meus perseguidores e meus adversários; [porém] eu não me desvio de teus testemunhos."}, {"numero": 158, "texto": "Eu vi aos enganadores e os detestei, porque eles não guardam tua palavra."}, {"numero": 159, "texto": "Vê, SENHOR, que eu amo teus mandamentos; vivifica-me conforme a tua bondade."}, {"numero": 160, "texto": "O princípio de tua palavra é fiel, e o juízo de tua justiça [dura] para sempre."}, {"numero": 161, "texto": "[Xin] :Príncipes me perseguiram sem causa, mas meu coração temeu a tua palavra."}, {"numero": 162, "texto": "Eu me alegro em tua palavra, tal como alguém que encontra um grande tesouro."}, {"numero": 163, "texto": "Odeio e abomino a falsidade; [mas] amo a tua lei."}, {"numero": 164, "texto": "Louvo a ti sete vezes ao dia, por causa dos juízos de tua justiça."}, {"numero": 165, "texto": "Muita paz têm aqueles que amam a tua lei; e para eles não há tropeço."}, {"numero": 166, "texto": "Espero por tua salvação, SENHOR; e pratico teus mandamentos."}, {"numero": 167, "texto": "Minha alma guarda teus testemunhos, e eu os amo muito."}, {"numero": 168, "texto": "Eu guardo teus preceitos e teus testemunhos, porque todos os meus caminhos estão diante de ti."}, {"numero": 169, "texto": "[Tau] :Chegue meu clamor perante teu rosto, SENHOR; dá-me entendimento conforme tua palavra."}, {"numero": 170, "texto": "Venha minha súplica diante de ti; livra-me conforme tua promessa."}, {"numero": 171, "texto": "Meus lábios falarão muitos louvores, pois tu me ensinas teus estatutos."}, {"numero": 172, "texto": "Minha língua falará de tua palavra, porque todos os teus mandamentos são justiça."}, {"numero": 173, "texto": "Que tua mão me socorra, porque escolhi [seguir] teus preceitos."}, {"numero": 174, "texto": "Desejo tua salvação, SENHOR; e tua lei é o meu prazer."}, {"numero": 175, "texto": "Que minha alma viva e louve a ti; e que teus juízos me socorram."}, {"numero": 176, "texto": "Tenho andado sem rumo, como uma ovelha perdida; busca a teu servo, pois eu não me esqueci de teus mandamentos."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 119, 'en', '[{"numero": 1, "texto": "Blessed are the undefiled in the way, who walk in the law of the Lord."}, {"numero": 2, "texto": "Blessed are they that keep his testimonies, and that seek him with the whole heart."}, {"numero": 3, "texto": "They also do no iniquity: they walk in his ways."}, {"numero": 4, "texto": "Thou hast commanded us to keep thy precepts diligently."}, {"numero": 5, "texto": "O that my ways were directed to keep thy statutes!"}, {"numero": 6, "texto": "Then shall I not be ashamed, when I have respect unto all thy commandments."}, {"numero": 7, "texto": "I will praise thee with uprightness of heart, when I shall have learned thy righteous judgments."}, {"numero": 8, "texto": "I will keep thy statutes: O forsake me not utterly."}, {"numero": 9, "texto": "Wherewithal shall a young man cleanse his way? by taking heed thereto according to thy word."}, {"numero": 10, "texto": "With my whole heart have I sought thee: O let me not wander from thy commandments."}, {"numero": 11, "texto": "Thy word have I hid in mine heart, that I might not sin against thee."}, {"numero": 12, "texto": "Blessed art thou, O Lord: teach me thy statutes."}, {"numero": 13, "texto": "With my lips have I declared all the judgments of thy mouth."}, {"numero": 14, "texto": "I have rejoiced in the way of thy testimonies, as much as in all riches."}, {"numero": 15, "texto": "I will meditate in thy precepts, and have respect unto thy ways."}, {"numero": 16, "texto": "I will delight myself in thy statutes: I will not forget thy word."}, {"numero": 17, "texto": "Deal bountifully with thy servant, that I may live, and keep thy word."}, {"numero": 18, "texto": "Open thou mine eyes, that I may behold wondrous things out of thy law."}, {"numero": 19, "texto": "I am a stranger in the earth: hide not thy commandments from me."}, {"numero": 20, "texto": "My soul breaketh for the longing that it hath unto thy judgments at all times."}, {"numero": 21, "texto": "Thou hast rebuked the proud that are cursed, which do err from thy commandments."}, {"numero": 22, "texto": "Remove from me reproach and contempt; for I have kept thy testimonies."}, {"numero": 23, "texto": "Princes also did sit and speak against me: but thy servant did meditate in thy statutes."}, {"numero": 24, "texto": "Thy testimonies also are my delight and my counselors."}, {"numero": 25, "texto": "My soul cleaveth unto the dust: quicken thou me according to thy word."}, {"numero": 26, "texto": "I have declared my ways, and thou heardest me: teach me thy statutes."}, {"numero": 27, "texto": "Make me to understand the way of thy precepts: so shall I talk of thy wondrous works."}, {"numero": 28, "texto": "My soul melteth for heaviness: strengthen thou me according unto thy word."}, {"numero": 29, "texto": "Remove from me the way of lying: and grant me thy law graciously."}, {"numero": 30, "texto": "I have chosen the way of truth: thy judgments have I laid before me."}, {"numero": 31, "texto": "I have stuck unto thy testimonies: O Lord, put me not to shame."}, {"numero": 32, "texto": "I will run the way of thy commandments, when thou shalt enlarge my heart."}, {"numero": 33, "texto": "Teach me, O Lord, the way of thy statutes; and I shall keep it unto the end."}, {"numero": 34, "texto": "Give me understanding, and I shall keep thy law; yea, I shall observe it with my whole heart."}, {"numero": 35, "texto": "Make me to go in the path of thy commandments; for therein do I delight."}, {"numero": 36, "texto": "Incline my heart unto thy testimonies, and not to covetousness."}, {"numero": 37, "texto": "Turn away mine eyes from beholding vanity; and quicken thou me in thy way."}, {"numero": 38, "texto": "Stablish thy word unto thy servant, who is devoted to thy fear."}, {"numero": 39, "texto": "Turn away my reproach which I fear: for thy judgments are good."}, {"numero": 40, "texto": "Behold, I have longed after thy precepts: quicken me in thy righteousness."}, {"numero": 41, "texto": "Let thy mercies come also unto me, O Lord, even thy salvation, according to thy word."}, {"numero": 42, "texto": "So shall I have wherewith to answer him that reproacheth me: for I trust in thy word."}, {"numero": 43, "texto": "And take not the word of truth utterly out of my mouth; for I have hoped in thy judgments."}, {"numero": 44, "texto": "So shall I keep thy law continually for ever and ever."}, {"numero": 45, "texto": "And I will walk at liberty: for I seek thy precepts."}, {"numero": 46, "texto": "I will speak of thy testimonies also before kings, and will not be ashamed."}, {"numero": 47, "texto": "And I will delight myself in thy commandments, which I have loved."}, {"numero": 48, "texto": "My hands also will I lift up unto thy commandments, which I have loved; and I will meditate in thy statutes."}, {"numero": 49, "texto": "Remember the word unto thy servant, upon which thou hast caused me to hope."}, {"numero": 50, "texto": "This is my comfort in my affliction: for thy word hath quickened me."}, {"numero": 51, "texto": "The proud have had me greatly in derision: yet have I not declined from thy law."}, {"numero": 52, "texto": "I remembered thy judgments of old, O Lord; and have comforted myself."}, {"numero": 53, "texto": "Horror hath taken hold upon me because of the wicked that forsake thy law."}, {"numero": 54, "texto": "Thy statutes have been my songs in the house of my pilgrimage."}, {"numero": 55, "texto": "I have remembered thy name, O Lord, in the night, and have kept thy law."}, {"numero": 56, "texto": "This I had, because I kept thy precepts."}, {"numero": 57, "texto": "Thou art my portion, O Lord: I have said that I would keep thy words."}, {"numero": 58, "texto": "I intreated thy favour with my whole heart: be merciful unto me according to thy word."}, {"numero": 59, "texto": "I thought on my ways, and turned my feet unto thy testimonies."}, {"numero": 60, "texto": "I made haste, and delayed not to keep thy commandments."}, {"numero": 61, "texto": "The bands of the wicked have robbed me: but I have not forgotten thy law."}, {"numero": 62, "texto": "At midnight I will rise to give thanks unto thee because of thy righteous judgments."}, {"numero": 63, "texto": "I am a companion of all them that fear thee, and of them that keep thy precepts."}, {"numero": 64, "texto": "The earth, O Lord, is full of thy mercy: teach me thy statutes."}, {"numero": 65, "texto": "Thou hast dealt well with thy servant, O Lord, according unto thy word."}, {"numero": 66, "texto": "Teach me good judgment and knowledge: for I have believed thy commandments."}, {"numero": 67, "texto": "Before I was afflicted I went astray: but now have I kept thy word."}, {"numero": 68, "texto": "Thou art good, and doest good; teach me thy statutes."}, {"numero": 69, "texto": "The proud have forged a lie against me: but I will keep thy precepts with my whole heart."}, {"numero": 70, "texto": "Their heart is as fat as grease; but I delight in thy law."}, {"numero": 71, "texto": "It is good for me that I have been afflicted; that I might learn thy statutes."}, {"numero": 72, "texto": "The law of thy mouth is better unto me than thousands of gold and silver."}, {"numero": 73, "texto": "Thy hands have made me and fashioned me: give me understanding, that I may learn thy commandments."}, {"numero": 74, "texto": "They that fear thee will be glad when they see me; because I have hoped in thy word."}, {"numero": 75, "texto": "I know, O Lord, that thy judgments are right, and that thou in faithfulness hast afflicted me."}, {"numero": 76, "texto": "Let, I pray thee, thy merciful kindness be for my comfort, according to thy word unto thy servant."}, {"numero": 77, "texto": "Let thy tender mercies come unto me, that I may live: for thy law is my delight."}, {"numero": 78, "texto": "Let the proud be ashamed; for they dealt perversely with me without a cause: but I will meditate in thy precepts."}, {"numero": 79, "texto": "Let those that fear thee turn unto me, and those that have known thy testimonies."}, {"numero": 80, "texto": "Let my heart be sound in thy statutes; that I be not ashamed."}, {"numero": 81, "texto": "My soul fainteth for thy salvation: but I hope in thy word."}, {"numero": 82, "texto": "Mine eyes fail for thy word, saying, When wilt thou comfort me?"}, {"numero": 83, "texto": "For I am become like a bottle in the smoke; yet do I not forget thy statutes."}, {"numero": 84, "texto": "How many are the days of thy servant? when wilt thou execute judgment on them that persecute me?"}, {"numero": 85, "texto": "The proud have digged pits for me, which are not after thy law."}, {"numero": 86, "texto": "All thy commandments are faithful: they persecute me wrongfully; help thou me."}, {"numero": 87, "texto": "They had almost consumed me upon earth; but I forsook not thy precepts."}, {"numero": 88, "texto": "Quicken me after thy lovingkindness; so shall I keep the testimony of thy mouth."}, {"numero": 89, "texto": "For ever, O Lord, thy word is settled in heaven."}, {"numero": 90, "texto": "Thy faithfulness is unto all generations: thou hast established the earth, and it abideth."}, {"numero": 91, "texto": "They continue this day according to thine ordinances: for all are thy servants."}, {"numero": 92, "texto": "Unless thy law had been my delights, I should then have perished in mine affliction."}, {"numero": 93, "texto": "I will never forget thy precepts: for with them thou hast quickened me."}, {"numero": 94, "texto": "I am thine, save me: for I have sought thy precepts."}, {"numero": 95, "texto": "The wicked have waited for me to destroy me: but I will consider thy testimonies."}, {"numero": 96, "texto": "I have seen an end of all perfection: but thy commandment is exceeding broad."}, {"numero": 97, "texto": "O how love I thy law! it is my meditation all the day."}, {"numero": 98, "texto": "Thou through thy commandments hast made me wiser than mine enemies: for they are ever with me."}, {"numero": 99, "texto": "I have more understanding than all my teachers: for thy testimonies are my meditation."}, {"numero": 100, "texto": "I understand more than the ancients, because I keep thy precepts."}, {"numero": 101, "texto": "I have refrained my feet from every evil way, that I might keep thy word."}, {"numero": 102, "texto": "I have not departed from thy judgments: for thou hast taught me."}, {"numero": 103, "texto": "How sweet are thy words unto my taste! yea, sweeter than honey to my mouth!"}, {"numero": 104, "texto": "Through thy precepts I get understanding: therefore I hate every false way."}, {"numero": 105, "texto": "Thy word is a lamp unto my feet, and a light unto my path."}, {"numero": 106, "texto": "I have sworn, and I will perform it, that I will keep thy righteous judgments."}, {"numero": 107, "texto": "I am afflicted very much: quicken me, O Lord, according unto thy word."}, {"numero": 108, "texto": "Accept, I beseech thee, the freewill offerings of my mouth, O Lord, and teach me thy judgments."}, {"numero": 109, "texto": "My soul is continually in my hand: yet do I not forget thy law."}, {"numero": 110, "texto": "The wicked have laid a snare for me: yet I erred not from thy precepts."}, {"numero": 111, "texto": "Thy testimonies have I taken as an heritage for ever: for they are the rejoicing of my heart."}, {"numero": 112, "texto": "I have inclined mine heart to perform thy statutes alway, even unto the end."}, {"numero": 113, "texto": "I hate vain thoughts: but thy law do I love."}, {"numero": 114, "texto": "Thou art my hiding place and my shield: I hope in thy word."}, {"numero": 115, "texto": "Depart from me, ye evildoers: for I will keep the commandments of my God."}, {"numero": 116, "texto": "Uphold me according unto thy word, that I may live: and let me not be ashamed of my hope."}, {"numero": 117, "texto": "Hold thou me up, and I shall be safe: and I will have respect unto thy statutes continually."}, {"numero": 118, "texto": "Thou hast trodden down all them that err from thy statutes: for their deceit is falsehood."}, {"numero": 119, "texto": "Thou puttest away all the wicked of the earth like dross: therefore I love thy testimonies."}, {"numero": 120, "texto": "My flesh trembleth for fear of thee; and I am afraid of thy judgments."}, {"numero": 121, "texto": "I have done judgment and justice: leave me not to mine oppressors."}, {"numero": 122, "texto": "Be surety for thy servant for good: let not the proud oppress me."}, {"numero": 123, "texto": "Mine eyes fail for thy salvation, and for the word of thy righteousness."}, {"numero": 124, "texto": "Deal with thy servant according unto thy mercy, and teach me thy statutes."}, {"numero": 125, "texto": "I am thy servant; give me understanding, that I may know thy testimonies."}, {"numero": 126, "texto": "It is time for thee, Lord, to work: for they have made void thy law."}, {"numero": 127, "texto": "Therefore I love thy commandments above gold; yea, above fine gold."}, {"numero": 128, "texto": "Therefore I esteem all thy precepts concerning all things to be right; and I hate every false way."}, {"numero": 129, "texto": "Thy testimonies are wonderful: therefore doth my soul keep them."}, {"numero": 130, "texto": "The entrance of thy words giveth light; it giveth understanding unto the simple."}, {"numero": 131, "texto": "I opened my mouth, and panted: for I longed for thy commandments."}, {"numero": 132, "texto": "Look thou upon me, and be merciful unto me, as thou usest to do unto those that love thy name."}, {"numero": 133, "texto": "Order my steps in thy word: and let not any iniquity have dominion over me."}, {"numero": 134, "texto": "Deliver me from the oppression of man: so will I keep thy precepts."}, {"numero": 135, "texto": "Make thy face to shine upon thy servant; and teach me thy statutes."}, {"numero": 136, "texto": "Rivers of waters run down mine eyes, because they keep not thy law."}, {"numero": 137, "texto": "Righteous art thou, O Lord, and upright are thy judgments."}, {"numero": 138, "texto": "Thy testimonies that thou hast commanded are righteous and very faithful."}, {"numero": 139, "texto": "My zeal hath consumed me, because mine enemies have forgotten thy words."}, {"numero": 140, "texto": "Thy word is very pure: therefore thy servant loveth it."}, {"numero": 141, "texto": "I am small and despised: yet do not I forget thy precepts."}, {"numero": 142, "texto": "Thy righteousness is an everlasting righteousness, and thy law is the truth."}, {"numero": 143, "texto": "Trouble and anguish have taken hold on me: yet thy commandments are my delights."}, {"numero": 144, "texto": "The righteousness of thy testimonies is everlasting: give me understanding, and I shall live."}, {"numero": 145, "texto": "I cried with my whole heart; hear me, O Lord: I will keep thy statutes."}, {"numero": 146, "texto": "I cried unto thee; save me, and I shall keep thy testimonies."}, {"numero": 147, "texto": "I prevented the dawning of the morning, and cried: I hoped in thy word."}, {"numero": 148, "texto": "Mine eyes prevent the night watches, that I might meditate in thy word."}, {"numero": 149, "texto": "Hear my voice according unto thy lovingkindness: O Lord, quicken me according to thy judgment."}, {"numero": 150, "texto": "They draw nigh that follow after mischief: they are far from thy law."}, {"numero": 151, "texto": "Thou art near, O Lord; and all thy commandments are truth."}, {"numero": 152, "texto": "Concerning thy testimonies, I have known of old that thou hast founded them for ever."}, {"numero": 153, "texto": "Consider mine affliction, and deliver me: for I do not forget thy law."}, {"numero": 154, "texto": "Plead my cause, and deliver me: quicken me according to thy word."}, {"numero": 155, "texto": "Salvation is far from the wicked: for they seek not thy statutes."}, {"numero": 156, "texto": "Great are thy tender mercies, O Lord: quicken me according to thy judgments."}, {"numero": 157, "texto": "Many are my persecutors and mine enemies; yet do I not decline from thy testimonies."}, {"numero": 158, "texto": "I beheld the transgressors, and was grieved; because they kept not thy word."}, {"numero": 159, "texto": "Consider how I love thy precepts: quicken me, O Lord, according to thy lovingkindness."}, {"numero": 160, "texto": "Thy word is true from the beginning: and every one of thy righteous judgments endureth for ever."}, {"numero": 161, "texto": "Princes have persecuted me without a cause: but my heart standeth in awe of thy word."}, {"numero": 162, "texto": "I rejoice at thy word, as one that findeth great spoil."}, {"numero": 163, "texto": "I hate and abhor lying: but thy law do I love."}, {"numero": 164, "texto": "Seven times a day do I praise thee because of thy righteous judgments."}, {"numero": 165, "texto": "Great peace have they which love thy law: and nothing shall offend them."}, {"numero": 166, "texto": "Lord, I have hoped for thy salvation, and done thy commandments."}, {"numero": 167, "texto": "My soul hath kept thy testimonies; and I love them exceedingly."}, {"numero": 168, "texto": "I have kept thy precepts and thy testimonies: for all my ways are before thee."}, {"numero": 169, "texto": "Let my cry come near before thee, O Lord: give me understanding according to thy word."}, {"numero": 170, "texto": "Let my supplication come before thee: deliver me according to thy word."}, {"numero": 171, "texto": "My lips shall utter praise, when thou hast taught me thy statutes."}, {"numero": 172, "texto": "My tongue shall speak of thy word: for all thy commandments are righteousness."}, {"numero": 173, "texto": "Let thine hand help me; for I have chosen thy precepts."}, {"numero": 174, "texto": "I have longed for thy salvation, O Lord; and thy law is my delight."}, {"numero": 175, "texto": "Let my soul live, and it shall praise thee; and let thy judgments help me."}, {"numero": 176, "texto": "I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments."}]'::jsonb, 'King James Version'),
  ('Sl', 119, 'fr', '[{"numero": 1, "texto": "Heureux ceux qui sont intègres dans leur voie, Qui marchent selon la loi de l''''Eternel!"}, {"numero": 2, "texto": "Heureux ceux qui gardent ses préceptes, Qui le cherchent de tout leur coeur,"}, {"numero": 3, "texto": "Qui ne commettent point d''''iniquité, Et qui marchent dans ses voies!"}, {"numero": 4, "texto": "Tu as prescrit tes ordonnances, Pour qu''''on les observe avec soin."}, {"numero": 5, "texto": "Puissent mes actions être bien réglées, Afin que je garde tes statuts!"}, {"numero": 6, "texto": "Alors je ne rougirai point, A la vue de tous tes commandements."}, {"numero": 7, "texto": "Je te louerai dans la droiture de mon coeur, En apprenant les lois de ta justice."}, {"numero": 8, "texto": "Je veux garder tes statuts: Ne m''''abandonne pas entièrement!"}, {"numero": 9, "texto": "Comment le jeune homme rendra-t-il pur son sentier? En se dirigeant d''''après ta parole."}, {"numero": 10, "texto": "Je te cherche de tout mon coeur: Ne me laisse pas égarer loin de tes commandements!"}, {"numero": 11, "texto": "Je serre ta parole dans mon coeur, Afin de ne pas pécher contre toi."}, {"numero": 12, "texto": "Béni sois-tu, ô Eternel! Enseigne-moi tes statuts!"}, {"numero": 13, "texto": "De mes lèvres j''''énumère Toutes les sentences de ta bouche."}, {"numero": 14, "texto": "Je me réjouis en suivant tes préceptes, Comme si je possédais tous les trésors."}, {"numero": 15, "texto": "Je médite tes ordonnances, J''''ai tes sentiers sous les yeux."}, {"numero": 16, "texto": "Je fais mes délices de tes statuts, Je n''''oublie point ta parole."}, {"numero": 17, "texto": "Fais du bien à ton serviteur, pour que je vive Et que j''''observe ta parole!"}, {"numero": 18, "texto": "Ouvre mes yeux, pour que je contemple Les merveilles de ta loi!"}, {"numero": 19, "texto": "Je suis un étranger sur la terre: Ne me cache pas tes commandements!"}, {"numero": 20, "texto": "Mon âme est brisée par le désir Qui toujours la porte vers tes lois."}, {"numero": 21, "texto": "Tu menaces les orgueilleux, ces maudits, Qui s''''égarent loin de tes commandements."}, {"numero": 22, "texto": "Décharge-moi de l''''opprobre et du mépris! Car j''''observe tes préceptes."}, {"numero": 23, "texto": "Des princes ont beau s''''asseoir et parler contre moi, Ton serviteur médite tes statuts."}, {"numero": 24, "texto": "Tes préceptes font mes délices, Ce sont mes conseillers."}, {"numero": 25, "texto": "Mon âme est attachée à la poussière: Rends-moi la vie selon ta parole!"}, {"numero": 26, "texto": "Je raconte mes voies, et tu m''''exauces: Enseigne-moi tes statuts!"}, {"numero": 27, "texto": "Fais-moi comprendre la voie de tes ordonnances, Et je méditerai sur tes merveilles!"}, {"numero": 28, "texto": "Mon âme pleure de chagrin: Relève-moi selon ta parole!"}, {"numero": 29, "texto": "Eloigne de moi la voie du mensonge, Et accorde-moi la grâce de suivre ta loi!"}, {"numero": 30, "texto": "Je choisis la voie de la vérité, Je place tes lois sous mes yeux."}, {"numero": 31, "texto": "Je m''''attache à tes préceptes: Eternel, ne me rends point confus!"}, {"numero": 32, "texto": "Je cours dans la voie de tes commandements, Car tu élargis mon coeur."}, {"numero": 33, "texto": "Enseigne-moi, Eternel, la voie de tes statuts, pour que je la retienne jusqu''''à la fin!"}, {"numero": 34, "texto": "Donne-moi l''''intelligence, pour que je garde ta loi Et que je l''''observe de tout mon coeur!"}, {"numero": 35, "texto": "Conduis-moi dans le sentier de tes commandements! Car je l''''aime."}, {"numero": 36, "texto": "Incline mon coeur vers tes préceptes, Et non vers le gain!"}, {"numero": 37, "texto": "Détourne mes yeux de la vue des choses vaines, Fais-moi vivre dans ta voie!"}, {"numero": 38, "texto": "Accomplis envers ton serviteur ta promesse, Qui est pour ceux qui te craignent!"}, {"numero": 39, "texto": "Eloigne de moi l''''opprobre que je redoute! Car tes jugements sont pleins de bonté."}, {"numero": 40, "texto": "Voici, je désire pratiquer tes ordonnances: Fais-moi vivre dans ta justice!"}, {"numero": 41, "texto": "Eternel, que ta miséricorde vienne sur moi, Ton salut selon ta promesse!"}, {"numero": 42, "texto": "Et je pourrai répondre à celui qui m''''outrage, Car je me confie en ta parole."}, {"numero": 43, "texto": "N''''ôte pas entièrement de ma bouche la parole de la vérité! Car j''''espère en tes jugements."}, {"numero": 44, "texto": "Je garderai ta loi constamment, A toujours et à perpétuité."}, {"numero": 45, "texto": "Je marcherai au large, Car je recherche tes ordonnances."}, {"numero": 46, "texto": "Je parlerai de tes préceptes devant les rois, Et je ne rougirai point."}, {"numero": 47, "texto": "Je fais mes délices de tes commandements. Je les aime."}, {"numero": 48, "texto": "Je lève mes mains vers tes commandements que j''''aime, Et je veux méditer tes statuts."}, {"numero": 49, "texto": "Souviens-toi de ta promesse à ton serviteur, Puisque tu m''''as donné l''''espérance!"}, {"numero": 50, "texto": "C''''est ma consolation dans ma misère, Car ta promesse me rend la vie."}, {"numero": 51, "texto": "Des orgueilleux me chargent de railleries; Je ne m''''écarte point de ta loi."}, {"numero": 52, "texto": "Je pense à tes jugements d''''autrefois, ô Eternel! Et je me console."}, {"numero": 53, "texto": "Une colère ardente me saisit à la vue des méchants Qui abandonnent ta loi."}, {"numero": 54, "texto": "Tes statuts sont le sujet de mes cantiques, Dans la maison où je suis étranger."}, {"numero": 55, "texto": "La nuit je me rappelle ton nom, ô Eternel! Et je garde ta loi."}, {"numero": 56, "texto": "C''''est là ce qui m''''est propre, Car j''''observe tes ordonnances."}, {"numero": 57, "texto": "Ma part, ô Eternel! je le dis, C''''est de garder tes paroles."}, {"numero": 58, "texto": "Je t''''implore de tout mon coeur: Aie pitié de moi, selon ta promesse!"}, {"numero": 59, "texto": "Je réfléchis à mes voies, Et je dirige mes pieds vers tes préceptes."}, {"numero": 60, "texto": "Je me hâte, je ne diffère point D''''observer tes commandements."}, {"numero": 61, "texto": "Les pièges des méchants m''''environnent; Je n''''oublie point ta loi."}, {"numero": 62, "texto": "Au milieu de la nuit je me lève pour te louer, A cause des jugements de ta justice."}, {"numero": 63, "texto": "Je suis l''''ami de tous ceux qui te craignent, Et de ceux qui gardent tes ordonnances."}, {"numero": 64, "texto": "La terre, ô Eternel! est pleine de ta bonté; Enseigne-moi tes statuts!"}, {"numero": 65, "texto": "Tu fais du bien à ton serviteur, O Eternel! selon ta promesse."}, {"numero": 66, "texto": "Enseigne-moi le bon sens et l''''intelligence! Car je crois à tes commandements."}, {"numero": 67, "texto": "Avant d''''avoir été humilié, je m''''égarais; Maintenant j''''observe ta parole."}, {"numero": 68, "texto": "Tu es bon et bienfaisant; Enseigne-moi tes statuts!"}, {"numero": 69, "texto": "Des orgueilleux imaginent contre moi des faussetés; Moi, je garde de tout mon coeur tes ordonnances."}, {"numero": 70, "texto": "Leur coeur est insensible comme la graisse; Moi, je fais mes délices de ta loi."}, {"numero": 71, "texto": "Il m''''est bon d''''être humilié, Afin que j''''apprenne tes statuts."}, {"numero": 72, "texto": "Mieux vaut pour moi la loi de ta bouche Que mille objets d''''or et d''''argent."}, {"numero": 73, "texto": "Tes mains m''''ont créé, elles m''''ont formé; Donne-moi l''''intelligence, pour que j''''apprenne tes commandements!"}, {"numero": 74, "texto": "Ceux qui te craignent me voient et se réjouissent, Car j''''espère en tes promesses."}, {"numero": 75, "texto": "Je sais, ô Eternel! que tes jugements sont justes; C''''est par fidélité que tu m''''as humilié."}, {"numero": 76, "texto": "Que ta bonté soit ma consolation, Comme tu l''''as promis à ton serviteur!"}, {"numero": 77, "texto": "Que tes compassions viennent sur moi, pour que je vive! Car ta loi fait mes délices."}, {"numero": 78, "texto": "Qu''''ils soient confondus, les orgueilleux qui m''''oppriment sans cause! Moi, je médite sur tes ordonnances."}, {"numero": 79, "texto": "Qu''''ils reviennent à moi, ceux qui te craignent, Et ceux qui connaissent tes préceptes!"}, {"numero": 80, "texto": "Que mon coeur soit sincère dans tes statuts, Afin que je ne sois pas couvert de honte!"}, {"numero": 81, "texto": "Mon âme languit après ton salut; J''''espère en ta promesse."}, {"numero": 82, "texto": "Mes yeux languissent après ta promesse; Je dis: Quand me consoleras-tu?"}, {"numero": 83, "texto": "Car je suis comme une outre dans la fumée; Je n''''oublie point tes statuts."}, {"numero": 84, "texto": "Quel est le nombre des jours de ton serviteur? Quand feras-tu justice de ceux qui me persécutent?"}, {"numero": 85, "texto": "Des orgueilleux creusent des fosses devant moi; Ils n''''agissent point selon ta loi."}, {"numero": 86, "texto": "Tous tes commandements ne sont que fidélité; Ils me persécutent sans cause: secours-moi!"}, {"numero": 87, "texto": "Ils ont failli me terrasser et m''''anéantir; Et moi, je n''''abandonne point tes ordonnances."}, {"numero": 88, "texto": "Rends-moi la vie selon ta bonté, Afin que j''''observe les préceptes de ta bouche!"}, {"numero": 89, "texto": "A toujours, ô Eternel! Ta parole subsiste dans les cieux."}, {"numero": 90, "texto": "De génération en génération ta fidélité subsiste; Tu as fondé la terre, et elle demeure ferme."}, {"numero": 91, "texto": "C''''est d''''après tes lois que tout subsiste aujourd''''hui, Car toutes choses te sont assujetties."}, {"numero": 92, "texto": "Si ta loi n''''eût fait mes délices, J''''eusse alors péri dans ma misère."}, {"numero": 93, "texto": "Je n''''oublierai jamais tes ordonnances, Car c''''est par elles que tu me rends la vie."}, {"numero": 94, "texto": "Je suis à toi: sauve-moi! Car je recherche tes ordonnances."}, {"numero": 95, "texto": "Des méchants m''''attendent pour me faire périr; Je suis attentif à tes préceptes."}, {"numero": 96, "texto": "Je vois des bornes à tout ce qui est parfait: Tes commandements n''''ont point de limite."}, {"numero": 97, "texto": "Combien j''''aime ta loi! Elle est tout le jour l''''objet de ma méditation."}, {"numero": 98, "texto": "Tes commandements me rendent plus sage que mes ennemis, Car je les ai toujours avec moi."}, {"numero": 99, "texto": "Je suis plus instruit que tous mes maîtres, Car tes préceptes sont l''''objet de ma méditation."}, {"numero": 100, "texto": "J''''ai plus d''''intelligence que les vieillards, Car j''''observe tes ordonnances."}, {"numero": 101, "texto": "Je retiens mon pied loin de tout mauvais chemin, Afin de garder ta parole."}, {"numero": 102, "texto": "Je ne m''''écarte pas de tes lois, Car c''''est toi qui m''''enseignes."}, {"numero": 103, "texto": "Que tes paroles sont douces à mon palais, Plus que le miel à ma bouche!"}, {"numero": 104, "texto": "Par tes ordonnances je deviens intelligent, Aussi je hais toute voie de mensonge."}, {"numero": 105, "texto": "Ta parole est une lampe à mes pieds, Et une lumière sur mon sentier."}, {"numero": 106, "texto": "Je jure, et je le tiendrai, D''''observer les lois de ta justice."}, {"numero": 107, "texto": "Je suis bien humilié: Eternel, rends-moi la vie selon ta parole!"}, {"numero": 108, "texto": "Agrée, ô Eternel! les sentiments que ma bouche exprime, Et enseigne-moi tes lois!"}, {"numero": 109, "texto": "Ma vie est continuellement exposée, Et je n''''oublie point ta loi."}, {"numero": 110, "texto": "Des méchants me tendent des pièges, Et je ne m''''égare pas loin de tes ordonnances."}, {"numero": 111, "texto": "Tes préceptes sont pour toujours mon héritage, Car ils sont la joie de mon coeur."}, {"numero": 112, "texto": "J''''incline mon coeur à pratiquer tes statuts, Toujours, jusqu''''à la fin."}, {"numero": 113, "texto": "Je hais les hommes indécis, Et j''''aime ta loi."}, {"numero": 114, "texto": "Tu es mon asile et mon bouclier; J''''espère en ta promesse."}, {"numero": 115, "texto": "Eloignez-vous de moi, méchants, Afin que j''''observe les commandements de mon Dieu!"}, {"numero": 116, "texto": "Soutiens-moi selon ta promesse, afin que je vive, Et ne me rends point confus dans mon espérance!"}, {"numero": 117, "texto": "Sois mon appui, pour que je sois sauvé, Et que je m''''occupe sans cesse de tes statuts!"}, {"numero": 118, "texto": "Tu méprises tous ceux qui s''''écartent de tes statuts, Car leur tromperie est sans effet."}, {"numero": 119, "texto": "Tu enlèves comme de l''''écume tous les méchants de la terre; C''''est pourquoi j''''aime tes préceptes."}, {"numero": 120, "texto": "Ma chair frissonne de l''''effroi que tu m''''inspires, Et je crains tes jugements."}, {"numero": 121, "texto": "J''''observe la loi et la justice: Ne m''''abandonne pas à mes oppresseurs!"}, {"numero": 122, "texto": "Prends sous ta garantie le bien de ton serviteur, Ne me laisse pas opprimer par des orgueilleux!"}, {"numero": 123, "texto": "Mes yeux languissent après ton salut, Et après la promesse de ta justice."}, {"numero": 124, "texto": "Agis envers ton serviteur selon ta bonté, Et enseigne-moi tes statuts!"}, {"numero": 125, "texto": "Je suis ton serviteur: donne-moi l''''intelligence, Pour que je connaisse tes préceptes!"}, {"numero": 126, "texto": "Il est temps que l''''Eternel agisse: Ils transgressent ta loi."}, {"numero": 127, "texto": "C''''est pourquoi j''''aime tes commandements, Plus que l''''or et que l''''or fin;"}, {"numero": 128, "texto": "C''''est pourquoi je trouve justes toutes tes ordonnances, Je hais toute voie de mensonge."}, {"numero": 129, "texto": "Tes préceptes sont admirables: Aussi mon âme les observe."}, {"numero": 130, "texto": "La révélation de tes paroles éclaire, Elle donne de l''''intelligence aux simples."}, {"numero": 131, "texto": "J''''ouvre la bouche et je soupire, Car je suis avide de tes commandements."}, {"numero": 132, "texto": "Tourne vers moi ta face, et aie pitié de moi, Selon ta coutume à l''''égard de ceux qui aiment ton nom!"}, {"numero": 133, "texto": "Affermis mes pas dans ta parole, Et ne laisse aucune iniquité dominer sur moi!"}, {"numero": 134, "texto": "Délivre-moi de l''''oppression des hommes, Afin que je garde tes ordonnances!"}, {"numero": 135, "texto": "Fais luire ta face sur ton serviteur, Et enseigne-moi tes statuts!"}, {"numero": 136, "texto": "Mes yeux répandent des torrents d''''eaux, Parce qu''''on n''''observe point ta loi."}, {"numero": 137, "texto": "Tu es juste, ô Eternel! Et tes jugements sont équitables;"}, {"numero": 138, "texto": "Tu fondes tes préceptes sur la justice Et sur la plus grande fidélité."}, {"numero": 139, "texto": "Mon zèle me consume, Parce que mes adversaires oublient tes paroles."}, {"numero": 140, "texto": "Ta parole est entièrement éprouvée, Et ton serviteur l''''aime."}, {"numero": 141, "texto": "Je suis petit et méprisé; Je n''''oublie point tes ordonnances."}, {"numero": 142, "texto": "Ta justice est une justice éternelle, Et ta loi est la vérité."}, {"numero": 143, "texto": "La détresse et l''''angoisse m''''atteignent: Tes commandements font mes délices."}, {"numero": 144, "texto": "Tes préceptes sont éternellement justes: Donne-moi l''''intelligence, pour que je vive!"}, {"numero": 145, "texto": "Je t''''invoque de tout mon coeur: exauce-moi, Eternel, Afin que je garde tes statuts!"}, {"numero": 146, "texto": "Je t''''invoque: sauve-moi, Afin que j''''observe tes préceptes!"}, {"numero": 147, "texto": "Je devance l''''aurore et je crie; J''''espère en tes promesses."}, {"numero": 148, "texto": "Je devance les veilles et j''''ouvre les yeux, Pour méditer ta parole."}, {"numero": 149, "texto": "Ecoute ma voix selon ta bonté! Rends-moi la vie selon ton jugement!"}, {"numero": 150, "texto": "Ils s''''approchent, ceux qui poursuivent le crime, Ils s''''éloignent de la loi."}, {"numero": 151, "texto": "Tu es proche, ô Eternel! Et tous tes commandements sont la vérité."}, {"numero": 152, "texto": "Dès longtemps je sais par tes préceptes Que tu les as établis pour toujours."}, {"numero": 153, "texto": "Vois ma misère, et délivre-moi! Car je n''''oublie point ta loi."}, {"numero": 154, "texto": "Défends ma cause, et rachète-moi; Rends-moi la vie selon ta promesse!"}, {"numero": 155, "texto": "Le salut est loin des méchants, Car ils ne recherchent pas tes statuts."}, {"numero": 156, "texto": "Tes compassions sont grandes, ô Eternel! Rends-moi la vie selon tes jugements!"}, {"numero": 157, "texto": "Mes persécuteurs et mes adversaires sont nombreux; Je ne m''''écarte point de tes préceptes,"}, {"numero": 158, "texto": "Je vois avec dégoût des traîtres Qui n''''observent pas ta parole."}, {"numero": 159, "texto": "Considère que j''''aime tes ordonnances: Eternel, rends-moi la vie selon ta bonté!"}, {"numero": 160, "texto": "Le fondement de ta parole est la vérité, Et toutes les lois de ta justice sont éternelles."}, {"numero": 161, "texto": "Des princes me persécutent sans cause; Mais mon coeur ne tremble qu''''à tes paroles."}, {"numero": 162, "texto": "Je me réjouis de ta parole, Comme celui qui trouve un grand butin."}, {"numero": 163, "texto": "Je hais, je déteste le mensonge; J''''aime ta loi."}, {"numero": 164, "texto": "Sept fois le jour je te célèbre, A cause des lois de ta justice."}, {"numero": 165, "texto": "Il y a beaucoup de paix pour ceux qui aiment ta loi, Et il ne leur arrive aucun malheur."}, {"numero": 166, "texto": "J''''espère en ton salut, ô Eternel! Et je pratique tes commandements."}, {"numero": 167, "texto": "Mon âme observe tes préceptes, Et je les aime beaucoup."}, {"numero": 168, "texto": "Je garde tes ordonnances et tes préceptes, Car toutes mes voies sont devant toi."}, {"numero": 169, "texto": "Que mon cri parvienne jusqu''''à toi, ô Eternel! Donne-moi l''''intelligence, selon ta promesse!"}, {"numero": 170, "texto": "Que ma supplication arrive jusqu''''à toi! Délivre-moi, selon ta promesse!"}, {"numero": 171, "texto": "Que mes lèvres publient ta louange! Car tu m''''enseignes tes statuts."}, {"numero": 172, "texto": "Que ma langue chante ta parole! Car tous tes commandements sont justes."}, {"numero": 173, "texto": "Que ta main me soit en aide! Car j''''ai choisi tes ordonnances."}, {"numero": 174, "texto": "Je soupire après ton salut, ô Eternel! Et ta loi fait mes délices."}, {"numero": 175, "texto": "Que mon âme vive et qu''''elle te loue! Et que tes jugements me soutiennent!"}, {"numero": 176, "texto": "Je suis errant comme une brebis perdue; cherche ton serviteur, Car je n''''oublie point tes commandements."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 119, 'es', '[{"numero": 1, "texto": "ALEPH. BIENAVENTURADOS los perfectos de camino; los que andan en la ley de Jehová."}, {"numero": 2, "texto": "Bienaventurados los que guardan sus testimonios, y con todo el corazón le buscan:"}, {"numero": 3, "texto": "Pues no hacen iniquidad los que andan en sus caminos."}, {"numero": 4, "texto": "Tú encargaste que sean muy guardados tus mandamientos."}, {"numero": 5, "texto": "¡Ojalá fuesen ordenados mis caminos á observar tus estatutos!"}, {"numero": 6, "texto": "Entonces no sería yo avergonzado, cuando atendiese á todos tus mandamientos."}, {"numero": 7, "texto": "Te alabaré con rectitud de corazón, cuando aprendiere los juicios de tu justicia."}, {"numero": 8, "texto": "Tus estatutos guardaré: no me dejes enteramente."}, {"numero": 9, "texto": "BETH ¿Con qué limpiará el joven su camino? Con guardar tu palabra."}, {"numero": 10, "texto": "Con todo mi corazón te he buscado: no me dejes divagar de tus mandamientos."}, {"numero": 11, "texto": "En mi corazón he guardado tus dichos, para no pecar contra ti."}, {"numero": 12, "texto": "Bendito tú, oh Jehová: enséñame tus estatutos."}, {"numero": 13, "texto": "Con mis labios he contado todos los juicios de tu boca."}, {"numero": 14, "texto": "Heme gozado en el camino de tus testimonios, como sobre toda riqueza."}, {"numero": 15, "texto": "En tus mandamientos meditaré, consideraré tus caminos."}, {"numero": 16, "texto": "Recrearéme en tus estatutos: no me olvidaré de tus palabras."}, {"numero": 17, "texto": "GIMEL. Haz bien á tu siervo; que viva y guarde tu palabra."}, {"numero": 18, "texto": "Abre mis ojos, y miraré las maravillas de tu ley."}, {"numero": 19, "texto": "Advenedizo soy yo en la tierra: no encubras de mí tus mandamientos."}, {"numero": 20, "texto": "Quebrantada está mi alma de desear tus juicios en todo tiempo."}, {"numero": 21, "texto": "Destruiste á los soberbios malditos, que se desvían de tus mandamientos."}, {"numero": 22, "texto": "Aparta de mí oprobio y menosprecio; porque tus testimonios he guardado."}, {"numero": 23, "texto": "Príncipes también se sentaron y hablaron contra mí: mas tu siervo meditaba en tus estatutos."}, {"numero": 24, "texto": "Pues tus testimonios son mis deleites, y mis consejeros."}, {"numero": 25, "texto": "DALETH. Pegóse al polvo mi alma: vivifícame según tu palabra."}, {"numero": 26, "texto": "Mis caminos te conté, y me has respondido: enséñame tus estatutos."}, {"numero": 27, "texto": "Hazme entender el camino de tus mandamientos, y hablaré de tus maravillas."}, {"numero": 28, "texto": "Deshácese mi alma de ansiedad: corrobórame según tu palabra."}, {"numero": 29, "texto": "Aparta de mí camino de mentira; y hazme la gracia de tu ley."}, {"numero": 30, "texto": "Escogí el camino de la verdad; he puesto tus juicios delante de mí."}, {"numero": 31, "texto": "Allegádome he á tus testimonios; oh Jehová, no me avergüences."}, {"numero": 32, "texto": "Por el camino de tus mandamientos correré, cuando ensanchares mi corazón."}, {"numero": 33, "texto": "HE. Enséñame, oh Jehová, el camino de tus estatutos, y guardarélo hasta el fin."}, {"numero": 34, "texto": "Dame entendimiento, y guardaré tu ley; y la observaré de todo corazón."}, {"numero": 35, "texto": "Guíame por la senda de tus mandamientos; porque en ella tengo mi voluntad."}, {"numero": 36, "texto": "Inclina mi corazón á tus testimonios, y no á la avaricia."}, {"numero": 37, "texto": "Aparta mis ojos, que no vean la vanidad; avívame en tu camino."}, {"numero": 38, "texto": "Confirma tu palabra á tu siervo, que te teme."}, {"numero": 39, "texto": "Quita de mí el oprobio que he temido: porque buenos son tus juicios."}, {"numero": 40, "texto": "He aquí yo he codiciado tus mandamientos: vivifícame en tu justicia."}, {"numero": 41, "texto": "VAU. Y venga á mí tu misericordia, oh Jehová; tu salud, conforme á tu dicho."}, {"numero": 42, "texto": "Y daré por respuesta á mi avergonzador, que en tu palabra he confiado."}, {"numero": 43, "texto": "Y no quites de mi boca en ningún tiempo la palabra de verdad; porque á tu juicio espero."}, {"numero": 44, "texto": "Y guardaré tu ley siempre, por siglo de siglo."}, {"numero": 45, "texto": "Y andaré en anchura, porque busqué tus mandamientos."}, {"numero": 46, "texto": "Y hablaré de tus testimonios delante de los reyes, y no me avergonzaré."}, {"numero": 47, "texto": "Y deleitaréme en tus mandamientos, que he amado."}, {"numero": 48, "texto": "Alzaré asimismo mis manos á tus mandamientos, que amé; y meditaré en tus estatutos."}, {"numero": 49, "texto": "ZAIN. Acuérdate de la palabra dada á tu siervo, en la cual me has hecho esperar."}, {"numero": 50, "texto": "Esta es mi consuelo en mi aflicción: porque tu dicho me ha vivificado."}, {"numero": 51, "texto": "Los soberbios se burlaron mucho de mí: mas no me he apartado de tu ley."}, {"numero": 52, "texto": "Acordéme, oh Jehová, de tus juicios antiguos, y consoléme."}, {"numero": 53, "texto": "Horror se apoderó de mí, á causa de los impíos que dejan tu ley."}, {"numero": 54, "texto": "Cánticos me fueron tus estatutos en la mansión de mis peregrinaciones."}, {"numero": 55, "texto": "Acordéme en la noche de tu nombre, oh Jehová, y guardé tu ley."}, {"numero": 56, "texto": "Esto tuve, porque guardaba tus mandamientos."}, {"numero": 57, "texto": "CHETH. Mi porción, oh Jehová, dije, será guardar tus palabras."}, {"numero": 58, "texto": "Tu presencia supliqué de todo corazón: ten misericordia de mí según tu palabra."}, {"numero": 59, "texto": "Consideré mis caminos, y torné mis pies á tus testimonios."}, {"numero": 60, "texto": "Apresuréme, y no me retardé en guardar tus mandamientos."}, {"numero": 61, "texto": "Compañías de impíos me han robado: mas no me he olvidado de tu ley."}, {"numero": 62, "texto": "A media noche me levantaba á alabarte sobre los juicios de tu justicia."}, {"numero": 63, "texto": "Compañero soy yo de todos los que te temieren y guardaren tus mandamientos."}, {"numero": 64, "texto": "De tu misericordia, oh Jehová, está llena la tierra: enséñame tus estatutos."}, {"numero": 65, "texto": "TETH. Bien has hecho con tu siervo, oh Jehová, conforme á tu palabra."}, {"numero": 66, "texto": "Enséñame bondad de sentido y sabiduría; porque tus mandamientos he creído."}, {"numero": 67, "texto": "Antes que fuera yo humillado, descarriado andaba; mas ahora guardo tu palabra."}, {"numero": 68, "texto": "Bueno eres tú, y bienhechor: enséñame tus estatutos."}, {"numero": 69, "texto": "Contra mí forjaron mentira los soberbios: mas yo guardaré de todo corazón tus mandamientos."}, {"numero": 70, "texto": "Engrasóse el corazón de ellos como sebo; mas yo en tu ley me he deleitado."}, {"numero": 71, "texto": "Bueno me es haber sido humillado, para que aprenda tus estatutos."}, {"numero": 72, "texto": "Mejor me es la ley de tu boca, que millares de oro y plata."}, {"numero": 73, "texto": "JOD. Tus manos me hicieron y me formaron: hazme entender, y aprenderé tus mandamientos."}, {"numero": 74, "texto": "Los que te temen, me verán, y se alegrarán; porque en tu palabra he esperado."}, {"numero": 75, "texto": "Conozco, oh Jehová, que tus juicios son justicia, y que conforme á tu fidelidad me afligiste."}, {"numero": 76, "texto": "Sea ahora tu misericordia para consolarme, conforme á lo que has dicho á tu siervo."}, {"numero": 77, "texto": "Vengan á mí tus misericordias, y viva; porque tu ley es mi deleite."}, {"numero": 78, "texto": "Sean avergonzados los soberbios, porque sin causa me han calumniado: yo empero, meditaré en tus mandamientos."}, {"numero": 79, "texto": "Tórnense á mí los que te temen y conocen tus testimonios."}, {"numero": 80, "texto": "Sea mi corazón íntegro en tus estatutos; porque no sea yo avergonzado."}, {"numero": 81, "texto": "CAPH. Desfallece mi alma por tu salud, esperando en tu palabra."}, {"numero": 82, "texto": "Desfallecieron mis ojos por tu palabra, diciendo: ¿Cuándo me consolarás?"}, {"numero": 83, "texto": "Porque estoy como el odre al humo; mas no he olvidado tus estatutos."}, {"numero": 84, "texto": "¿Cuántos son los días de tu siervo? ¿cuándo harás juicio contra los que me persiguen?"}, {"numero": 85, "texto": "Los soberbios me han cavado hoyos; mas no obran según tu ley."}, {"numero": 86, "texto": "Todos tus mandamientos son verdad: sin causa me persiguen; ayúdame."}, {"numero": 87, "texto": "Casi me han echado por tierra: mas yo no he dejado tus mandamientos."}, {"numero": 88, "texto": "Vivifícame conforme á tu misericordia; y guardaré los testimonios de tu boca."}, {"numero": 89, "texto": "LAMED. Para siempre, oh Jehová, permanece tu palabra en los cielos."}, {"numero": 90, "texto": "Por generación y generación es tu verdad: tú afirmaste la tierra, y persevera."}, {"numero": 91, "texto": "Por tu ordenación perseveran hasta hoy las cosas criadas; porque todas ellas te sirven."}, {"numero": 92, "texto": "Si tu ley no hubiese sido mis delicias, ya en mi aflicción hubiera perecido."}, {"numero": 93, "texto": "Nunca jamás me olvidaré de tus mandamientos; porque con ellos me has vivificado."}, {"numero": 94, "texto": "Tuyo soy yo, guárdame; porque he buscado tus mandamientos."}, {"numero": 95, "texto": "Los impíos me han aguardado para destruirme: mas yo entenderé en tus testimonios."}, {"numero": 96, "texto": "A toda perfección he visto fin: ancho sobremanera es tu mandamiento."}, {"numero": 97, "texto": "MEM ¡Cuánto amo yo tu ley! todo el día es ella mi meditación."}, {"numero": 98, "texto": "Me has hecho más sabio que mis enemigos con tus mandamientos; porque me son eternos."}, {"numero": 99, "texto": "Más que todos mis enseñadores he entendido: porque tus testimonios son mi meditación."}, {"numero": 100, "texto": "Más que los viejos he entendido, porque he guardado tus mandamientos."}, {"numero": 101, "texto": "De todo mal camino contuve mis pies, para guardar tu palabra."}, {"numero": 102, "texto": "No me aparté de tus juicios; porque tú me enseñaste."}, {"numero": 103, "texto": "¡Cuán dulces son á mi paladar tus palabras! más que la miel á mi boca."}, {"numero": 104, "texto": "De tus mandamientos he adquirido inteligencia: por tanto he aborrecido todo camino de mentira."}, {"numero": 105, "texto": "NUN. Lámpara es á mis pies tu palabra, y lumbrera á mi camino."}, {"numero": 106, "texto": "Juré y ratifiqué el guardar los juicios de tu justicia."}, {"numero": 107, "texto": "Afligido estoy en gran manera: oh Jehová, vivifícame conforme á tu palabra."}, {"numero": 108, "texto": "Ruégote, oh Jehová, te sean agradables los sacrificios voluntarios de mi boca; y enséñame tus juicios."}, {"numero": 109, "texto": "De continuo está mi alma en mi mano: mas no me he olvidado de tu ley."}, {"numero": 110, "texto": "Pusiéronme lazo los impíos: empero yo no me desvié de tus mandamientos."}, {"numero": 111, "texto": "Por heredad he tomado tus testimonios para siempre; porque son el gozo de mi corazón."}, {"numero": 112, "texto": "Mi corazón incliné á poner por obra tus estatutos de continuo, hasta el fin."}, {"numero": 113, "texto": "SAMECH. Los pensamientos vanos aborrezco; mas amo tu ley."}, {"numero": 114, "texto": "Mi escondedero y mi escudo eres tú: en tu palabra he esperado."}, {"numero": 115, "texto": "Apartaos de mí, malignos; pues yo guardaré los mandamientos de mi Dios."}, {"numero": 116, "texto": "Susténtame conforme á tu palabra, y viviré: y no me avergüences de mi esperanza."}, {"numero": 117, "texto": "Sostenme, y seré salvo; y deleitaréme siempre en tus estatutos."}, {"numero": 118, "texto": "Hollaste á todos los que se desvían de tus estatutos: porque mentira es su engaño."}, {"numero": 119, "texto": "Como escorias hiciste consumir á todos los impíos de la tierra: por tanto yo he amado tus testimonios."}, {"numero": 120, "texto": "Mi carne se ha extremecido por temor de ti; y de tus juicios tengo miedo."}, {"numero": 121, "texto": "AIN. Juicio y justicia he hecho; no me dejes á mis opresores."}, {"numero": 122, "texto": "Responde por tu siervo para bien: no me hagan violencia los soberbios."}, {"numero": 123, "texto": "Mis ojos desfallecieron por tu salud, y por el dicho de tu justicia."}, {"numero": 124, "texto": "Haz con tu siervo según tu misericordia, y enséñame tus estatutos."}, {"numero": 125, "texto": "Tu siervo soy yo, dame entendimiento; para que sepa tus testimonios."}, {"numero": 126, "texto": "Tiempo es de hacer, oh Jehová; disipado han tu ley."}, {"numero": 127, "texto": "Por eso he amado tus mandamientos más que el oro, y más que oro muy puro."}, {"numero": 128, "texto": "Por eso todos los mandamientos de todas las cosas estimé rectos: aborrecí todo camino de mentira."}, {"numero": 129, "texto": "PE. Maravillosos son tus testimonios: por tanto los ha guardado mi alma."}, {"numero": 130, "texto": "El principio de tus palabras alumbra; hace entender á los simples."}, {"numero": 131, "texto": "Mi boca abrí y suspiré; porque deseaba tus mandamientos."}, {"numero": 132, "texto": "Mírame, y ten misericordia de mí, como acostumbras con los que aman tu nombre."}, {"numero": 133, "texto": "Ordena mis pasos con tu palabra; y ninguna iniquidad se enseñoree de mí."}, {"numero": 134, "texto": "Redímeme de la violencia de los hombres; y guardaré tus mandamientos."}, {"numero": 135, "texto": "Haz que tu rostro resplandezca sobre tu siervo; y enséñame tus estatutos."}, {"numero": 136, "texto": "Ríos de agua descendieron de mis ojos, porque no guardaban tu ley."}, {"numero": 137, "texto": "TZADDI. Justo eres tú, oh Jehová, y rectos tus juicios."}, {"numero": 138, "texto": "Tus testimonios, que has recomendado, son rectos y muy fieles."}, {"numero": 139, "texto": "Mi celo me ha consumido; porque mis enemigos se olvidaron de tus palabras."}, {"numero": 140, "texto": "Sumamente acendrada es tu palabra; y la ama tu siervo."}, {"numero": 141, "texto": "Pequeño soy yo y desechado; mas no me he olvidado de tus mandamientos."}, {"numero": 142, "texto": "Tu justicia es justicia eterna, y tu ley la verdad."}, {"numero": 143, "texto": "Aflicción y angustia me hallaron: mas tus mandamientos fueron mis deleites."}, {"numero": 144, "texto": "Justicia eterna son tus testimonios; dame entendimiento, y viviré."}, {"numero": 145, "texto": "COPH. Clamé con todo mi corazón; respóndeme, Jehová, y guardaré tus estatutos."}, {"numero": 146, "texto": "A ti clamé; sálvame, y guardaré tus testimonios."}, {"numero": 147, "texto": "Anticipéme al alba, y clamé: esperé en tu palabra."}, {"numero": 148, "texto": "Previnieron mis ojos las vigilias de la noche, para meditar en tus dichos."}, {"numero": 149, "texto": "Oye mi voz conforme á tu misericordia; oh Jehová, vivifícame conforme á tu juicio."}, {"numero": 150, "texto": "Acercáronse á la maldad los que me persiguen; alejáronse de tu ley."}, {"numero": 151, "texto": "Cercano estás tú, oh Jehová; y todos tus mandamientos son verdad."}, {"numero": 152, "texto": "Ya ha mucho que he entendido de tus mandamientos, que para siempre los fundaste."}, {"numero": 153, "texto": "RESH. Mira mi aflicción, y líbrame; porque de tu ley no me he olvidado."}, {"numero": 154, "texto": "Aboga mi causa, y redímeme: vivifícame con tu dicho."}, {"numero": 155, "texto": "Lejos está de los impíos la salud; porque no buscan tus estatutos."}, {"numero": 156, "texto": "Muchas son tus misericordias, oh Jehová: vivifícame conforme á tus juicios."}, {"numero": 157, "texto": "Muchos son mis perseguidores y mis enemigos; mas de tus testimonios no me he apartado."}, {"numero": 158, "texto": "Veía á los prevaricadores, y carcomíame; porque no guardaban tus palabras."}, {"numero": 159, "texto": "Mira, oh Jehová, que amo tus mandamientos: vivifícame conforme á tu misericordia."}, {"numero": 160, "texto": "El principio de tu palabra es verdad; y eterno es todo juicio de tu justicia."}, {"numero": 161, "texto": "SIN. Príncipes me han perseguido sin causa; mas mi corazón tuvo temor de tus palabras."}, {"numero": 162, "texto": "Gózome yo en tu palabra, como el que halla muchos despojos."}, {"numero": 163, "texto": "La mentira aborrezco y abomino: tu ley amo."}, {"numero": 164, "texto": "Siete veces al día te alabo sobre los juicios de tu justicia."}, {"numero": 165, "texto": "Mucha paz tienen los que aman tu ley; y no hay para ellos tropiezo."}, {"numero": 166, "texto": "Tu salud he esperado, oh Jehová; y tus mandamientos he puesto por obra."}, {"numero": 167, "texto": "Mi alma ha guardado tus testimonios, y helos amado en gran manera."}, {"numero": 168, "texto": "Guardado he tus mandamientos y tus testimonios; porque todos mis caminos están delante de ti."}, {"numero": 169, "texto": "TAU. Acérquese mi clamor delante de ti, oh Jehová: dame entendimiento conforme á tu palabra."}, {"numero": 170, "texto": "Venga mi oración delante de ti: líbrame conforme á tu dicho."}, {"numero": 171, "texto": "Mis labios rebosarán alabanza, cuando me enseñares tus estatutos."}, {"numero": 172, "texto": "Hablará mi lengua tus dichos; porque todos tus mandamientos son justicia."}, {"numero": 173, "texto": "Sea tu mano en mi socorro; porque tus mandamientos he escogido."}, {"numero": 174, "texto": "Deseado he tu salud, oh Jehová; y tu ley es mi delicia."}, {"numero": 175, "texto": "Viva mi alma y alábete; y tus juicios me ayuden."}, {"numero": 176, "texto": "Yo anduve errante como oveja extraviada; busca á tu siervo; porque no me he olvidado de tus mandamientos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 121, 'pt', '[{"numero": 1, "texto": "Cântico dos degraus: Levanto meus olhos aos montes. De onde virá meu socorro?"}, {"numero": 2, "texto": "Meu socorro [vem] do SENHOR, que fez os céus e a terra."}, {"numero": 3, "texto": "Ele não deixará o teu pé se abalar, nem cochilará o teu guardião."}, {"numero": 4, "texto": "Eis que não cochilará nem dormirá o Guardião de Israel."}, {"numero": 5, "texto": "O SENHOR é o teu guardião; o SENHOR é a sombra à tua direita."}, {"numero": 6, "texto": "O sol não te ferirá durante o dia, nem a lua durante a noite."}, {"numero": 7, "texto": "O SENHOR te guardará de todo mal; ele guardará a tua alma."}, {"numero": 8, "texto": "O SENHOR guardará tua saída e tua entrada, desde agora e para sempre."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 121, 'en', '[{"numero": 1, "texto": "I will lift up mine eyes unto the hills, from whence cometh my help."}, {"numero": 2, "texto": "My help cometh from the Lord, which made heaven and earth."}, {"numero": 3, "texto": "He will not suffer thy foot to be moved: he that keepeth thee will not slumber."}, {"numero": 4, "texto": "Behold, he that keepeth Israel shall neither slumber nor sleep."}, {"numero": 5, "texto": "The Lord is thy keeper: the Lord is thy shade upon thy right hand."}, {"numero": 6, "texto": "The sun shall not smite thee by day, nor the moon by night."}, {"numero": 7, "texto": "The Lord shall preserve thee from all evil: he shall preserve thy soul."}, {"numero": 8, "texto": "The Lord shall preserve thy going out and thy coming in from this time forth, and even for evermore."}]'::jsonb, 'King James Version'),
  ('Sl', 121, 'fr', '[{"numero": 1, "texto": "Cantique des degrés. Je lève mes yeux vers les montagnes... D''''où me viendra le secours?"}, {"numero": 2, "texto": "Le secours me vient de l''''Eternel, Qui a fait les cieux et la terre."}, {"numero": 3, "texto": "Il ne permettra point que ton pied chancelle; Celui qui te garde ne sommeillera point."}, {"numero": 4, "texto": "Voici, il ne sommeille ni ne dort, Celui qui garde Israël."}, {"numero": 5, "texto": "L''''Eternel est celui qui te garde, L''''Eternel est ton ombre à ta main droite."}, {"numero": 6, "texto": "Pendant le jour le soleil ne te frappera point, Ni la lune pendant la nuit."}, {"numero": 7, "texto": "L''''Eternel te gardera de tout mal, Il gardera ton âme;"}, {"numero": 8, "texto": "L''''Eternel gardera ton départ et ton arrivée, Dès maintenant et à jamais."}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 121, 'es', '[{"numero": 1, "texto": "ALZARÉ mis ojos á los montes, de donde vendrá mi socorro."}, {"numero": 2, "texto": "Mi socorro viene de Jehová, que hizo los cielos y la tierra."}, {"numero": 3, "texto": "No dará tu pie al resbaladero; ni se dormirá el que te guarda."}, {"numero": 4, "texto": "He aquí, no se adormecerá ni dormirá el que guarda á Israel."}, {"numero": 5, "texto": "Jehová es tu guardador: Jehová es tu sombra á tu mano derecha."}, {"numero": 6, "texto": "El sol no te fatigará de día, ni la luna de noche."}, {"numero": 7, "texto": "Jehová te guardará de todo mal: él guardará tu alma."}, {"numero": 8, "texto": "Jehová guardará tu salida y tu entrada, desde ahora y para siempre."}]'::jsonb, 'Reina-Valera 1909'),
  ('Sl', 125, 'pt', '[{"numero": 1, "texto": "Os que confiam no SENHOR são como o monte de Sião, que não se abala, [e] permanece para sempre."}, {"numero": 2, "texto": "Assim como montanhas estão ao redor de Jerusalém, assim também o SENHOR está ao redor de seu povo, desde agora para sempre."}, {"numero": 3, "texto": "Porque o cetro da maldade não repousará sobre a sorte dos justos, para que os justos não estendam suas mãos à perversidade."}, {"numero": 4, "texto": "SENHOR, trata bem aos bons, e aos corretos em seus corações."}, {"numero": 5, "texto": "Mas aos que se dirigem a seus caminhos tortuosos, o SENHOR os mandará embora junto com os que praticam perversidade. Paz [seja] sobre Israel."}]'::jsonb, 'Almeida Livre'),
  ('Sl', 125, 'en', '[{"numero": 1, "texto": "They that trust in the Lord shall be as mount Zion, which cannot be removed, but abideth for ever."}, {"numero": 2, "texto": "As the mountains are round about Jerusalem, so the Lord is round about his people from henceforth even for ever."}, {"numero": 3, "texto": "For the rod of the wicked shall not rest upon the lot of the righteous; lest the righteous put forth their hands unto iniquity."}, {"numero": 4, "texto": "Do good, O Lord, unto those that be good, and to them that are upright in their hearts."}, {"numero": 5, "texto": "As for such as turn aside unto their crooked ways, the Lord shall lead them forth with the workers of iniquity: but peace shall be upon Israel."}]'::jsonb, 'King James Version'),
  ('Sl', 125, 'fr', '[{"numero": 1, "texto": "Cantique des degrés. Ceux qui se confient en l''''Eternel Sont comme la montagne de Sion: elle ne chancelle point, Elle est affermie pour toujours."}, {"numero": 2, "texto": "Des montagnes entourent Jérusalem; Ainsi l''''Eternel entoure son peuple, Dès maintenant et à jamais."}, {"numero": 3, "texto": "Car le sceptre de la méchanceté ne restera pas sur le lot des justes, Afin que les justes ne tendent pas les mains vers l''''iniquité."}, {"numero": 4, "texto": "Eternel, répands tes bienfaits sur les bons Et sur ceux dont le coeur est droit!"}, {"numero": 5, "texto": "Mais ceux qui s''''engagent dans des voies détournées, Que l''''Eternel les détruise avec ceux qui font le mal! Que la paix soit sur Israël!"}]'::jsonb, 'Louis Segond 1910'),
  ('Sl', 125, 'es', '[{"numero": 1, "texto": "LOS que confían en Jehová son como el monte de Sión, que no deslizará: estará para siempre."}, {"numero": 2, "texto": "Como Jerusalem tiene montes alrededor de ella, así Jehová alrededor de su pueblo desde ahora y para siempre."}, {"numero": 3, "texto": "Porque no reposará la vara de la impiedad sobre la suerte de los justos; porque no extiendan los justos sus manos á la iniquidad."}, {"numero": 4, "texto": "Haz bien, oh Jehová, á los buenos, y á los que son rectos en sus corazones."}, {"numero": 5, "texto": "Mas á los que se apartan tras sus perversidades, Jehová los llevará con los que obran iniquidad: y paz sea sobre Israel."}]'::jsonb, 'Reina-Valera 1909')
